use clap::{Arg, ArgAction, ArgMatches, Command};

pub fn color_arg() -> Arg {
    Arg::new("color")
        .long("color")
        .value_name("COLOR")
        .help("Control colored output: auto, always, never")
        .value_parser(["auto", "always", "never"])
        .default_value("auto")
}
pub fn config_arg() -> Arg {
    Arg::new("config")
        .long("config")
        .value_name("CONFIG")
        .help("Path to configuration file")
        .conflicts_with_all(["no-config", "isolated"])
}
pub fn no_config_arg() -> Arg {
    Arg::new("no-config")
        .long("no-config")
        .help("Ignore all configuration files and use built-in defaults")
        .action(ArgAction::SetTrue)
        .conflicts_with("isolated")
}
pub fn isolated_arg() -> Arg {
    Arg::new("isolated")
        .long("isolated")
        .help("Ignore all configuration files (alias for --no-config)")
        .action(ArgAction::SetTrue)
}
pub fn global_args() -> Vec<Arg> {
    vec![color_arg(), config_arg(), no_config_arg(), isolated_arg()]
}

fn check_command(name: &'static str, about: &'static str) -> Command {
    let mut cmd = Command::new(name).about(about);
    let args: Vec<Arg> = vec![
        Arg::new("fix").short('f').long("fix").help("Fix issues automatically where possible").action(ArgAction::SetTrue),
        Arg::new("diff").long("diff").help("Show diff of what would be fixed instead of fixing files").action(ArgAction::SetTrue),
        Arg::new("check").long("check").help("Exit with code 1 if any formatting changes would be made (for CI)").action(ArgAction::SetTrue),
        Arg::new("list-rules").short('l').long("list-rules").help("List all available rules").action(ArgAction::SetTrue),
        Arg::new("disable").short('d').long("disable").value_name("DISABLE").help("Disable specific rules (comma-separated)"),
        Arg::new("enable").short('e').long("enable").visible_alias("rules").value_name("ENABLE").help("Enable only specific rules (comma-separated)"),
        Arg::new("extend-enable").long("extend-enable").value_name("EXTEND_ENABLE").help("Extend the list of enabled rules (additive with config)"),
        Arg::new("extend-disable").long("extend-disable").value_name("EXTEND_DISABLE").help("Extend the list of disabled rules (additive with config)"),
        Arg::new("exclude").long("exclude").value_name("EXCLUDE").help("Exclude specific files or directories (comma-separated glob patterns)"),
        Arg::new("no-exclude").long("no-exclude").help("Disable all exclude patterns").action(ArgAction::SetTrue),
        Arg::new("include").long("include").value_name("INCLUDE").help("Include only specific files or directories (comma-separated glob patterns)"),
        Arg::new("respect-gitignore").long("respect-gitignore").value_name("RESPECT_GITIGNORE").help("Respect .gitignore files when scanning directories (does not apply to explicitly provided paths)").value_parser(["true", "false"]).num_args(0..=1).require_equals(true).default_missing_value("true"),
        Arg::new("verbose").short('v').long("verbose").help("Show detailed output").action(ArgAction::SetTrue),
        color_arg(),
        Arg::new("profile").long("profile").help("Show profiling information").action(ArgAction::SetTrue),
        config_arg(),
        Arg::new("statistics").long("statistics").help("Show statistics summary of rule violations").action(ArgAction::SetTrue),
        no_config_arg(),
        Arg::new("quiet").short('q').long("quiet").help("Print diagnostics, but nothing else").action(ArgAction::SetTrue),
        isolated_arg(),
        Arg::new("output").short('o').long("output").value_name("OUTPUT").help("Output format: text (default) or json").default_value("text"),
        Arg::new("output-format").long("output-format").value_name("OUTPUT_FORMAT").help("Output format (default: text, or $RUMDL_OUTPUT_FORMAT, or output-format in config)").value_parser(["text", "full", "concise", "grouped", "json", "json-lines", "github", "gitlab", "pylint", "azure", "sarif", "junit"]),
        Arg::new("show-full-path").long("show-full-path").help("Show absolute file paths in output instead of relative paths").action(ArgAction::SetTrue),
        Arg::new("flavor").long("flavor").value_name("FLAVOR").help("Markdown flavor: standard (default), mkdocs, mdx, quarto, or obsidian").value_parser(["standard", "mkdocs", "mdx", "quarto", "obsidian"]),
        Arg::new("stdin").long("stdin").help("Read from stdin instead of files").action(ArgAction::SetTrue),
        Arg::new("stdin-filename").long("stdin-filename").value_name("STDIN_FILENAME").help("Filename to use when reading from stdin (e.g., README.md)"),
        Arg::new("stderr").long("stderr").help("Output diagnostics to stderr instead of stdout").action(ArgAction::SetTrue),
        Arg::new("silent").short('s').long("silent").help("Disable all logging (but still exit with status code upon detecting diagnostics)").action(ArgAction::SetTrue),
        Arg::new("watch").short('w').long("watch").help("Run in watch mode by re-running whenever files change").action(ArgAction::SetTrue),
        Arg::new("force-exclude").long("force-exclude").help("Enforce exclude patterns even for explicitly specified files").action(ArgAction::SetTrue),
        Arg::new("no-cache").long("no-cache").help("Disable caching (re-check all files)").action(ArgAction::SetTrue),
        Arg::new("cache-dir").long("cache-dir").value_name("CACHE_DIR").help("Directory to store cache files (default: .rumdl_cache, or $RUMDL_CACHE_DIR, or cache-dir in config)"),
        Arg::new("fail-on").long("fail-on").value_name("FAIL_ON").help("Exit code behavior: 'any' (default) exits 1 on any violation, 'warning' on warning+error, 'error' only on errors, 'never' always exits 0").value_parser(["any", "warning", "error", "never"]).default_value("any"),
        Arg::new("paths").value_name("PATHS").help("Files or directories to lint (use '-' for stdin)").action(ArgAction::Append).num_args(0..),
    ];
    for a in args { cmd = cmd.arg(a); }
    cmd
}

pub fn build_cli() -> Command {
    let mut root = Command::new("rumdl")
        .version("0.1.13")
        .about("A fast Markdown linter written in Rust (Ru(st) MarkDown Linter)")
        .subcommand_required(true)
        .arg_required_else_help(true);
    for a in global_args() { root = root.arg(a); }

    let check = check_command("check", "Lint Markdown files and print warnings/errors");
    let fmt = check_command("fmt", "Format Markdown files (alias for check --fix)");

    let mut init = Command::new("init").about("Initialize a new configuration file")
        .arg(Arg::new("pyproject").long("pyproject").help("Generate configuration for pyproject.toml instead of .rumdl.toml").action(ArgAction::SetTrue));
    for a in global_args() { init = init.arg(a); }

    let mut rule = Command::new("rule").about("Show information about a rule or list all rules")
        .arg(Arg::new("output-format").short('o').long("output-format").value_name("FORMAT").help("Output format: text, json, or json-lines").default_value("text"))
        .arg(Arg::new("fixable").short('f').long("fixable").help("Filter to only fixable rules").action(ArgAction::SetTrue))
        .arg(Arg::new("category").short('c').long("category").value_name("CATEGORY").help("Filter by category (use --list-categories to see options)"))
        .arg(Arg::new("explain").long("explain").help("Include full documentation in output (for json/json-lines)").action(ArgAction::SetTrue))
        .arg(Arg::new("list-categories").long("list-categories").help("List available categories and exit").action(ArgAction::SetTrue))
        .arg(Arg::new("rule").value_name("RULE").help("Rule name or ID (optional, omit to list all rules)"));
    for a in global_args() { rule = rule.arg(a); }

    let mut explain = Command::new("explain").about("Explain a rule with detailed information and examples")
        .arg(Arg::new("rule").value_name("RULE").help("Rule name or ID to explain").required(true));
    for a in global_args() { explain = explain.arg(a); }

    // config subcommands
    let mut config_get = Command::new("get").about("Query a specific config key (e.g. global.exclude or MD013.line_length)")
        .arg(Arg::new("key").value_name("KEY").help("").required(true));
    for a in global_args() { config_get = config_get.arg(a); }
    let mut config_file = Command::new("file").about("Show the absolute path of the configuration file that was loaded");
    for a in global_args() { config_file = config_file.arg(a); }
    let mut config = Command::new("config").about("Show configuration or query a specific key")
        .arg(Arg::new("defaults").long("defaults").help("Show only the default configuration values").action(ArgAction::SetTrue))
        .arg(Arg::new("no-defaults").long("no-defaults").help("Show only non-default configuration values (exclude defaults)").action(ArgAction::SetTrue))
        .arg(Arg::new("output").long("output").value_name("OUTPUT").help("Output format (e.g. toml, json)"))
        .subcommand(config_get).subcommand(config_file);
    for a in global_args() { config = config.arg(a); }

    let server = Command::new("server").about("Start the Language Server Protocol server")
        .arg(Arg::new("port").long("port").value_name("PORT").help("TCP port to listen on (for debugging)").value_parser(clap::value_parser!(u16)))
        .arg(Arg::new("stdio").long("stdio").help("Use stdio for communication (default)").action(ArgAction::SetTrue))
        .arg(Arg::new("verbose").short('v').long("verbose").help("Enable verbose logging").action(ArgAction::SetTrue))
        .arg(Arg::new("config").short('c').long("config").value_name("CONFIG").help("Path to rumdl configuration file"))
        .arg(color_arg())
        // server's no-config/isolated conflict with each other but not with its -c config
        .arg(Arg::new("no-config").long("no-config").help("Ignore all configuration files and use built-in defaults").action(ArgAction::SetTrue).conflicts_with("isolated"))
        .arg(isolated_arg());

    let mut schema_generate = Command::new("generate").about("Generate/update the JSON schema file");
