pub enum ColorChoice { Auto, Always, Never }

#[derive(Debug, Clone)]
pub struct GlobalOpts {
    pub color: ColorChoice,
    pub color_explicit: bool,
    pub config: Option<String>,
    pub no_config: bool,
}

impl Default for GlobalOpts {
    fn default() -> Self { Self { color: ColorChoice::Auto, color_explicit: false, config: None, no_config: false } }
}

pub fn resolve_global(levels: &[&ArgMatches]) -> GlobalOpts {
    let mut g = GlobalOpts::default();
    for m in levels {
        // color: explicit at this level wins
        if matches!(m.value_source("color"), Some(clap::parser::ValueSource::CommandLine)) {
            if let Some(v) = m.get_one::<String>("color") {
                g.color = match v.as_str() { "always" => ColorChoice::Always, "never" => ColorChoice::Never, _ => ColorChoice::Auto };
                g.color_explicit = true;
            }
        }
        let has_config = m.try_get_one::<String>("config").ok().flatten().is_some();
        if has_config {
            g.config = m.get_one::<String>("config").cloned();
            g.no_config = false;
        }
        let nc = m.try_get_flag("no-config").unwrap_or(false) || m.try_get_flag("isolated").unwrap_or(false);
        if nc {
            g.no_config = true;
            g.config = None;
        }
    }
    g
}
