    for a in global_args() { init = init.arg(a); }

    let mut rule = Command::new("rule").about("Show information about a rule or list all rules")
        .arg(Arg::new("output-format").short('o').long("output-format").value_name("FORMAT").help("Output format: text, json, or json-lines").default_value("text"))
        .arg(Arg::new("fixable").short('f').long("fixable").help("Filter to only fixable rules").action(ArgAction::SetTrue))
        .arg(Arg::new("category").short('c').long("category").value_name("CATEGORY").help("Filter by category (use --list-categories to see options)"))
        .arg(Arg::new("explain").long("explain").help("Include full documentation in output (for json/json-lines)").action(ArgAction::SetTrue))
        .arg(Arg::new("list-categories").long("list-categories").help("List available categories and exit").action(ArgAction::SetTrue))
        .arg(Arg::new("rule").value_name("RULE").help("Rule name or ID (optional, omit to list all rules)"));
    for a in global_args() { rule = rule.arg(a); }

    let mut explain = Command::new("explain").about("Explain a rule with detailed information and examples")
        .arg(Arg::new("rule").value_name("RULE").help("Rule name or ID to explain").required(true));
    for a in global_args() { explain = explain.arg(a); }

    // config subcommands
    let mut config_get = Command::new("get").about("Query a specific config key (e.g. global.exclude or MD013.line_length)")
        .arg(Arg::new("key").value_name("KEY").help("").required(true));
    for a in global_args() { config_get = config_get.arg(a); }
    let mut config_file = Command::new("file").about("Show the absolute path of the configuration file that was loaded");
    for a in global_args() { config_file = config_file.arg(a); }
    let mut config = Command::new("config").about("Show configuration or query a specific key")
        .arg(Arg::new("defaults").long("defaults").help("Show only the default configuration values").action(ArgAction::SetTrue))
        .arg(Arg::new("no-defaults").long("no-defaults").help("Show only non-default configuration values (exclude defaults)").action(ArgAction::SetTrue))
        .arg(Arg::new("output").long("output").value_name("OUTPUT").help("Output format (e.g. toml, json)"))
        .subcommand(config_get).subcommand(config_file);
    for a in global_args() { config = config.arg(a); }

    let server = Command::new("server").about("Start the Language Server Protocol server")
        .arg(Arg::new("port").long("port").value_name("PORT").help("TCP port to listen on (for debugging)").value_parser(clap::value_parser!(u16)))
        .arg(Arg::new("stdio").long("stdio").help("Use stdio for communication (default)").action(ArgAction::SetTrue))
        .arg(Arg::new("verbose").short('v').long("verbose").help("Enable verbose logging").action(ArgAction::SetTrue))
        .arg(Arg::new("config").short('c').long("config").value_name("CONFIG").help("Path to rumdl configuration file"))
        .arg(color_arg())
        // server's no-config/isolated conflict with each other but not with its -c config
        .arg(Arg::new("no-config").long("no-config").help("Ignore all configuration files and use built-in defaults").action(ArgAction::SetTrue).conflicts_with("isolated"))
        .arg(isolated_arg());

    let mut schema_generate = Command::new("generate").about("Generate/update the JSON schema file");
    for a in global_args() { schema_generate = schema_generate.arg(a); }
    let mut schema_check = Command::new("check").about("Check if the schema is up-to-date");
    for a in global_args() { schema_check = schema_check.arg(a); }
    let mut schema_print = Command::new("print").about("Print the schema to stdout");
    for a in global_args() { schema_print = schema_print.arg(a); }
    let mut schema = Command::new("schema").about("Generate or check JSON schema for rumdl.toml")
        .subcommand_required(true).arg_required_else_help(true)
        .subcommand(schema_generate).subcommand(schema_check).subcommand(schema_print);
    for a in global_args() { schema = schema.arg(a); }

    let mut import = Command::new("import").about("Import and convert markdownlint configuration files")
        .arg(Arg::new("file").value_name("FILE").help("Path to markdownlint config file (JSON/YAML)").required(true))
        .arg(Arg::new("output").short('o').long("output").value_name("OUTPUT").help("Output file path (default: .rumdl.toml)"))
        .arg(Arg::new("format").long("format").value_name("FORMAT").help("Output format: toml or json").default_value("toml"))
        .arg(Arg::new("dry-run").long("dry-run").help("Show converted config without writing to file").action(ArgAction::SetTrue));
    for a in global_args() { import = import.arg(a); }

    let mut vscode = Command::new("vscode").about("Install the rumdl VS Code extension")
        .arg(Arg::new("force").long("force").help("Force reinstall the current version even if already installed").action(ArgAction::SetTrue))
        .arg(Arg::new("update").long("update").help("Update to the latest version (only if newer version available)").action(ArgAction::SetTrue))
        .arg(Arg::new("status").long("status").help("Show installation status without installing").action(ArgAction::SetTrue));
    for a in global_args() { vscode = vscode.arg(a); }

    let mut completions = Command::new("completions").about("Generate shell completion scripts")
        .arg(Arg::new("shell").value_name("SHELL").help("Shell to generate completions for (detected from $SHELL if omitted)").value_parser(["bash", "elvish", "fish", "powershell", "zsh"]))
        .arg(Arg::new("list").short('l').long("list").help("List available shells").action(ArgAction::SetTrue));
    for a in global_args() { completions = completions.arg(a); }

    let mut clean = Command::new("clean").about("Clear the cache");
    for a in global_args() { clean = clean.arg(a); }
    let mut version = Command::new("version").about("Show version information");
    for a in global_args() { version = version.arg(a); }

    root.subcommand(check).subcommand(fmt).subcommand(init).subcommand(rule).subcommand(explain)
        .subcommand(config).subcommand(server).subcommand(schema).subcommand(import)
        .subcommand(vscode).subcommand(completions).subcommand(clean).subcommand(version)
}

#[derive(Debug, Clone, PartialEq)]
pub enum ColorChoice { Auto, Always, Never }

#[derive(Debug, Clone)]
pub struct GlobalOpts {
    pub color: ColorChoice,
    pub color_explicit: bool,
    pub config: Option<String>,
    pub no_config: bool,
}

impl Default for GlobalOpts {
    fn default() -> Self { Self { color: ColorChoice::Auto, color_explicit: false, config: None, no_config: false } }
}

pub fn resolve_global(levels: &[&ArgMatches]) -> GlobalOpts {
    let mut g = GlobalOpts::default();
    for m in levels {
        // color: explicit at this level wins
        if matches!(m.value_source("color"), Some(clap::parser::ValueSource::CommandLine)) {
            if let Some(v) = m.get_one::<String>("color") {
                g.color = match v.as_str() { "always" => ColorChoice::Always, "never" => ColorChoice::Never, _ => ColorChoice::Auto };
                g.color_explicit = true;
            }
        }
        let has_config = m.try_get_one::<String>("config").ok().flatten().is_some();
        if has_config {
            g.config = m.get_one::<String>("config").cloned();
            g.no_config = false;
        }
        let nc = m.try_get_flag("no-config").unwrap_or(false) || m.try_get_flag("isolated").unwrap_or(false);
        if nc {
            g.no_config = true;
            g.config = None;
        }
    }
    g
}
