#[derive(Debug, Clone)]
pub struct CodeBlock {
    pub start_line: usize, // 0-based fence start
    pub end_line: Option<usize>, // fence end line index if closed
    pub lang: String,
    pub fence_char: char,
    pub fence_len: usize,
    pub indent: String,
}

pub struct LintContext {
    pub content: String,
    pub lines: Vec<LineInfo>,
    pub flavor: Flavor,
    pub file_path: Option<PathBuf>,
    pub code_blocks: Vec<CodeBlock>,
    pub frontmatter_lines: Option<(usize,usize)>, // inclusive delim lines 0-based
    pub frontmatter_kind: Option<String>, // "yaml","toml","json"
}

pub fn parse_fence_line(line:&str)->Option<(String,char,usize,String)>{
    // returns indent, char, len, info
    let mut chars = line.char_indices().peekable();
    let mut indent_end=0usize; let mut spaces=0usize;
    // allow blockquote markers? handled by caller stripping; here count spaces/tabs
    for (i,c) in line.char_indices() {
        if c==' ' { spaces+=1; indent_end=i+1; if spaces>3 { /* still allow for list contexts; caller decides */ } }
        else if c=='\t' { spaces+=4; indent_end=i+1; }
        else { break; }
    }
    let rest=&line[indent_end..];
    if rest.len()<3 { return None; }
    let fc=rest.chars().next()?;
    if fc!='`' && fc!='~' { return None; }
    let count=rest.chars().take_while(|&c| c==fc).count();
    if count<3 { return None; }
    let info=rest[count..].trim().to_string();
    if fc=='`' && info.contains('`') { return None; }
    Some((line[..indent_end].to_string(), fc, count, info))
}

impl LintContext {
    pub fn new(content:&str, flavor:Flavor, file_path:Option<PathBuf>) -> Self {
        let mut line_ranges: Vec<(usize,usize)> = Vec::new();
        let bytes=content.as_bytes();
        let mut start=0usize;
        for (i,&b) in bytes.iter().enumerate() {
            if b==b'\n' { line_ranges.push((start,i)); start=i+1; }
        }
        if start<bytes.len() { line_ranges.push((start,bytes.len())); }
        if content.is_empty() { /* no lines */ }
        let raw_lines: Vec<&str> = line_ranges.iter().map(|&(s,e)| { let mut sl=&content[s..e]; if sl.ends_with('\r') { /* keep? strip for text but byte_end includes */ } sl }).collect();
        // frontmatter detection
        let mut fm: Option<(usize,usize)> = None; let mut fm_kind: Option<String>=None;
        if !raw_lines.is_empty() {
            let first=raw_lines[0].trim_end_matches('\r');
            if first=="---" {
                for i in 1..raw_lines.len() { let l=raw_lines[i].trim_end_matches('\r'); if l=="---" || l=="..." { fm=Some((0,i)); fm_kind=Some("yaml".into()); break; } }
            } else if first=="+++" {
                for i in 1..raw_lines.len() { let l=raw_lines[i].trim_end_matches('\r'); if l=="+++" { fm=Some((0,i)); fm_kind=Some("toml".into()); break; } }
            } else if first.trim()=="{" {
                // JSON frontmatter: find line that is } at start
                let mut depth=0i32;
                for i in 0..raw_lines.len() { for ch in raw_lines[i].chars() { if ch=='{'{depth+=1} else if ch=='}'{depth-=1} } if i>0 && depth<=0 { fm=Some((0,i)); fm_kind=Some("json".into()); break; } }
            }
        }
        let mut lines: Vec<LineInfo> = line_ranges.iter().map(|&(s,e)| LineInfo{byte_start:s,byte_end:e,in_fenced_code:false,is_fence:false,in_indented_code:false,in_frontmatter:false,is_frontmatter_delim:false}).collect();
        if let Some((a,b))=fm { for i in a..=b { lines[i].in_frontmatter = i>a && i<b; lines[i].is_frontmatter_delim = i==a || i==b; if i>a && i<b { lines[i].in_frontmatter=true; } } }
        // fenced code
        let mut code_blocks=Vec::new();
        let mut current: Option<CodeBlock>=None;
        for idx in 0..raw_lines.len() {
            if lines[idx].in_frontmatter || lines[idx].is_frontmatter_delim { continue; }
            let line=raw_lines[idx].trim_end_matches('\r');
            // strip blockquote prefixes for fence detection
            let stripped = strip_blockquote_prefix(line);
            if let Some(cb)=&current {
                // check close
                if let Some((_ind,fc,cnt,info))=parse_fence_line(stripped) {
                    if fc==cb.fence_char && cnt>=cb.fence_len && info.is_empty() {
                        lines[idx].is_fence=true;
                        let mut done=current.take().unwrap(); done.end_line=Some(idx); code_blocks.push(done); continue;
                    }
                }
                lines[idx].in_fenced_code=true;
            } else {
                if let Some((indent,fc,cnt,info))=parse_fence_line(stripped) {
                    // Don't treat as fence if indented >=4 spaces (indented code) unless stripped from blockquote/list; simplified: spaces count of stripped original indent
                    let indent_spaces: usize = indent.chars().map(|c| if c=='\t'{4}else{1}).sum();
                    if indent_spaces>=4 && stripped==line {
                        // could be list content; allow if previous nonblank is list item? skip heuristic: treat as indented code below
                    } else {
                        lines[idx].is_fence=true;
                        let lang = info.split_whitespace().next().unwrap_or("").to_string();
                        current=Some(CodeBlock{start_line:idx,end_line:None,lang,fence_char:fc,fence_len:cnt,indent});
                        continue;
                    }
                }
            }
        }
        if let Some(cb)=current { code_blocks.push(cb); }
        // indented code heuristic
        let mut prev_blank=true;
        for idx in 0..raw_lines.len() {
            if lines[idx].in_fenced_code || lines[idx].is_fence || lines[idx].in_frontmatter || lines[idx].is_frontmatter_delim { prev_blank = raw_lines[idx].trim().is_empty(); continue; }
            let line=raw_lines[idx].trim_end_matches('\r');
            let is_blank=line.trim().is_empty();
            if is_blank { prev_blank=true; continue; }
            let indent = line.chars().take_while(|c| *c==' '||*c=='\t').map(|c| if c=='\t'{4}else{1}).sum::<usize>();
            if indent>=4 && prev_blank {
                // exclude list items: trimmed starts with list marker and prev lines list? If line after blank is indented list, CommonMark would be a list with indented item? Mark not code if it's a list item line
                let trimmed=line.trim_start();
                if !is_list_item_line(trimmed) { lines[idx].in_indented_code=true; }
            } else if indent>=4 && idx>0 && lines[idx-1].in_indented_code {
                lines[idx].in_indented_code=true;
            }
            if lines[idx].in_indented_code { prev_blank=false; } else { prev_blank=false; }
        }
        Self{ content: content.to_string(), lines, flavor, file_path, code_blocks, frontmatter_lines:fm, frontmatter_kind:fm_kind }
    }
    pub fn line_count(&self)->usize{ self.lines.len() }
    pub fn line(&self, idx:usize)->&str{ let li=&self.lines[idx]; let s=&self.content[li.byte_start..li.byte_end]; s.strip_suffix('\r').unwrap_or(s) }
    pub fn line_raw(&self, idx:usize)->&str{ let li=&self.lines[idx]; &self.content[li.byte_start..li.byte_end] }
    pub fn line_byte_start(&self, idx:usize)->usize{ if idx<self.lines.len(){self.lines[idx].byte_start}else{self.content.len()} }
    pub fn line_byte_end(&self, idx:usize)->usize{ if idx<self.lines.len(){self.lines[idx].byte_end}else{self.content.len()} }
    pub fn char_count(&self, idx:usize)->usize{ self.line(idx).chars().count() }
    pub fn byte_to_line_col(&self, byte:usize)->(usize,usize){
        // returns 1-based line,column(char)
        for (i,li) in self.lines.iter().enumerate() {
            if byte>=li.byte_start && byte<=li.byte_end { let col=self.content[li.byte_start..byte.min(li.byte_end)].chars().count()+1; return (i+1,col); }
        }
        if self.lines.is_empty(){ return (1,1); }
        let last=self.lines.len(); (last, self.line(last-1).chars().count()+1)
    }
    pub fn char_to_byte(&self, line_idx:usize, char_idx:usize)->usize{
        let s=self.line_raw(line_idx);
        let mut b=0usize; let mut c=0usize;
        for ch in s.chars(){ if c>=char_idx{break;} b+=ch.len_utf8(); c+=1; }
        self.lines[line_idx].byte_start+b
    }
    pub fn frontmatter_str(&self)->Option<String>{
        if let Some((a,b))=self.frontmatter_lines { if b>a+1 { let mut parts=Vec::new(); for i in a+1..b{parts.push(self.line(i));} return Some(parts.join("\n")); } else { return Some(String::new()); } }
        None
    }
}

pub fn strip_blockquote_prefix(line:&str)->&str{
    let mut s=line;
    loop {
        let t=s.trim_start_matches(' ');
        // only strip if up to 3 spaces before >
        let spaces=s.len()-t.len();
        if spaces<=3 && t.starts_with('>') { s=&t[1..]; if s.starts_with(' '){ s=&s[1..]; } }
        else { break; }
    }
    s
}

pub fn is_list_item_line(trimmed:&str)->bool{
    let mut chars=trimmed.chars();
    match chars.next(){ Some(c) if c=='-'||c=='+'||c=='*' => { let rest=chars.as_str(); rest.is_empty()||rest.starts_with(' ')||rest.starts_with('\t') }, Some(c) if c.is_ascii_digit() => {
        let mut i=0; for ch in trimmed.chars(){ if ch.is_ascii_digit(){i+=1}else{break;} }
        let rest=&trimmed[i..]; (rest.starts_with(". ")||rest.starts_with(") ")||rest.starts_with(".\t")||rest.starts_with(")\t")||rest=="."||rest==")")
    }, _=>false }
}

/// ranges (char indices) of inline code spans in a line
pub fn code_span_ranges(line:&str)->Vec<(usize,usize)>{
    let chars:Vec<char>=line.chars().collect(); let mut ranges=Vec::new(); let mut i=0usize;
    while i<chars.len(){
        if chars[i]=='`'{
            let mut j=i; while j<chars.len() && chars[j]=='`'{j+=1;}
            let n=j-i; // find closing run of exactly n (CommonMark approx: run length == n)
            let mut k=j; let mut found=None;
            while k<chars.len(){
                if chars[k]=='`'{ let mut k2=k; while k2<chars.len() && chars[k2]=='`'{k2+=1;} if k2-k==n { found=Some((k,k2)); break; } k=k2; } else { k+=1; }
            }
            if let Some((cs,ce))=found { ranges.push((i,ce)); i=ce; } else { i=j; }
        } else { i+=1; }
    }
    ranges
}
pub fn in_code_span(ranges:&[(usize,usize)], char_idx:usize)->bool{ ranges.iter().any(|&(s,e)| char_idx>=s && char_idx<e) }

pub fn char_len(s:&str)->usize{ s.chars().count() }
pub fn byte_idx_of_char(s:&str, char_idx:usize)->usize{ let mut b=0; for (i,ch) in s.chars().enumerate(){ if i>=char_idx{break;} b+=ch.len_utf8(); } b }
EOF
