        ("MD058", vec![("minimum-after", i(1)),("minimum-before", i(1))]),
        ("MD059", vec![("prohibited-texts", arr_str(&["click here","here","link","more"]))]),
        ("MD060", vec![("column-align", s("auto")),("column-align-body", s("auto")),("column-align-header", s("auto")),("enabled", b(false)),("loose-last-column", b(false)),("max-width", i(0)),("style", s("any"))]),
        ("MD061", vec![("case-sensitive", b(true)),("terms", arr_empty())]),
        ("MD063", vec![("enabled", b(false)),("ignore-words", arr_empty()),("lowercase-words", arr_str(&["a","an","and","as","at","but","by","for","from","in","into","nor","of","off","on","or","per","so","the","to","up","via","with","yet"])),("max-level", i(6)),("min-level", i(1)),("preserve-cased-words", b(true)),("style", s("title_case"))]),
        ("MD064", vec![("allow-sentence-double-space", b(false))]),
        ("MD072", vec![("enabled", b(false))]),
        ("MD073", vec![("enabled", b(false)),("enforce-order", b(true)),("indent", i(2)),("max-level", i(4)),("min-level", i(2))]),
    ]
}
pub fn default_for(code:&str, key:&str)->Option<toml::Value>{
    for (c,entries) in default_rule_configs(){ if c==code { for (k,v) in entries { if k==key { return Some(v); } } } }
    None
}
pub fn known_rule_keys(code:&str)->Vec<&'static str>{
    for (c,entries) in default_rule_configs(){ if c==code { return entries.iter().map(|e| e.0).collect(); } }
    vec![]
}

// Levenshtein suggestion
fn lev(a:&str,b:&str)->usize{
    let a:Vec<char>=a.chars().collect(); let b:Vec<char>=b.chars().collect();
    let mut prev:Vec<usize>=(0..=b.len()).collect(); let mut cur=vec![0;b.len()+1];
    for i in 1..=a.len(){ cur[0]=i; for j in 1..=b.len(){ let cost=if a[i-1]==b[j-1]{0}else{1}; cur[j]=std::cmp::min(std::cmp::min(prev[j]+1,cur[j-1]+1),prev[j-1]+cost); } std::mem::swap(&mut prev,&mut cur); }
    prev[b.len()]
}
pub fn suggest_rule(input:&str)->Option<String>{
    let norm=normalize_rule(input);
    let mut best: Option<(usize,String)>=None;
    let mut candidates: Vec<String>=Vec::new();
    for r in RULES { candidates.push(r.code.to_string()); candidates.push(r.name.to_string()); for a in r.aliases{candidates.push(a.to_string());} }
    for c in candidates { let d=lev(&norm,&c); if best.as_ref().map(|(bd,_)| d<*bd).unwrap_or(true) { best=Some((d,c)); } }
    if let Some((d,c))=best { if d<=3 { return Some(c); } }
    None
}
pub fn unknown_rule_msg(context:&str, raw:&str)->String{
    let norm=normalize_rule(raw);
    if let Some(sug)=suggest_rule(raw) { format!("Unknown rule in {context}: {norm} (did you mean: {sug}?)") } else { format!("Unknown rule in {context}: {norm}") }
}

fn to_string_vec(v:&toml::Value)->Option<Vec<String>>{
    if let toml::Value::Array(a)=v { Some(a.iter().filter_map(|x| if let toml::Value::String(s)=x{Some(s.clone())}else{None}).collect()) } else { None }
}

const KNOWN_GLOBAL: &[&str]=&["enable","disable","exclude","include","respect-gitignore","line-length","output-format","fixable","unfixable","flavor","force-exclude","cache-dir","cache"];

fn parse_global_table(table:&toml::map::Map<String,toml::Value>, cfg:&mut Config, unknown:&mut Vec<String>, warn_unknown:bool){
    for (k,v) in table.iter() {
        let nk=norm_key(k);
        if !KNOWN_GLOBAL.contains(&nk.as_str()) { if warn_unknown { unknown.push(k.clone()); } continue; }
        match nk.as_str() {
            "enable"|"disable"|"exclude"|"include"|"fixable"|"unfixable"=>{
                if let Some(vec)=to_string_vec(v){ cfg.global_explicit.insert(nk.clone()); match nk.as_str(){ "enable"=>cfg.global.enable=vec,"disable"=>cfg.global.disable=vec,"exclude"=>cfg.global.exclude=vec,"include"=>cfg.global.include=vec,"fixable"=>cfg.global.fixable=vec,_=>cfg.global.unfixable=vec } }
            },
            "respect-gitignore"=>{ if let toml::Value::Boolean(x)=v{cfg.global.respect_gitignore=*x; cfg.global_explicit.insert(nk);} },
            "line-length"=>{ if let toml::Value::Integer(x)=v{cfg.global.line_length=(*x) as u64; cfg.global_explicit.insert(nk);} },
            "output-format"=>{ if let toml::Value::String(x)=v{cfg.global.output_format=Some(x.clone()); cfg.global_explicit.insert(nk);} },
            "flavor"=>{ if let toml::Value::String(x)=v{ if let Some(f)=Flavor::parse_loose(x){cfg.global.flavor=f; cfg.global_explicit.insert(nk);} } },
            "force-exclude"=>{ if let toml::Value::Boolean(x)=v{cfg.global.force_exclude=*x; cfg.global_explicit.insert(nk);} },
            "cache"=>{ if let toml::Value::Boolean(x)=v{cfg.global.cache=*x; cfg.global_explicit.insert(nk);} },
            "cache-dir"=>{ if let toml::Value::String(x)=v{cfg.global.cache_dir=Some(x.clone()); cfg.global_explicit.insert(nk);} },
            _=>{}
        }
    }
}

fn parse_rule_table(code:&str, table:&toml::map::Map<String,toml::Value>, cfg:&mut Config){
    cfg.rule_sections.insert(code.to_string());
    let entry=cfg.rules.entry(code.to_string()).or_default();
    let tentry=cfg.rule_tables.entry(code.to_string()).or_default();
    for (k,v) in table.iter() {
        let nk=norm_key(k);
        if nk=="severity" { if let toml::Value::String(s)=v { if let Some(sev)=Severity::parse(s){ cfg.severities.insert(code.to_string(),sev); } } continue; }
        if let toml::Value::Table(_)=v { tentry.insert(nk, v.clone()); continue; }
        entry.insert(nk, v.clone());
    }
}
fn parse_per_file_ignores(table:&toml::map::Map<String,toml::Value>, cfg:&mut Config){
    for (k,v) in table.iter(){ if let Some(vec)=to_string_vec(v){ cfg.per_file_ignores.push((k.clone(),vec)); } else if let toml::Value::String(s)=v { cfg.per_file_ignores.push((k.clone(),vec![s.clone()])); } }
}
fn parse_per_file_flavor(table:&toml::map::Map<String,toml::Value>, cfg:&mut Config){
    for (k,v) in table.iter(){ if let toml::Value::String(s)=v{ if let Some(f)=Flavor::parse_strict(s){ cfg.per_file_flavor.push((k.clone(),f)); } } }
}
fn parse_code_block_tools(table:&toml::map::Map<String,toml::Value>, cfg:&mut Config){
    let cbt=&mut cfg.code_block_tools;
    for (k,v) in table.iter(){ let nk=norm_key(k); match nk.as_str(){
        "enabled"=>{ if let toml::Value::Boolean(x)=v{cbt.enabled=*x;} },
        "normalize-language"=>{ if let toml::Value::String(x)=v{cbt.normalize_language=x.clone();} },
        "on-error"=>{ if let toml::Value::String(x)=v{cbt.on_error=x.clone();} },
        "on-missing-language-definition"=>{ if let toml::Value::String(x)=v{cbt.on_missing_language_definition=x.clone();} },
        "on-missing-tool-binary"=>{ if let toml::Value::String(x)=v{cbt.on_missing_tool_binary=x.clone();} },
        "timeout"=>{ if let toml::Value::Integer(x)=v{cbt.timeout=(*x) as u64;} },
        "languages"=>{ if let toml::Value::Table(langs)=v{ for (lang,lv) in langs.iter(){ let mut lt=LangTools{lint:vec![],format:vec![],on_error:None}; if let toml::Value::Table(m)=lv{ for (kk,vv) in m.iter(){ match norm_key(kk).as_str(){ "lint"=>{lt.lint=to_string_vec(vv).unwrap_or_default();}, "format"=>{lt.format=to_string_vec(vv).unwrap_or_default();}, "on-error"=>{ if let toml::Value::String(s)=vv{lt.on_error=Some(s.clone());} }, _=>{} } } } cbt.languages.push((lang.clone(),lt)); } } },
        "language-aliases"=>{ if let toml::Value::Table(m)=v{ for (kk,vv) in m.iter(){ if let toml::Value::String(s)=vv{cbt.language_aliases.push((kk.clone(),s.clone()));} } } },
        "tools"=>{ if let toml::Value::Table(m)=v{ for (kk,vv) in m.iter(){ let mut td=ToolDef{command:vec![],stdin:true,stdout:true,lint_args:vec![],format_args:vec![]}; if let toml::Value::Table(tm)=vv{ for (tk,tv) in tm.iter(){ match norm_key(tk).as_str(){ "command"=>{td.command=to_string_vec(tv).unwrap_or_default();}, "stdin"=>{if let toml::Value::Boolean(x)=tv{td.stdin=*x;}}, "stdout"=>{if let toml::Value::Boolean(x)=tv{td.stdout=*x;}}, "lint-args"=>{td.lint_args=to_string_vec(tv).unwrap_or_default();}, "format-args"=>{td.format_args=to_string_vec(tv).unwrap_or_default();}, _=>{} } } } cbt.tools.push((kk.clone(),td)); } } },
        _=>{}
    } }
}

pub struct LoadResult { pub config: Config }

fn build_warnings(cfg:&mut Config, unknown_globals:&[String], unknown_top:&[String], warning_path:&str, is_pyproject:bool){
    let mut warns: Vec<String>=Vec::new();
    // A rule options
    for (code, map) in cfg.rules.clone().iter() {
        let known=known_rule_keys(code);
        for (k,v) in map.iter() {
            if !known.contains(&k.as_str()) { warns.push(format!("Unknown option for rule {code}: {k}")); }
            else if let Some(def)=default_for(code,k) { let exp=toml_type_str(&def); let got=toml_type_str(v); if exp!=got { warns.push(format!("Type mismatch for {code}.{k}: expected {exp}, got {got}")); } }
        }
    }
    // B unknown globals
    if is_pyproject {
        let mut sorted=unknown_globals.to_vec(); sorted.sort();
        for k in sorted { warns.push(format!("Unknown global option in {warning_path}: {k}")); }
    } else {
        for k in unknown_globals { warns.push(format!("Unknown global option in {warning_path}: {k}")); }
    }
    // C unknown top-level (rumdl toml only)
    if !is_pyproject {
        for k in unknown_top { warns.push(unknown_rule_msg(&format!("{warning_path}"), k).replacen("Unknown rule in ", &format!("Unknown rule in "),1)); }
        // unknown_rule_msg builds "Unknown rule in {context}: ..." context is warning_path, good
    }
    // D enable then disable unknown
    for name in cfg.global.enable.clone() { if resolve_rule(&name).is_none(){ warns.push(unknown_rule_msg("global.enable",&name)); } }
    for name in cfg.global.disable.clone() { if resolve_rule(&name).is_none(){ warns.push(unknown_rule_msg("global.disable",&name)); } }
    cfg.warnings=warns;
}

fn load_toml_table(content:&str, display:&str)->Result<toml::Table,String>{
    match content.parse::<toml::Table>() { Ok(t)=>Ok(t), Err(e)=>Err(format!("Failed to parse config: {display}: Failed to parse TOML: {e}")) }
}

pub fn config_from_toml_table(table:&toml::Table, warning_path:&str, source_label:&str)->Config{
    let mut cfg=Config::default(); cfg.source_label=Some(source_label.to_string());
    let mut unknown_globals:Vec<String>=Vec::new();
    let mut unknown_top:Vec<String>=Vec::new();
    for (k,v) in table.iter() {
        let nk=norm_key(k);
        match nk.as_str() {
            "global"=>{ if let toml::Value::Table(t)=v{ parse_global_table(t,&mut cfg,&mut unknown_globals,true); } },
            "per-file-ignores"=>{ if let toml::Value::Table(t)=v{ parse_per_file_ignores(t,&mut cfg); } },
            "per-file-flavor"=>{ if let toml::Value::Table(t)=v{ parse_per_file_flavor(t,&mut cfg); } },
            "code-block-tools"=>{ if let toml::Value::Table(t)=v{ parse_code_block_tools(t,&mut cfg); } },
            _=>{
                if let Some(info)=resolve_rule(k) {
                    if let toml::Value::Table(t)=v{ parse_rule_table(info.code,t,&mut cfg); } else { cfg.rule_sections.insert(info.code.to_string()); cfg.rules.entry(info.code.to_string()).or_default(); }
                } else { unknown_top.push(k.clone()); }
            }
        }
    }
    build_warnings(&mut cfg,&unknown_globals,&unknown_top,warning_path,false);
    cfg
}

fn pyproject_effective(cfg:&Config)->bool{
    let g=&cfg.global;
    if !g.enable.is_empty()||!g.disable.is_empty()||!g.exclude.is_empty()||!g.include.is_empty()||!g.fixable.is_empty()||!g.unfixable.is_empty() { return true; }
    if !g.respect_gitignore || g.flavor!=Flavor::Standard || g.output_format.is_some() || g.force_exclude || !g.cache || g.cache_dir.is_some() { return true; }
    if cfg.pyproject_line_length.is_some() { return true; }
    if !cfg.per_file_ignores.is_empty()||!cfg.per_file_flavor.is_empty() { return true; }
    if cfg.code_block_tools.enabled || cfg.code_block_tools.normalize_language!="linguist" || cfg.code_block_tools.on_error!="fail" || cfg.code_block_tools.on_missing_language_definition!="ignore" || cfg.code_block_tools.on_missing_tool_binary!="ignore" || cfg.code_block_tools.timeout!=30000 || !cfg.code_block_tools.languages.is_empty() || !cfg.code_block_tools.language_aliases.is_empty() || !cfg.code_block_tools.tools.is_empty() { return true; }
    if !cfg.severities.is_empty() { return true; }
    // any rule raw values
    if cfg.rules.values().any(|m| !m.is_empty()) { return true; }
    false
}

pub fn config_from_pyproject_table(table:&toml::Table, warning_path:&str)->Config{
    let mut cfg=Config::default(); cfg.source_label=Some("pyproject.toml".to_string()); cfg.is_pyproject=true;
    let rumdl = table.get("tool").and_then(|t| if let toml::Value::Table(m)=t{m.get("rumdl")}else{None});
    let rumdl_table = match rumdl { Some(toml::Value::Table(m))=>m.clone(), _=>toml::map::Map::new() };
    let mut unknown_globals:Vec<String>=Vec::new();
    // global subtable first (no unknown warnings)
    if let Some(toml::Value::Table(gt))=rumdl_table.get("global") { let mut dummy=vec![]; parse_global_table(gt,&mut cfg,&mut dummy,false); if let Some(toml::Value::Integer(x))=gt.get("line-length").or_else(|| gt.get("line_length")) { cfg.pyproject_line_length=Some(*x); } }
    // root entries
    for (k,v) in rumdl_table.iter() {
        let nk=norm_key(k);
        match nk.as_str() {
            "global"=> continue,
            "per-file-ignores"=>{ if let toml::Value::Table(t)=v{parse_per_file_ignores(t,&mut cfg);} continue; },
            "per-file-flavor"=>{ if let toml::Value::Table(t)=v{parse_per_file_flavor(t,&mut cfg);} continue; },
            "code-block-tools"=>{ if let toml::Value::Table(t)=v{parse_code_block_tools(t,&mut cfg);} continue; },
            _=>{}
        }
        if let Some(info)=resolve_rule(k) {
            if let toml::Value::Table(t)=v{ parse_rule_table(info.code,t,&mut cfg); }
            continue;
        }
        if KNOWN_GLOBAL.contains(&nk.as_str()) {
            // parse single global entry via a temp table
            let mut tmp=toml::map::Map::new(); tmp.insert(k.clone(),v.clone());
            let mut dummy=vec![]; parse_global_table(&tmp,&mut cfg,&mut dummy,false);
            if nk=="line-length" { if let toml::Value::Integer(x)=v{ cfg.pyproject_line_length=Some(*x); } }
        } else {
            unknown_globals.push(k.clone());
        }
    }
    // line-length special insert MD013 if not present
    if let Some(ll)=cfg.pyproject_line_length {
        let has=cfg.rules.get("MD013").map(|m| m.contains_key("line-length")).unwrap_or(false);
        if !has { cfg.rule_sections.insert("MD013".to_string()); cfg.rules.entry("MD013".to_string()).or_default().insert("line-length".to_string(), toml::Value::Integer(ll)); }
    }
    build_warnings(&mut cfg,&unknown_globals,&[],warning_path,true);
    cfg
}

// markdownlint conversion (used for JSON/YAML config load and import command)
pub fn markdownlint_to_config(map:&serde_json::Map<String,serde_json::Value>)->Config{
    // Convert JSON-like map (from json/yaml via serde_json value) to Config using import logic (shared in import module via toml generation?)
    // Implemented in import_convert.rs through a callback; here we do a direct conversion mirroring observed behavior.
    crate::import_convert::convert_map_to_config(map)
}

pub fn load_config_file(path:&Path, display_for_error:&str, warning_path:&str)->Result<Config,String>{
    let content=std::fs::read_to_string(path).map_err(|e| format!("Failed to read config file at {display_for_error}: {e}"))?;
    let file_name=path.file_name().and_then(|s| s.to_str()).unwrap_or("");
    let ext=path.extension().and_then(|s| s.to_str()).unwrap_or("");
    if file_name=="pyproject.toml" {
        let table=load_toml_table(&content, display_for_error)?;
        let mut cfg=config_from_pyproject_table(&table, warning_path);
        if pyproject_effective(&cfg) { cfg.loaded_path=Some(std::fs::canonicalize(path).unwrap_or(path.to_path_buf())); }
        return Ok(cfg);
    }
    if ext=="json" {
        let parsed: Result<std::collections::HashMap<String,serde_json::Value>,_>=serde_json::from_str(&content);
        let map_obj = match parsed { Ok(m)=>{ let mut mo=serde_json::Map::new(); // ordering from HashMap lossy; reparse as Value to preserve order for rules sorting later (BTree in config anyway)
            if let Ok(serde_json::Value::Object(o))=serde_json::from_str::<serde_json::Value>(&content){ o } else { for (k,v) in m{mo.insert(k,v);} mo } }, Err(e)=>{ return Err(format!("Failed to parse config: {display_for_error}: Failed to parse JSON: {e}")); } };
        let mut cfg=markdownlint_to_config(&map_obj);
        cfg.loaded_path=Some(std::fs::canonicalize(path).unwrap_or(path.to_path_buf()));
        cfg.source_label=Some("project config".to_string());
        cfg.warning_path=Some(warning_path.to_string());
        return Ok(cfg);
    }
    if ext=="yaml"||ext=="yml" {
        let parsed: Result<std::collections::HashMap<String,serde_yaml::Value>,_>=serde_yaml::from_str(&content);
        match parsed { Err(e)=>{ return Err(format!("Failed to parse config: {display_for_error}: Failed to parse YAML: {e}")); }, Ok(_)=>{
            // reparse to serde_json value via yaml value conversion
            let yv: serde_yaml::Value=serde_yaml::from_str(&content).map_err(|e| format!("Failed to parse config: {display_for_error}: Failed to parse YAML: {e}"))?;
            let jv=yaml_to_json(&yv);
            let map_obj=if let serde_json::Value::Object(o)=jv{o}else{serde_json::Map::new()};
            let mut cfg=markdownlint_to_config(&map_obj);
            cfg.loaded_path=Some(std::fs::canonicalize(path).unwrap_or(path.to_path_buf()));
            cfg.source_label=Some("project config".to_string());
            cfg.warning_path=Some(warning_path.to_string());
            return Ok(cfg);
        } }
    }
    // TOML
    let table=load_toml_table(&content, display_for_error)?;
    let mut cfg=config_from_toml_table(&table, warning_path, "project config");
    cfg.loaded_path=Some(std::fs::canonicalize(path).unwrap_or(path.to_path_buf()));
    cfg.warning_path=Some(warning_path.to_string());
    Ok(cfg)
}

pub fn yaml_to_json(v:&serde_yaml::Value)->serde_json::Value{
    match v {
        serde_yaml::Value::Null=>serde_json::Value::Null,
        serde_yaml::Value::Bool(b)=>serde_json::Value::Bool(*b),
        serde_yaml::Value::Number(n)=>{ if let Some(i)=n.as_i64(){serde_json::Value::Number(i.into())} else if let Some(u)=n.as_u64(){serde_json::Value::Number(u.into())} else if let Some(f)=n.as_f64(){ serde_json::Number::from_f64(f).map(serde_json::Value::Number).unwrap_or(serde_json::Value::Null)} else {serde_json::Value::Null} },
        serde_yaml::Value::String(s)=>serde_json::Value::String(s.clone()),
        serde_yaml::Value::Sequence(seq)=>serde_json::Value::Array(seq.iter().map(yaml_to_json).collect()),
        serde_yaml::Value::Mapping(map)=>{ let mut o=serde_json::Map::new(); for (k,val) in map{ let ks=match k{serde_yaml::Value::String(s)=>s.clone(), _=>format!("{:?}",k)}; o.insert(ks,yaml_to_json(val)); } serde_json::Value::Object(o) },
        serde_yaml::Value::Tagged(t)=>yaml_to_json(&t.value),
    }
}

pub enum Discover { Found(PathBuf,String), StopNone, None }

pub fn discover_config(start_dir:&Path)->Discover{
    // start_dir may be relative; iterate with a path that, for first dir, warning path is relative file name construction handled by caller via loaded path relativization
    let mut dirs:Vec<PathBuf>=Vec::new();
    let abs = std::fs::canonicalize(start_dir).unwrap_or_else(|_| { if start_dir.is_absolute(){start_dir.to_path_buf()}else{std::env::current_dir().unwrap_or(PathBuf::from(".")).join(start_dir)} });
    let mut cur: Option<PathBuf>=Some(abs.clone());
    while let Some(dir)=cur {
        dirs.push(dir.clone());
        let is_git_root = dir.join(".git").exists();
        for name in [".rumdl.toml","rumdl.toml"] { let p=dir.join(name); if p.is_file(){ return Discover::Found(p, name.to_string()); } }
        let py=dir.join("pyproject.toml");
        if py.is_file() {
            if let Ok(content)=std::fs::read_to_string(&py) {
                if content.contains("tool.rumdl") {
                    // determine if effective (parse inside load; errors handled by caller returning Found so load errors)
                    // We return Found with a marker; caller load will parse and may turn into None if not effective.
                    // To implement StopNone semantics, caller should treat non-effective pyproject as no config and not continue searching (discovery already stopped).
                    return Discover::Found(py, "pyproject.toml".to_string());
                }
            }
        }
        if is_git_root { break; }
        cur=dir.parent().map(|p| p.to_path_buf());
    }
    Discover::None
}

