{"command":"cat > src/import_convert.rs <<'EOF'
use crate::config::*;
use crate::info::*;
use std::collections::{BTreeMap, HashSet};

#[derive(Debug, Default, Clone)]
pub struct Converted {
    pub enable: Vec<String>,
    pub disable: Vec<String>,
    pub rules: BTreeMap<String, BTreeMap<String, serde_json::Value>>,
}

fn convert_key(k:&str)->String{ k.to_ascii_lowercase().replace('_',"-") }

fn convert_value(v:&serde_json::Value)->Option<serde_json::Value>{
    match v {
        serde_json::Value::Null=>None,
        serde_json::Value::Object(o)=>{
            let mut out=serde_json::Map::new();
            let mut keys: Vec<&String>=o.keys().collect(); keys.sort();
            for k in keys { let cv=convert_value(&o[k])?; out.insert(convert_key(k), cv); }
            Some(serde_json::Value::Object(out))
        },
        serde_json::Value::Array(a)=>{
            let mut out=Vec::new(); for e in a { out.push(convert_value(e)?); } Some(serde_json::Value::Array(out))
        },
        _=>Some(v.clone())
    }
}

pub fn convert_map(map:&serde_json::Map<String,serde_json::Value>)->Converted{
    let mut enable_set: HashSet<String>=HashSet::new();
    let mut disable_set: HashSet<String>=HashSet::new();
    let mut enable: Vec<String>=Vec::new(); let mut disable: Vec<String>=Vec::new();
    let mut rules: BTreeMap<String,BTreeMap<String,serde_json::Value>>=BTreeMap::new();
    for (raw_key, value) in map.iter() {
        let Some(info)=resolve_rule(raw_key) else { continue; };
        let code=info.code;
        match value {
            serde_json::Value::Bool(true)=>{ if enable_set.insert(code.to_string()){ enable.push(code.to_string()); } },
            serde_json::Value::Bool(false)=>{ if disable_set.insert(code.to_string()){ disable.push(code.to_string()); } },
            serde_json::Value::Object(obj)=>{
                // iterate sorted raw keys (BTree behavior)
                let mut keys:Vec<&String>=obj.keys().collect(); keys.sort();
                let mut rule_map:BTreeMap<String,serde_json::Value>=BTreeMap::new();
                let mut failed=false;
                for k in keys {
                    let lk=k.to_ascii_lowercase();
                    if code=="MD013" && (lk=="heading_line_length"||lk=="heading-line-length"||lk=="code_block_line_length"||lk=="code-block-line-length") { continue; }
                    let new_key=if code=="MD013" && lk=="stern" { "strict".to_string() } else { convert_key(k) };
                    match convert_value(&obj[k]) { Some(cv)=>{ rule_map.insert(new_key,cv); }, None=>{ failed=true; break; } }
                }
                if failed { continue; }
                if code=="MD007" && !rule_map.contains_key("style") { rule_map.insert("style".to_string(), serde_json::Value::String("fixed".to_string())); }
                if !rule_map.is_empty() { rules.insert(code.to_string(), rule_map); }
            },
            serde_json::Value::Number(n)=>{
                let mut m=BTreeMap::new();
                if code=="MD013" { m.insert("line-length".to_string(), serde_json::Value::Number(n.clone())); } else { m.insert("value".to_string(), serde_json::Value::Number(n.clone())); }
                rules.insert(code.to_string(),m);
            },
            serde_json::Value::String(_)|serde_json::Value::Array(_)=>{
                if let Some(cv)=convert_value(value){ let mut m=BTreeMap::new(); m.insert("value".to_string(),cv); rules.insert(code.to_string(),m); }
            },
            serde_json::Value::Null=> continue,
        }
    }
    Converted{enable,disable,rules}
}

pub fn json_to_toml(v:&serde_json::Value)->Option<toml::Value>{
    match v {
        serde_json::Value::Null=>None,
        serde_json::Value::Bool(b)=>Some(toml::Value::Boolean(*b)),
        serde_json::Value::Number(n)=>{ if let Some(i)=n.as_i64(){Some(toml::Value::Integer(i))} else if let Some(u)=n.as_u64(){ i64::try_from(u).ok().map(toml::Value::Integer) } else if let Some(f)=n.as_f64(){Some(toml::Value::Float(f))} else {None} },
        serde_json::Value::String(s)=>Some(toml::Value::String(s.clone())),
        serde_json::Value::Array(a)=>{ let mut out=Vec::new(); for e in a{out.push(json_to_toml(e)?);} Some(toml::Value::Array(out)) },
        serde_json::Value::Object(o)=>{ let mut t=toml::map::Map::new(); for (k,val) in o{ t.insert(k.clone(), json_to_toml(val)?); } Some(toml::Value::Table(t)) },
    }
}

pub fn convert_map_to_config(map:&serde_json::Map<String,serde_json::Value>)->Config{
    let conv=convert_map(map);
    let mut cfg=Config::default();
    cfg.source_label=Some("project config".to_string());
    if !conv.enable.is_empty(){ cfg.global.enable=conv.enable.clone(); cfg.global_explicit.insert("enable".into()); }
    if !conv.disable.is_empty(){ cfg.global.disable=conv.disable.clone(); cfg.global_explicit.insert("disable".into()); }
    for (code, entries) in &conv.rules {
        cfg.rule_sections.insert(code.clone());
        let m=cfg.rules.entry(code.clone()).or_default();
        let tm=cfg.rule_tables.entry(code.clone()).or_default();
        for (k,v) in entries {
            if k=="severity" { if let serde_json::Value::String(s)=v{ if let Some(sev)=crate::lint::Severity::parse(s){cfg.severities.insert(code.clone(),sev);} } continue; }
            if let Some(tv)=json_to_toml(v){ if let toml::Value::Table(_)=tv{ tm.insert(k.clone(),tv); } else { m.insert(k.clone(),tv); } }
        }
    }
    // warnings for converted config: original markdownlint auto-load probably does not emit config warnings for unknown keys? Leave empty (probed no warnings on auto load except typed rule factory)
    cfg
}

pub fn converted_to_json_value(conv:&Converted)->serde_json::Value{
    let mut out=serde_json::Map::new();
    if !conv.enable.is_empty() || !conv.disable.is_empty() {
        let mut g=serde_json::Map::new();
        if !conv.enable.is_empty(){ g.insert("enable".into(), serde_json::Value::Array(conv.enable.iter().map(|s| serde_json::Value::String(s.clone())).collect())); }
        if !conv.disable.is_empty(){ g.insert("disable".into(), serde_json::Value::Array(conv.disable.iter().map(|s| serde_json::Value::String(s.clone())).collect())); }
        out.insert("global".into(), serde_json::Value::Object(g));
    }
    for (code,map) in &conv.rules {
        let mut o=serde_json::Map::new(); for (k,v) in map{o.insert(k.clone(),v.clone());} out.insert(code.clone(),serde_json::Value::Object(o));
    }
    serde_json::Value::Object(out)
}

fn fmt_import_value(v:&serde_json::Value)->String{
    match v {
        serde_json::Value::String(s)=>format!("\"{s}\""),
        serde_json::Value::Number(n)=>n.to_string(),
        serde_json::Value::Bool(b)=>b.to_string(),
        serde_json::Value::Array(a)=>{
            let parts:Vec<String>=a.iter().map(|e| match e { serde_json::Value::String(s)=>format!("\"{s}\""), _=> json_to_toml(e).map(|tv| tv.to_string()).unwrap_or_default() }).collect();
            format!("[{}]", parts.join(", "))
        },
        serde_json::Value::Object(_)=>{
            if let Some(toml::Value::Table(t))=json_to_toml(v){ toml::to_string(&t).unwrap_or_default().trim_end().to_string() } else { String::new() }
        },
        serde_json::Value::Null=>String::new(),
    }
}

pub fn converted_to_toml_string(conv:&Converted)->String{
    let mut out=String::new();
    if !conv.enable.is_empty() || !conv.disable.is_empty() {
        out.push_str("[global]\n");
        if !conv.enable.is_empty(){ out.push_str(&format!("enable = [{}]\n", conv.enable.iter().map(|s| format!("\"{s}\"")).collect::<Vec<_>>().join(", "))); }
        if !conv.disable.is_empty(){ out.push_str(&format!("disable = [{}]\n", conv.disable.iter().map(|s| format!("\"{s}\"")).collect::<Vec<_>>().join(", "))); }
        out.push('\n');
    }
    for (code,map) in &conv.rules {
        out.push_str(&format!("[{code}]\n"));
        for (k,v) in map { out.push_str(&format!("{k} = {}\n", fmt_import_value(v))); }
        out.push('\n');
    }
    out
}
EOF
"}

