                    let warn=display_rel_to_cwd(&py);
                    let cfg=load_config_file(&py,&warn,&warn)?;
                    if cfg.loaded_path.is_some(){ if !suppress_config_warnings{print_config_warnings(&cfg);} return Ok(cfg); } else { return Ok(Config::default()); }
                }
            }
        }
    }
    // markdownlint fallback
    for dir in &dirs {
        for name in MARKDOWNLINT_CANDIDATES {
            let p=dir.join(name); if p.is_file(){
                let warn=display_rel_to_cwd(&p);
                match load_config_file(&p,&warn,&warn){ Ok(mut cfg)=>{ cfg.loaded_path=Some(std::fs::canonicalize(&p).unwrap_or(p)); if !suppress_config_warnings{print_config_warnings(&cfg);} return Ok(cfg); }, Err(_)=>{ return Ok(Config::default()); } }
            }
        }
    }
    Ok(Config::default())
}
