            if std::env::var("TERM").map(|v| v=="dumb").unwrap_or(false) { return false; }
            std::io::stdout().is_terminal()
        }
    }
}
pub fn bold(s:&str,color:bool)->String{ if color{format!("\x1b[1m{s}\x1b[0m")}else{s.to_string()} }
