pub fn format_bytes(n:u64)->String{
    if n<1024 { format!("{n} B") } else if n<1024*1024 { format!("{:.2} KB", n as f64/1024.0) } else if n<1024*1024*1024 { format!("{:.2} MB", n as f64/(1024.0*1024.0)) } else { format!("{:.2} GB", n as f64/(1024.0*1024.0*1024.0)) }
}
fn collect_size_count(path:&Path)->(u64,u64){
    // walk following? Use symlink_metadata for entries; if entry is symlink, count as file with len from symlink_metadata (observed)
    let mut size:u64=0; let mut count:u64=0;
    fn walk(p:&Path,size:&mut u64,count:&mut u64){
        let meta=match std::fs::symlink_metadata(p){Ok(m)=>m,Err(_)=>return};
        if meta.file_type().is_symlink() {
            // For top-level cache symlink itself, caller handles separately; nested symlink counted as file
            *size+=meta.len(); *count+=1; return;
        }
        if meta.is_dir(){
            if let Ok(rd)=std::fs::read_dir(p){ for e in rd.flatten(){ walk(&e.path(),size,count); } }
        } else if meta.is_file(){ *size+=meta.len(); *count+=1; }
    }
    // top-level: if symlink to dir, original counted files inside target (observed 1 file 4B) - follow walk through read_dir traversal which follows
    if let Ok(meta)=std::fs::metadata(path){ if meta.is_dir(){ if let Ok(rd)=std::fs::read_dir(path){ for e in rd.flatten(){ walk(&e.path(),&mut size,&mut count); } } }
    (size,count)
}
pub fn cmd_clean(global:&GlobalOpts)->i32{
    // load config from cwd
    let cfg_res=crate::config::load_resolved(global, Path::new("."), false);
    let cfg=match cfg_res{ Ok(c)=>c, Err(e)=>{ eprintln!("Config error: {e}"); return 2; } };
    let (cache_path, display)=resolve_cache_dir(None,&cfg);
    if !cache_path.exists() { println!("No cache found at {display} (nothing to clean)"); return 0; }
    let (size,count)=collect_size_count(&cache_path);
    if count==0 { 
        // empty directory tree: original removes dir tree (?) if it's a dir
        if cache_path.is_dir() && !std::fs::symlink_metadata(&cache_path).map(|m| m.file_type().is_symlink()).unwrap_or(false) { let _=std::fs::remove_dir_all(&cache_path); }
        println!("Cache is empty at {display} (nothing to clean)"); return 0; }
    // remove
    let is_symlink=std::fs::symlink_metadata(&cache_path).map(|m| m.file_type().is_symlink()).unwrap_or(false);
    let res=if is_symlink { std::fs::remove_file(&cache_path) } else if cache_path.is_dir() { std::fs::remove_dir_all(&cache_path) } else { std::fs::remove_file(&cache_path) };
    if let Err(e)=res { eprintln!("Error: Failed to clear cache: {e}"); return 2; }
    println!("Cleared cache: {display}");
    println!("  Removed {} across {} files", format_bytes(size), count);
    0
}
pub fn resolve_cache_dir(cli_cache_dir:Option<&str>, cfg:&Config)->(PathBuf,String){
    let candidate: String = if let Some(s)=cli_cache_dir { s.to_string() } else if let Ok(env)=std::env::var("RUMDL_CACHE_DIR") { env } else if let Some(s)=&cfg.global.cache_dir { s.clone() } else { ".rumdl_cache".to_string() };
    let cand_path=PathBuf::from(&candidate);
    let resolved=if let Some(loaded)=&cfg.loaded_path {
        if cand_path.is_absolute(){ cand_path } else { loaded.parent().unwrap_or(Path::new(".")).join(&cand_path) }
    } else { cand_path };
    let display=resolved.to_string_lossy().to_string();
    (resolved,display)
}

pub fn cmd_vscode(m:&ArgMatches)->i32{
    let status=m.get_flag("status"); let update=m.get_flag("update"); let force=m.get_flag("force");
    // find editor
    let editors=["code","cursor","windsurf","codium","vscodium"];
    let mut editor: Option<String>=None;
    for e in editors {
        let out=std::process::Command::new(e).arg("--version").output();
        if let Ok(o)=out { if o.status.success(){ editor=Some(e.to_string()); break; } }
    }
    let Some(editor)=editor else { eprintln!("Error: VS Code (or compatible editor) not found. Please ensure one of the following commands is available: code, cursor, windsurf, codium, vscodium"); return 2; };
    let list_extensions=|show_versions:bool|->Vec<String>{
        let mut cmd=std::process::Command::new(&editor); cmd.arg("--list-extensions"); if show_versions{cmd.arg("--show-versions");}
        match cmd.output(){ Ok(o)=> String::from_utf8_lossy(&o.stdout).lines().map(|s| s.trim().to_string()).collect(), Err(_)=>vec![] }
    };
    let is_installed=|exts:&Vec<String>| exts.iter().any(|s| s=="rvben.rumdl");
    let get_version=|exts_v:&Vec<String>|->String{
        for s in exts_v { if let Some((name,ver))=s.split_once('@'){ if name=="rvben.rumdl"{ return ver.to_string(); } } }
        "unknown".to_string()
    };
    if status {
        let exts=list_extensions(false);
        if is_installed(&exts){ let v=get_version(&list_extensions(true)); println!("✓ Rumdl VS Code extension is installed"); println!("  Current version: {v}"); } else { println!("✗ Rumdl VS Code extension is not installed"); println!("  Run rumdl vscode to install it"); }
        return 0;
    }
    if update {
        let exts=list_extensions(false);
        if !is_installed(&exts){ println!("✗ Rumdl VS Code extension is not installed"); println!("  Run rumdl vscode to install it"); return 0; }
        let v=get_version(&list_extensions(true));
        println!("Current version: {v}");
        println!("⚠ Unable to check for updates");
        println!("  Unable to check latest version from marketplace");
        println!();
        println!("You can try forcing a reinstall with:");
        println!("  rumdl vscode --force");
        return 0;
    }
    // install path
    if !force {
        let exts=list_extensions(false);
        if is_installed(&exts){ let v=get_version(&list_extensions(true)); println!("✓ Rumdl VS Code extension is already installed"); println!("  Current version: {v}"); return 0; }
        println!("Installing rumdl - Markdown Linter extension...");
        let out=std::process::Command::new(&editor).args(["--install-extension","rvben.rumdl"]).output();
        match out { Ok(o) if o.status.success()=>{ println!("✓ Successfully installed Rumdl VS Code extension!"); let v=get_version(&list_extensions(true)); if v!="unknown" { println!("  Installed version: {v}"); } 0 }, Ok(o)=>{ eprintln!("Error: Failed to install extension: {}", String::from_utf8_lossy(&o.stderr).trim_end_matches('\n')); 2 }, Err(e)=>{ eprintln!("Error: Failed to install extension: {e}"); 2 } }
    } else {
        println!("Force reinstalling rumdl - Markdown Linter extension...");
        let out=std::process::Command::new(&editor).args(["--install-extension","rvben.rumdl","--force"]).output();
        match out { Ok(o) if o.status.success()=>{ println!("✓ Successfully installed Rumdl VS Code extension!"); let v=get_version(&list_extensions(true)); if v!="unknown" { println!("  Installed version: {v}"); } 0 }, Ok(o)=>{ eprintln!("Error: Failed to install extension: {}", String::from_utf8_lossy(&o.stderr).trim_end_matches('\n')); 2 }, Err(e)=>{ eprintln!("Error: Failed to install extension: {e}"); 2 } }
    }
}
EOF
"}

