        println!("  • Run {} to lint your Markdown files", cyan("rumdl check .",color));
        println!("  • Open your editor to see real-time linting");
        return 0;
    }
}

pub fn schema_content()->&'static str{ include_str!("data/schema.json") }
pub fn cmd_schema(sub_name:&str)->i32{
    let schema=schema_content();
    match sub_name {
        "print"=>{ println!("{schema}"); 0 },
        "generate"=>{
            let cwd=std::env::current_dir().unwrap_or(PathBuf::from("."));
            let path=cwd.join("rumdl.schema.json");
            if let Ok(existing)=std::fs::read_to_string(&path){ if existing==schema { println!("Schema is already up-to-date: {}", path.display()); return 0; } }
            match std::fs::write(&path,schema){ Ok(_)=>{ println!("Schema updated: {}", path.display()); 0 }, Err(e)=>{ eprintln!("Error: Failed to write schema file: {e}"); 2 } }
        },
        "check"=>{
            let cwd=std::env::current_dir().unwrap_or(PathBuf::from("."));
            let path=cwd.join("rumdl.schema.json");
            if !path.is_file() { eprintln!("Error: Schema file not found: {}\nRun 'rumdl schema generate' to create it.", path.display()); return 2; }
            match std::fs::read_to_string(&path){ Ok(existing)=>{ if existing==schema{ println!("Schema is up-to-date: {}", path.display()); 0 } else { eprintln!("Error: Schema is out of date: {}\nRun 'rumdl schema generate' to update it.", path.display()); 2 } }, Err(_)=>{ eprintln!("Error: Schema file not found: {}\nRun 'rumdl schema generate' to create it.", path.display()); 2 } }
        },
        _=>2
    }
}

pub fn cmd_completions(m:&ArgMatches)->i32{
    if m.get_flag("list") {
        println!("Available shells:");
        println!("  bash         Bourne Again SHell");
        println!("  zsh          Z shell");
        println!("  fish         Friendly Interactive SHell");
        println!("  powershell   PowerShell");
        println!("  elvish       Elvish shell");
        return 0;
    }
    let shell: Option<String>= if let Some(s)=m.get_one::<String>("shell") { Some(s.clone()) } else {
        std::env::var("SHELL").ok().and_then(|v| { let base=v.rsplit('/').next().unwrap_or("").to_string(); match base.as_str(){ "bash"|"zsh"|"fish"|"elvish"|"powershell"=>Some(base), "pwsh"=>Some("powershell".to_string()), _=>None } })
    };
    let Some(shell)=shell else {
        eprintln!("Error: Could not detect shell from $SHELL environment variable\n\nPlease specify a shell explicitly:\n  rumdl completions bash\n  rumdl completions zsh\n  rumdl completions fish\n  rumdl completions powershell\n  rumdl completions elvish\n\nOr use --list to see all available shells");
        return 2;
    };
    let content: &str = match shell.as_str() {
        "bash"=>include_str!("data/completions/bash.txt"),
