fn print_sections(sections:&Vec<(String,Vec<(String,String,String)>)>, color:bool){
    // compute max len of entry lines "key = value"
    let mut max_len=0usize;
    for (_sec, entries) in sections { for (k,v,_s) in entries { let line=format!("{k} = {v}"); if line.len()>max_len{max_len=line.len();} } }
    for (sec,entries) in sections {
        println!("{:<width$}", format!("[{sec}]"), width=max_len+1);
        for (k,v,s) in entries {
            let line=format!("{k} = {v}");
