        let mut codes:BTreeSet<String>=BTreeSet::new(); for c in cfg.rule_sections.iter(){codes.insert(c.clone());} for c in cfg.rules.keys(){codes.insert(c.clone());} for c in cfg.severities.keys(){codes.insert(c.clone());}
        // Only include codes that are in rule_sections (user) - cfg.rules may have entries from pyproject line-length insert (rule_sections includes)
