    let mut pff=serde_json::Map::new(); for (k,v) in &cfg.per_file_flavor{ pff.insert(k.clone(), serde_json::Value::String(v.as_str().into())); } root.insert("per-file-flavor".into(), serde_json::Value::Object(pff));
    // code block tools
    let mut cbt=serde_json::Map::new();
    cbt.insert("enabled".into(), cfg.code_block_tools.enabled.into());
    cbt.insert("normalize-language".into(), cfg.code_block_tools.normalize_language.clone().into());
    cbt.insert("on-error".into(), cfg.code_block_tools.on_error.clone().into());
    cbt.insert("on-missing-language-definition".into(), cfg.code_block_tools.on_missing_language_definition.clone().into());
    cbt.insert("on-missing-tool-binary".into(), cfg.code_block_tools.on_missing_tool_binary.clone().into());
    cbt.insert("timeout".into(), cfg.code_block_tools.timeout.into());
    let mut langs=serde_json::Map::new(); for (name,lt) in &cfg.code_block_tools.languages{ let mut o=serde_json::Map::new(); o.insert("lint".into(), sarr(&lt.lint)); o.insert("format".into(), sarr(&lt.format)); if let Some(oe)=&lt.on_error{o.insert("on-error".into(), oe.clone().into());} langs.insert(name.clone(), serde_json::Value::Object(o)); } cbt.insert("languages".into(), serde_json::Value::Object(langs));
    let mut la=serde_json::Map::new(); for (k,v) in &cfg.code_block_tools.language_aliases{ la.insert(k.clone(), v.clone().into()); } cbt.insert("language-aliases".into(), serde_json::Value::Object(la));
    let mut tools=serde_json::Map::new(); for (name,td) in &cfg.code_block_tools.tools{ let mut o=serde_json::Map::new(); o.insert("command".into(), sarr(&td.command)); o.insert("stdin".into(), td.stdin.into()); o.insert("stdout".into(), td.stdout.into()); o.insert("lint-args".into(), sarr(&td.lint_args)); o.insert("format-args".into(), sarr(&td.format_args)); tools.insert(name.clone(), serde_json::Value::Object(o)); } cbt.insert("tools".into(), serde_json::Value::Object(tools));
    root.insert("code-block-tools".into(), serde_json::Value::Object(cbt));
