fn json_to_toml_value(v:&serde_json::Value)->Option<toml::Value>{ crate::import_convert::json_to_toml(v) }

pub fn cmd_config_main(cfg:&Config, defaults:bool, no_defaults:bool, output:Option<&str>, color:bool)->i32{
    if defaults && no_defaults { eprintln!("Error: Cannot use both --defaults and --no-defaults flags together"); return 2; }
    // defaults handled by caller passing default cfg for text/json; but include_defaults for json/toml when defaults flag
    if output==Some("json") {
        let v=cfg_to_json(cfg, defaults);
        println!("{}", serde_json::to_string_pretty(&v).unwrap());
        return 0;
    }
    if output==Some("toml") {
        let v=cfg_to_json(cfg, defaults);
        if let Some(toml::Value::Table(t))=json_to_toml_value(&v){ match toml::to_string_pretty(&t){ Ok(s)=>{ print!("{s}"); println!(); }, Err(e)=>{ eprintln!("Error: {e}"); return 2; } } }
        return 0;
    }
    // text
    if no_defaults {
        // Build sections: global only explicit, per-file-ignores, rules user
        let mut sections:Vec<(String,Vec<(String,String,String)>)>=Vec::new();
        let mut g_entries:Vec<(String,String,String)>=Vec::new();
        for (k,v,s) in global_entries(cfg,true){
            // match explicit by key mapping
            let check_key=match k.as_str(){ "respect_gitignore"=>"respect-gitignore","line_length"=>"line-length","force_exclude"=>"force-exclude","output_format"=>"output-format","cache_dir"=>"cache-dir", other=>other };
            if cfg.global_explicit.contains(check_key){ g_entries.push((k,v,s)); }
        }
        if !g_entries.is_empty(){ sections.push(("global".into(),g_entries)); }
        if !cfg.per_file_ignores.is_empty(){
            let mut pfi=cfg.per_file_ignores.clone(); pfi.sort_by(|a,b| a.0.cmp(&b.0));
            let src=cfg.source_label.clone().unwrap_or("project config".into());
            let entries=pfi.iter().map(|(k,v)| (format!("\"{k}\""), format_toml_value(&toml::Value::Array(v.iter().map(|x| toml::Value::String(x.clone())).collect())), src.clone())).collect();
            sections.push(("per-file-ignores".into(),entries));
        }
        for (code,map) in &cfg.rules { if map.is_empty(){continue;} let src=cfg.source_label.clone().unwrap_or("project config".into()); let entries=map.iter().map(|(k,v)| (k.clone(),format_toml_value(v),src.clone())).collect(); sections.push((code.clone(),entries)); }
        if sections.is_empty(){ println!("All configurations are using default values."); return 0; }
        print_sections(&sections,color);
        return 0;
    } else {
        // full
        let mut sections:Vec<(String,Vec<(String,String,String)>)>=Vec::new();
        sections.push(("global".into(), global_entries(cfg,false)));
        // union of default codes and user codes with non-empty raw entries, sorted
        let mut codes:BTreeSet<String>=BTreeSet::new();
        for (c,_) in default_rule_configs(){codes.insert(c.to_string());}
        for (c,m) in &cfg.rules{ if !m.is_empty(){codes.insert(c.clone());} }
        for code in codes {
            if let Some(m)=cfg.rules.get(&code){ if !m.is_empty(){ let src=cfg.source_label.clone().unwrap_or("project config".into()); let entries=m.iter().map(|(k,v)| (k.clone(),format_toml_value(v),src.clone())).collect(); sections.push((code,entries)); continue; } }
            // if user section present but empty -> skip section entirely (observed)
            if cfg.rule_sections.contains(&code){ continue; }
            // default entries if any
            if let Some((_,entries))=default_rule_configs().iter().find(|(c,_)| *c==code){ let e=entries.iter().map(|(k,v)| (k.to_string(),format_toml_value(v),"default".to_string())).collect(); sections.push((code,e)); }
            else if let Some(m)=cfg.rules.get(&code){ if !m.is_empty(){ let src=cfg.source_label.clone().unwrap_or("project config".into()); let entries=m.iter().map(|(k,v)| (k.clone(),format_toml_value(v),src.clone())).collect(); sections.push((code,entries)); } }
        }
        print_sections(&sections,color);
        return 0;
    }
}

pub fn cmd_config_get(cfg:&Config, key:&str)->i32{
    let parts:Vec<&str>=key.splitn(2,'.').collect();
    if parts.len()!=2 || parts[0].is_empty() || parts[1].is_empty() && false { eprintln!("Key must be in the form global.key or MDxxx.key"); return 2; }
    if parts.len()!=2 { eprintln!("Key must be in the form global.key or MDxxx.key"); return 2; }
    let left=parts[0]; let right=parts[1];
    let source_label=cfg.source_label.clone().unwrap_or("project config".to_string());
    let src_explicit=format!("[from {source_label}]");
    if left.eq_ignore_ascii_case("global") {
        let nk=right.to_ascii_lowercase();
        let arr=|v:&Vec<String>| format_toml_value(&toml::Value::Array(v.iter().map(|s| toml::Value::String(s.clone())).collect()));
        let (val, explicit_key): (String,&str) = match nk.as_str() {
            "enable"=>(arr(&cfg.global.enable),"enable"),
            "disable"=>(arr(&cfg.global.disable),"disable"),
            "exclude"=>(arr(&cfg.global.exclude),"exclude"),
            "include"=>(arr(&cfg.global.include),"include"),
            "respect-gitignore"|"respect_gitignore"=>(cfg.global.respect_gitignore.to_string(),"respect-gitignore"),
            "flavor"=>(format!("\"{}\"",cfg.global.flavor.as_str()),"flavor"),
            "output-format"|"output_format"=>{
                if let Some(of)=&cfg.global.output_format{ (format!("\"{of}\""),"output-format") } else { eprintln!("Unknown global key: {right}"); return 2; }
            },
            _=>{ eprintln!("Unknown global key: {right}"); return 2; }
        };
        let src=if cfg.global_explicit.contains(explicit_key){ src_explicit } else { "[from default]".to_string() };
        println!("{key} = {val} {src}");
        return 0;
    } else {
        let code_upper=left.to_ascii_uppercase();
        let key_norm=norm_key(right);
        let normalized=format!("{code_upper}.{key_norm}");
        // user raw first (normalized code)
        if let Some(m)=cfg.rules.get(&code_upper){ if let Some(v)=m.get(&key_norm){ println!("{normalized} = {} {}", format_toml_value(v), src_explicit); return 0; } }
        // default lookup using original left case as key (bug replication)
        if let Some(v)=default_for(left,&key_norm){ println!("{normalized} = {} [from default]", format_toml_value(&v)); return 0; }
        eprintln!("Unknown config key: {normalized}");
        return 2;
    }
}

pub fn cmd_config_file(cfg:&Config, global:&GlobalOpts)->i32{
    if global.no_config { println!("No configuration file loaded (--no-config/--isolated specified)"); return 0; }
    if let Some(p)=&cfg.loaded_path { println!("{}", p.display()); } else { println!("No configuration file found (using defaults)"); }
    0
}
