pub fn parse_markdownlint_file(path:&Path)->Result<serde_json::Map<String,serde_json::Value>,String>{
    let content=std::fs::read_to_string(path).map_err(|e| format!("Failed to read config file {}: {e}", path.display()))?;
    let ext=path.extension().and_then(|s|s.to_str()).unwrap_or("");
    if ext=="json" {
        let parsed:Result<std::collections::HashMap<String,serde_json::Value>,_>=serde_json::from_str(&content);
        match parsed { Err(e)=>Err(format!("Failed to parse JSON: {e}")), Ok(_)=>{
            match serde_json::from_str::<serde_json::Value>(&content){ Ok(serde_json::Value::Object(o))=>Ok(o), Ok(_)=>Err("Failed to parse JSON: expected a map".into()), Err(e)=>Err(format!("Failed to parse JSON: {e}")) }
        } }
    } else if ext=="yaml"||ext=="yml" {
        let parsed:Result<std::collections::HashMap<String,serde_yaml::Value>,_>=serde_yaml::from_str(&content);
        match parsed { Err(e)=>Err(format!("Failed to parse YAML: {e}")), Ok(_)=>{
            if content.trim().is_empty(){ return Ok(serde_json::Map::new()); }
            let yv:serde_yaml::Value=serde_yaml::from_str(&content).map_err(|e| format!("Failed to parse YAML: {e}"))?;
            match crate::config::yaml_to_json(&yv){ serde_json::Value::Object(o)=>Ok(o), _=>Ok(serde_json::Map::new()) }
        } }
    } else {
        // try JSON then YAML, error reports YAML error with generic prefix
        let jparsed:Result<std::collections::HashMap<String,serde_json::Value>,_>=serde_json::from_str(&content);
        if jparsed.is_ok() {
            if let Ok(serde_json::Value::Object(o))=serde_json::from_str::<serde_json::Value>(&content){ return Ok(o); }
        }
        let yparsed:Result<std::collections::HashMap<String,serde_yaml::Value>,_>=serde_yaml::from_str(&content);
        match yparsed { Err(e)=>Err(format!("Failed to parse config as JSON or YAML: {e}")), Ok(_)=>{
            if content.trim().is_empty(){ return Ok(serde_json::Map::new()); }
            let yv:serde_yaml::Value=serde_yaml::from_str(&content).map_err(|e| format!("Failed to parse config as JSON or YAML: {e}"))?;
            match crate::config::yaml_to_json(&yv){ serde_json::Value::Object(o)=>Ok(o), _=>Ok(serde_json::Map::new()) }
        } }
    }
}

pub fn cmd_import(m:&ArgMatches)->i32{
    let file=m.get_one::<String>("file").unwrap();
    let format=m.get_one::<String>("format").map(|s|s.as_str()).unwrap_or("toml");
    if format!="toml" && format!="json" { eprintln!("Error: Unsupported format '{format}'. Use 'toml' or 'json'."); return 2; }
    let map=match parse_markdownlint_file(Path::new(file)){ Ok(m)=>m, Err(e)=>{ eprintln!("Import error: {e}"); return 2; } };
    let conv=crate::import_convert::convert_map(&map);
    let output_str: String = if format=="json" { serde_json::to_string_pretty(&crate::import_convert::converted_to_json_value(&conv)).unwrap() } else { crate::import_convert::converted_to_toml_string(&conv) };
    if m.get_flag("dry-run") { println!("{output_str}"); return 0; }
    let out_path: String = if let Some(o)=m.get_one::<String>("output") { o.clone() } else if format=="json" { "rumdl-config.json".to_string() } else { ".rumdl.toml".to_string() };
    if Path::new(&out_path).exists() { eprintln!("Error: Output file '{out_path}' already exists"); return 2; }
    if let Err(e)=std::fs::write(&out_path,&output_str){ eprintln!("Error: Failed to write output file: {e}"); return 2; }
    println!("Converted markdownlint config from '{file}' to '{out_path}'");
    println!("You can now use: rumdl check --config {out_path} .");
    0
}
EOF
"}

