use clap::ArgMatches;
use std::path::Path;

fn main() {
    let matches = cli::build_cli().get_matches();
    let code = run(&matches);
    std::process::exit(code);
}

fn run(matches: &ArgMatches) -> i32 {
    let (name, sub) = matches.subcommand().unwrap();
    let global = cli::resolve_global(&[matches, sub]);
    match name {
        "version" => { println!("rumdl 0.1.13"); 0 }
        "rule" => commands::cmd_rule(sub),
        "explain" => commands::cmd_explain(sub, &global),
        "init" => commands::cmd_init(sub, &global),
        "completions" => commands::cmd_completions(sub),
        "clean" => commands::cmd_clean(&global),
        "vscode" => commands::cmd_vscode(sub),
        "import" => commands::cmd_import(sub),
        "schema" => {
            let (subname, _subsub) = sub.subcommand().unwrap();
            commands::cmd_schema(subname)
        }
        "config" => {
            // conflict check first (observed even with subcommand)
            let defaults = sub.get_flag("defaults");
            let no_defaults = sub.get_flag("no-defaults");
            if defaults && no_defaults { eprintln!("Error: Cannot use both --defaults and --no-defaults flags together"); return 2; }
            if let Some((subname, subsub)) = sub.subcommand() {
                let g2 = cli::resolve_global(&[matches, sub, subsub]);
                // load config
                let cfg = match load_for_config_cmd(&g2) { Ok(c)=>c, Err(code)=>return code };
                match subname {
                    "get" => {
                        let key = subsub.get_one::<String>("key").unwrap();
                        cmd_config::cmd_config_get(&cfg, key)
                    }
                    "file" => cmd_config::cmd_config_file(&cfg, &g2),
                    _ => 2,
                }
            } else {
                if defaults {
                    let cfg = config::Config::default();
                    let output = sub.get_one::<String>("output").map(|s|s.as_str());
                    let color = util::should_color(&global.color);
                    return cmd_config::cmd_config_main(&cfg, true, false, output, color);
                }
                let cfg = match load_for_config_cmd(&global) { Ok(c)=>c, Err(code)=>return code };
                let output = sub.get_one::<String>("output").map(|s|s.as_str());
                let color = util::should_color(&global.color);
                cmd_config::cmd_config_main(&cfg, false, no_defaults, output, color)
            }
        }
        "check" | "fmt" => {
            eprintln!("check not yet implemented");
            2
        }
        "server" => {
            eprintln!("server not yet implemented");
            2
        }
        _ => 2,
    }
}

fn load_for_config_cmd(global: &cli::GlobalOpts) -> Result<config::Config, i32> {
    match config::load_resolved(global, Path::new("."), false) {
        Ok(c) => Ok(c),
        Err(e) => { eprintln!("Config error: {e}"); Err(2) }
    }
}
