// Two glob semantics observed:
// 1) separator_aware: * and ? do not cross '/', ** as a whole component crosses.
// 2) cross: * and ? match any char including '/' (but [..] class still). ** same as *.
pub fn glob_match_sep(pattern:&str, path:&str)->bool{ glob_match_inner(pattern,path,true) }
pub fn glob_match_cross(pattern:&str, path:&str)->bool{ glob_match_inner(pattern,path,false) }

fn glob_match_inner(pattern:&str, path:&str, sep:bool)->bool{
    let p:Vec<char>=pattern.chars().collect(); let s:Vec<char>=path.chars().collect();
    // Dynamic programming with tokenization
    #[derive(Clone,Debug,PartialEq)]
    enum Tok{ Char(char), Star, RecStar, Qmark, Class(Vec<(char,char)>,bool) }
    let mut toks:Vec<Tok>=Vec::new(); let mut i=0;
    while i<p.len(){
        match p[i]{
            '*'=>{
                if sep {
                    // ** only recursive if whole component: preceded by / or start, followed by / or end, and exactly ** (or more?)
                    let mut j=i; while j<p.len()&&p[j]=='*'{j+=1;}
                    let cnt=j-i;
                    let prev_ok=i==0||p[i-1]=='/';
                    let next_ok=j==p.len()||p[j]=='/';
                    if cnt>=2 && prev_ok && next_ok { toks.push(Tok::RecStar); } else { for _ in 0..cnt{toks.push(Tok::Star);} }
                    i=j;
                } else { toks.push(Tok::RecStar); i+=1; }
            },
            '?'=>{toks.push(Tok::Qmark); i+=1;},
            '['=>{
                let mut j=i+1; let mut neg=false;
                if j<p.len()&&(p[j]=='!'||p[j]=='^'){neg=true;j+=1;}
                let mut ranges=Vec::new(); let mut first=true; let mut ok=false;
                while j<p.len(){
                    if p[j]==']' && !first { ok=true; break; }
                    first=false;
                    if j+2<p.len() && p[j+1]=='-' && p[j+2]!=']' { ranges.push((p[j],p[j+2])); j+=3; } else { ranges.push((p[j],p[j])); j+=1; }
                }
                if ok { toks.push(Tok::Class(ranges,neg)); i=j+1; } else { toks.push(Tok::Char('[')); i+=1; }
            },
            '\\' if i+1<p.len()=>{ toks.push(Tok::Char(p[i+1])); i+=2; },
            c=>{toks.push(Tok::Char(c)); i+=1;}
        }
    }
    // DP over tokens and string
    let nt=toks.len(); let ns=s.len();
    let mut dp=vec![vec![false;ns+1];nt+1]; dp[0][0]=true;
    // handle leading RecStar/Star and RecStar followed by /
    for ti in 0..nt {
        for si in 0..=ns {
            if !dp[ti][si]{continue;}
            match &toks[ti]{
                Tok::Star=>{
                    dp[ti+1][si]=true;
                    if si<ns && s[si]!='/' { dp[ti][si+1]=true; }
                },
                Tok::RecStar=>{
                    dp[ti+1][si]=true;
                    if si<ns { dp[ti][si+1]=true; }
                    // **/ can match zero components: if next tok is Char('/'), allow skipping it via dp propagation in next iterations? Standard DP with RecStar consuming slash handles */ cases but zero-dir case where pattern **/b needs match b at top: RecStar then '/' token must consume a slash, which would fail for top-level. Handle: if next token is '/', mark dp[ti+2][si]=true when ti+1<nt
                    if sep && ti+1<nt {
                        if let Tok::Char('/')=toks[ti+1] { dp[ti+2][si]=true; }
                    }
                },
                Tok::Qmark=>{
                    if si<ns && (!sep || s[si]!='/'){ dp[ti+1][si+1]=true; }
                },
                Tok::Char(c)=>{
                    if si<ns && s[si]==*c { dp[ti+1][si+1]=true; }
                },
                Tok::Class(ranges,neg)=>{
                    if si<ns && (!sep || s[si]!='/') { let inside=ranges.iter().any(|(lo,hi)| s[si]>=*lo&&s[si]<=*hi); if inside!=*neg { dp[ti+1][si+1]=true; } }
                }
            }
        }
    }
    // Need also allow trailing RecStar/Star dp propagation already handled in loop order? dp[ti][si+1] revisited because si ascending, dp[ti+1][si] later. For **/ skipping, dp[ti+2][si] set when ti processed, will be processed.
    dp[nt][ns]
}

pub fn scan_matches(pattern:&str, rel_path:&str)->bool{
    let pat=pattern.strip_prefix('/').unwrap_or(pattern);
    if glob_match_sep(pat, rel_path){ return true; }
    let fname=rel_path.rsplit('/').next().unwrap_or(rel_path);
    glob_match_sep(pat, fname)
}

pub fn explicit_match(patterns:&[String], rel_path:&str)->Option<String>{
    for pat in patterns {
        let trimmed=pat.trim_end_matches('/');
        let variants=vec![pat.clone(), format!("{trimmed}/**")];
        for v in variants { if glob_match_cross(&v, rel_path){ return Some(v); } }
    }
    None
}
pub fn cross_matches(pattern:&str, rel_path:&str)->bool{
    glob_match_cross(pattern, rel_path)
}
