use crate::config::*;
use crate::info::*;
use crate::lint::*;
use std::collections::{BTreeMap, HashSet};

#[derive(Clone)]
pub struct EffectiveConfig {
    pub config: Config,
    pub invalid_rules: HashSet<String>,
}

pub fn validate_and_build(cfg:&Config)->EffectiveConfig{
    // Placeholder: invalid determined in rule cfg access; factory warnings emitted by check before lint via factory_warnings()
    EffectiveConfig{ config: cfg.clone(), invalid_rules: compute_invalid_rules(cfg) }
}

pub fn enum_allowed(code:&str,key:&str)->Option<&'static [&'static str]>{
    match (code,key){
        ("MD003","style")=>Some(&["consistent","atx","atx_closed","setext","setext_with_atx","setext_with_atx_closed"]),
        ("MD007","style")=>Some(&["text-aligned","text_aligned","fixed"]),
        ("MD013","length-mode")=>Some(&["visual","chars","bytes"]),
        ("MD013","reflow-mode")=>Some(&["default","normalize","sentence-per-line"]),
        ("MD029","style")=>Some(&["one","one-one","one_one","ordered","ordered0","one-or-ordered","one_or_ordered","consistent"]),
        ("MD040","style")=>Some(&["disabled","consistent"]),
        ("MD040","unknown-language-action")=>Some(&["ignore","warn","error"]),
        ("MD055","style")=>Some(&["consistent","leading-and-trailing","no-leading-or-trailing","leading-only","trailing-only"]),
        ("MD060","style")=>Some(&["aligned","aligned-no-space","compact","tight","any"]),
        ("MD060","column-align")=>Some(&["auto","left","center","right"]),
        ("MD060","column-align-body")=>Some(&["auto","left","center","right"]),
        ("MD060","column-align-header")=>Some(&["auto","left","center","right"]),
        ("MD063","style")=>Some(&["title_case","sentence_case","all_caps"]),
        _=>None
    }
}

fn compute_invalid_rules(cfg:&Config)->HashSet<String>{
    let mut invalid=HashSet::new();
    for (code,map) in &cfg.rules {
        for (k,v) in map {
            if let Some(def)=default_for(code,k){
                if toml_type_str(&def)!=toml_type_str(v){ invalid.insert(code.clone()); break; }
                if let toml::Value::Integer(i)=v { if *i<0 { invalid.insert(code.clone()); break; } }
                if let Some(allowed)=enum_allowed(code,k){ if let toml::Value::String(s)=v{ if !allowed.contains(&s.as_str()){ invalid.insert(code.clone()); break; } } }
                // ranges
                if (code=="MD025"||code=="MD041") && k=="level" { if let toml::Value::Integer(i)=v{ if *i<1||*i>6{invalid.insert(code.clone());break;} } }
                if code=="MD036" && k=="heading-level" { if let toml::Value::Integer(i)=v{ if *i<1||*i>6{invalid.insert(code.clone());break;} } }
            }
        }
    }
    invalid
}

pub struct RuleCfg<'a> {
    pub eff:&'a EffectiveConfig,
