    match v {
        toml::Value::String(s)=>format!("invalid type: string {s:?},"),
        toml::Value::Integer(i)=>format!("invalid type: integer `{i}`,"),
        toml::Value::Float(f)=>format!("invalid type: floating point `{f}`,"),
        toml::Value::Boolean(b)=>format!("invalid type: boolean `{b}`,"),
        toml::Value::Array(_)=>"invalid type: sequence,".to_string(),
        toml::Value::Table(_)=>"invalid type: map,".to_string(),
        toml::Value::Datetime(d)=>format!("invalid type: string \"{d}\","),
    }
}
fn expected_type_name(code:&str,key:&str,def:&toml::Value)->String{
    // crude mapping for integer fields known to be u8
    let u8_fields=[("MD007","indent"),("MD025","level"),("MD007","start-indent")];
    match def {
        toml::Value::Integer(_)=> if u8_fields.contains(&(code,key)){"u8".into()}else{"usize".into()},
        toml::Value::Boolean(_)=>"a boolean".into(),
        toml::Value::String(_)=>"a string".into(),
        toml::Value::Array(_)=>"a sequence".into(),
        toml::Value::Float(_)=>"f64".into(),
        toml::Value::Table(_)=>"a map".into(),
        toml::Value::Datetime(_)=>"a string".into(),
    }
}
