use crate::lint::*;
use crate::rules::*;
use std::collections::HashSet;
pub fn lint_content_impl(content:&str, cfg:&Config, enabled:&[&RuleInfo], flavor:Flavor, file_path:Option<std::path::PathBuf>)->Vec<LintWarning>{
    // inline configure-file merge is handled by caller cloning config if needed (TODO in check layer)
    let eff=validate_and_build(cfg);
    let ctx=LintContext::new(content, flavor, file_path.clone());
    let enabled_set:HashSet<&str>=enabled.iter().map(|r| r.code).collect();
    let mut warnings=Vec::new();
    // dispatch placeholder expanded by include of rule functions
    crate::rule_funcs::run_all(&ctx,&eff,&enabled_set,&mut warnings);
    // inline config filtering
