pub fn sorted_warnings(results:&[FileResult])->Vec<(&FileResult,&LintWarning)>{
    let mut v:Vec<(&FileResult,&LintWarning)>=results.iter().flat_map(|f| f.warnings.iter().map(move |w| (f,w))).collect();
    v.sort_by(|a,b| { a.0.display.cmp(&b.0.display).then((a.1.line,a.1.column,&a.1.rule_name).cmp(&(b.1.line,b.1.column,&b.1.rule_name))) });
    v
}

pub fn format_text_warning(file:&str,w:&LintWarning,color:bool,fixed_mode:Option<bool>)->String{
    // fixed_mode None=normal[*], Some(true/false)?
    let suffix=match fixed_mode { Some(_)=> if w.fix.is_some(){" [fixed]"}else{""}, None=> if w.fix.is_some(){" [*]"}else{""} };
    if color {
        format!("\x1b[4;34m{file}\x1b[0m:\x1b[36m{}\x1b[0m:\x1b[36m{}\x1b[0m: \x1b[33m[{}]\x1b[0m {}\x1b[32m{suffix}\x1b[0m", w.line,w.column,w.rule_name,w.message)
    } else {
        format!("{file}:{}:{}: [{}] {}{suffix}", w.line,w.column,w.rule_name,w.message)
    }
}

