use std::io::{Read, Write};
use std::path::{Path, PathBuf};
use std::time::Instant;

#[derive(Debug, Clone, PartialEq)]
pub enum OutputFmt { Text, Full, Concise, Grouped, Json, JsonLines, Github, Gitlab, Pylint, Azure, Sarif, Junit }
impl OutputFmt {
    pub fn parse(s:&str)->Option<Self>{ match s.to_ascii_lowercase().as_str(){ "text"=>Some(Self::Text),"full"=>Some(Self::Full),"concise"=>Some(Self::Concise),"grouped"=>Some(Self::Grouped),"json"=>Some(Self::Json),"json-lines"=>Some(Self::JsonLines),"github"=>Some(Self::Github),"gitlab"=>Some(Self::Gitlab),"pylint"=>Some(Self::Pylint),"azure"=>Some(Self::Azure),"sarif"=>Some(Self::Sarif),"junit"=>Some(Self::Junit),_=>None } }
    pub fn name(&self)->&'static str{ match self{Self::Text=>"text",Self::Full=>"full",Self::Concise=>"concise",Self::Grouped=>"grouped",Self::Json=>"json",Self::JsonLines=>"json-lines",Self::Github=>"github",Self::Gitlab=>"gitlab",Self::Pylint=>"pylint",Self::Azure=>"azure",Self::Sarif=>"sarif",Self::Junit=>"junit"} }
    pub fn is_structured(&self)->bool{ matches!(self,Self::Json|Self::Gitlab|Self::Sarif|Self::Junit) }
    pub fn has_summary(&self)->bool{ !self.is_structured() }
}

pub struct CheckArgs {
    pub paths: Vec<String>,
    pub fix_flag: bool,
    pub diff_flag: bool,
    pub check_flag: bool,
    pub disable: Option<String>,
    pub enable: Option<String>,
    pub extend_enable: Option<String>,
    pub extend_disable: Option<String>,
    pub exclude: Option<String>,
    pub no_exclude: bool,
    pub include: Option<String>,
    pub respect_gitignore: Option<String>,
    pub verbose: bool,
    pub profile: bool,
    pub statistics: bool,
    pub quiet: bool,
    pub output: String,
    pub output_format: Option<String>,
    pub show_full_path: bool,
    pub flavor: Option<String>,
    pub stdin_flag: bool,
    pub stdin_filename: Option<String>,
    pub stderr_flag: bool,
    pub silent: bool,
    pub watch: bool,
    pub force_exclude: bool,
    pub no_cache: bool,
    pub cache_dir: Option<String>,
    pub fail_on: String,
}
impl CheckArgs {
    pub fn from_matches(m:&ArgMatches)->Self{
        let get=|k:&str| m.get_one::<String>(k).cloned();
        Self{
            paths: m.get_many::<String>("paths").map(|v| v.cloned().collect()).unwrap_or_default(),
            fix_flag:m.get_flag("fix"), diff_flag:m.get_flag("diff"), check_flag:m.get_flag("check"),
            disable:get("disable"), enable:get("enable"), extend_enable:get("extend-enable"), extend_disable:get("extend-disable"),
            exclude:get("exclude"), no_exclude:m.get_flag("no-exclude"), include:get("include"),
            respect_gitignore:get("respect-gitignore"), verbose:m.get_flag("verbose"), profile:m.get_flag("profile"), statistics:m.get_flag("statistics"), quiet:m.get_flag("quiet"),
            output:get("output").unwrap_or("text".into()), output_format:get("output-format"), show_full_path:m.get_flag("show-full-path"), flavor:get("flavor"), stdin_flag:m.get_flag("stdin"), stdin_filename:get("stdin-filename"), stderr_flag:m.get_flag("stderr"), silent:m.get_flag("silent"), watch:m.get_flag("watch"), force_exclude:m.get_flag("force-exclude"), no_cache:m.get_flag("no-cache"), cache_dir:get("cache-dir"), fail_on:get("fail-on").unwrap_or("any".into()),
        }
    }
}

fn split_list(s:&str)->Vec<String>{ s.split(',').map(|x| x.trim().to_string()).filter(|x| !x.is_empty()).collect() }

fn cli_warn_unknown(list_opt:&Option<String>, flag:&str){
    if let Some(s)=list_opt{ for tok in split_list(s){ if tok.eq_ignore_ascii_case("all"){continue;} if resolve_rule(&tok).is_none(){ eprintln!("\x1b[33m[cli warning]\x1b[0m Unknown rule in {flag}: {tok}"); } } }
}

pub fn compute_enabled(cfg:&Config, args:&CheckArgs)->Vec<&'static RuleInfo>{
    // Merge logic derived from probing
    let mut e_list:Vec<String>=cfg.global.enable.clone();
    let mut d_list:Vec<String>=cfg.global.disable.clone();
    // extend merges first (with quirks)
    if let Some(ee)=&args.extend_enable {
        if !e_list.is_empty() {
            for tok in split_list(ee){ if let Some(info)=resolve_rule(&tok){ if !d_list.iter().any(|d| resolve_rule(d).map(|i| i.code)==Some(info.code)) && !e_list.iter().any(|x| resolve_rule(x).map(|i| i.code)==Some(info.code)) { e_list.push(tok); } } }
        }
    }
    if let Some(ed)=&args.extend_disable {
        for tok in split_list(ed){ if let Some(info)=resolve_rule(&tok){ e_list.retain(|x| resolve_rule(x).map(|i| i.code)!=Some(info.code)); if !d_list.iter().any(|x| resolve_rule(x).map(|i| i.code)==Some(info.code)){ d_list.push(tok); } } }
    }
    let mut enabled_set: HashSet<String>;
    if let Some(ce)=&args.enable {
        enabled_set=HashSet::new(); for tok in split_list(ce){ if let Some(info)=resolve_rule(&tok){ enabled_set.insert(info.code.to_string()); } }
    } else if !e_list.is_empty() {
        enabled_set=HashSet::new(); for tok in &e_list{ if let Some(info)=resolve_rule(tok){ enabled_set.insert(info.code.to_string()); } }
    } else {
        enabled_set=RULES.iter().map(|r| r.code.to_string()).collect();
        for tok in &d_list{ if let Some(info)=resolve_rule(tok){ enabled_set.remove(info.code); } }
    }
    if let Some(cd)=&args.disable {
        for tok in split_list(cd){ if let Some(info)=resolve_rule(&tok){ enabled_set.remove(info.code); } }
    }
    RULES.iter().filter(|r| enabled_set.contains(r.code)).collect()
}

fn resolve_output_format(args:&CheckArgs, cfg:&Config)->Result<OutputFmt,String>{
    if let Some(f)=&args.output_format { return OutputFmt::parse(f).ok_or_else(|| f.clone()); }
    if let Ok(env)=std::env::var("RUMDL_OUTPUT_FORMAT") { if !env.is_empty(){ return OutputFmt::parse(&env).ok_or(env); } }
    if let Some(cf)=&cfg.global.output_format { return OutputFmt::parse(cf).ok_or_else(|| cf.clone()); }
    if args.output=="json" { return Ok(OutputFmt::Json); }
    Ok(OutputFmt::Text)
}

fn fail_exit(warnings:&[LintWarning], fail_on:&str)->bool{
    match fail_on { "never"=>false, "error"=>warnings.iter().any(|w| w.severity==Severity::Error), "warning"=>warnings.iter().any(|w| matches!(w.severity,Severity::Error|Severity::Warning)), _=>!warnings.is_empty() }
}

pub fn run_check(matches:&ArgMatches, global:&GlobalOpts, is_fmt:bool)->i32{
    let args=CheckArgs::from_matches(matches);
    // validation fix/diff
    let diff_effective = args.diff_flag || (is_fmt && args.check_flag);
    if diff_effective && args.fix_flag { eprintln!("Error: --diff and --fix cannot be used together\nUse --diff to preview changes, or --fix to apply them"); return 2; }
    if args.check_flag && args.fix_flag && !is_fmt { eprintln!("Error: --check and --fix cannot be used together\nUse --check to verify formatting without changes, or --fix to apply them"); return 2; }
    if args.watch { return crate::watch::run_watch(matches, global, is_fmt); }
    run_check_once(matches, global, is_fmt, &args, diff_effective)
}

pub fn run_check_once(_matches:&ArgMatches, global:&GlobalOpts, is_fmt:bool, args:&CheckArgs, diff_effective:bool)->i32{
    let start=Instant::now();
    let fix_effective = args.fix_flag || is_fmt;
    let color=should_color(&global.color);
    // config start dir determination (except stdin -> cwd)
    let is_stdin = args.stdin_flag || (args.paths.len()==1 && args.paths[0]=="-");
    let start_dir: PathBuf = if is_stdin { PathBuf::from(".") } else if let Some(first)=args.paths.first() { let p=Path::new(first); if p.is_dir(){ p.to_path_buf() } else if let Some(parent)=p.parent(){ if parent.as_os_str().is_empty(){ PathBuf::from(".") } else { parent.to_path_buf() } } else { PathBuf::from(".") } } else { PathBuf::from(".") };
    // config load (silent suppresses config warnings)
    let cfg=match load_resolved(global,&start_dir,args.silent){ Ok(c)=>c, Err(e)=>{ eprintln!("Config error: {e}"); return 2; } };
    // factory warnings (not suppressed by silent based on probes -- they appeared under -s; but maybe only in file/stdin lint paths, emit after output format validation? Order vs bogus format: probe later; emit here after format check below)
    // output format determination (after config, before file discovery/stdin read based on probes)
    let fmt=match resolve_output_format(args,&cfg){ Ok(f)=>f, Err(name)=>{ eprintln!("Error: Unknown output format: {name}"); return if is_fmt{0}else{1}; } };
    if args.force_exclude && !args.silent { eprintln!("warning: --force-exclude is deprecated and has no effect\nExclude patterns are now always respected by default (as of v0.0.156)\nUse --no-exclude if you want to disable exclusions"); }
    // cli unknown warnings (suppressed if silent? test later; assume not silent)
    if !args.silent {
        cli_warn_unknown(&args.enable,"--enable"); cli_warn_unknown(&args.disable,"--disable"); cli_warn_unknown(&args.extend_enable,"--extend-enable"); cli_warn_unknown(&args.extend_disable,"--extend-disable");
    }
    // factory warnings
    {
        let warns=crate::rules::factory_warnings(&cfg);
        for w in warns { eprint!("{w}"); }
    }
    let enabled=compute_enabled(&cfg,args);
    if args.verbose && !args.silent {
        println!("Enabled rules:");
        for r in &enabled { println!("  - {} ({})", r.code, r.summary); }
        println!();
    }
    if is_stdin {
        return run_stdin(args, global, is_fmt, fix_effective, &cfg, &enabled, &fmt, color);
    }
    // File discovery
    let files_res=discover_files(args,&cfg);
    let files=match files_res{ Ok(f)=>f, Err(msg)=>{
        if !args.silent { eprintln!("Error: Failed to find markdown files: {msg}"); }
        return if is_fmt{0}else{1};
    } };
    if files.is_empty() {
        if !args.silent { println!("No markdown files found to check."); }
        return 0;
    }
    // Process files
    let mut results:Vec<FileResult>=Vec::new();
    let mut file_data:Vec<(FileEntry,String)>=Vec::new(); // entry + original content (empty if read error)
    for entry in &files {
        if args.verbose && !args.silent { println!("Processing file: {}", entry.display); }
        let content=match std::fs::read_to_string(&entry.abs_path){ Ok(c)=>c, Err(e)=>{
            // Error reading file ... to stderr (even silent? assume still? but follow silent for diagnostics only; original file read error in silent unknown)
            if !args.silent { eprintln!("Error reading file {}: Failed to read file {}: {e}", entry.abs_path.display(), entry.abs_path.display()); }
            results.push(FileResult{display:entry.display.clone(),abs_path:entry.abs_path.clone(),warnings:vec![]});
            file_data.push((entry.clone(),String::new()));
            continue;
        } };
        // cache handling simplified in cache.rs (may return warnings)
        let flavor=flavor_for_file(args,&cfg,entry);
        let per_disabled=per_file_disabled(&cfg,entry);
        let enabled_for_file:Vec<&RuleInfo>=enabled.iter().filter(|r| !per_disabled.contains(r.code)).copied().collect();
        let mut warnings=crate::rules::lint_content(&content,&cfg,&enabled_for_file,flavor,Some(entry.abs_path.clone()));
        // cross-file rules are handled in rules that need file path (they read other files as needed)
        results.push(FileResult{display:entry.display.clone(),abs_path:entry.abs_path.clone(),warnings});
        file_data.push((entry.clone(),content));
    }
    let total_warnings:usize=results.iter().map(|r| r.warnings.len()).sum();
    let fixable_count:usize=results.iter().flat_map(|r| &r.warnings).filter(|w| w.fix.is_some()).count();
    let files_with_issues=results.iter().filter(|r| !r.warnings.is_empty()).count();
    let elapsed=start.elapsed(); let elapsed_ms=elapsed.as_millis();
    // structured formats: no fix/diff/summary
    if fmt.is_structured() {
        if !args.silent {
            let out=format_by_name(fmt.name(),&results,color,elapsed_ms);
            if args.stderr_flag { eprint!("{out}"); } else { print!("{out}"); let _=std::io::stdout().flush(); }
        }
        if is_fmt { return 0; }
        let all:Vec<LintWarning>=results.iter().flat_map(|r| r.warnings.clone()).collect();
        return if fail_exit(&all,&args.fail_on){1}else{0};
    }
    // Diff mode
    if diff_effective {
        return handle_diff_mode(args,is_fmt,fix_effective,&cfg,&enabled,&results,&file_data,color,elapsed_ms);
    }
    if fix_effective {
        // apply fixes and write
        let mut fixed_count=0usize;
        for (idx,(entry,content)) in file_data.iter().enumerate() {
            let initial=&results[idx].warnings;
            let fc=initial.iter().filter(|w| w.fix.is_some() && fix_allowed(&cfg,&w.rule_name)).count();
            fixed_count+=fc;
            if fc>0 {
                let flavor=flavor_for_file(args,&cfg,entry);
                let per_disabled=per_file_disabled(&cfg,entry);
                let enabled_for_file:Vec<&RuleInfo>=enabled.iter().filter(|r| !per_disabled.contains(r.code)).copied().collect();
                let (fixed, _remaining)=crate::fix::apply_fixes(content,&cfg,&enabled_for_file,flavor,Some(entry.abs_path.clone()));
                if fixed!=*content { let _=std::fs::write(&entry.abs_path,&fixed); }
            }
        }
        // output diagnostics text with [fixed]
        if !args.silent {
            let mut out=String::new();
            for f in &results{ for w in &f.warnings{ let is_fixed=w.fix.is_some()&&fix_allowed(&cfg,&w.rule_name); let suffix=if is_fixed{" [fixed]"}else{""}; // reuse format_text_warning with Some will mark all fixable as fixed; need account fixable/unfixable cfg: if fix not allowed, original may show [*] or nothing? Probe later; use text fn then replace for non-allowed
                let mut line=format_text_warning(&f.display,w,color,Some(true));
                if w.fix.is_some() && !is_fixed { line=line.replace(" [fixed]"," [*]"); }
                out.push_str(&line); out.push('\n'); } }
            if args.stderr_flag { eprint!("{out}"); } else { print!("{out}"); }
            if !args.quiet { print_summary(color,total_warnings,fixable_count,fixed_count,files_with_issues,results.len(),elapsed_ms,true,args.statistics,&results,args.profile,args.stderr_flag); }
        }
        if is_fmt { return 0; }
        // remaining = initial warnings not fixed (fix is None or not allowed)
        let remaining:Vec<LintWarning>=results.iter().flat_map(|r| r.warnings.iter().filter(|w| !(w.fix.is_some()&&fix_allowed(&cfg,&w.rule_name))).cloned()).collect();
        return if fail_exit(&remaining,&args.fail_on){1}else{0};
    }
    // normal mode
    if !args.silent {
        let out=format_by_name(fmt.name(),&results, color && matches!(fmt,OutputFmt::Text|OutputFmt::Full), elapsed_ms);
        if args.stderr_flag { eprint!("{out}"); } else { print!("{out}"); }
        if !args.quiet { print_summary(color,total_warnings,fixable_count,0,files_with_issues,results.len(),elapsed_ms,false,args.statistics,&results,args.profile,args.stderr_flag); }
    }
    if is_fmt { return 0; }
    let all:Vec<LintWarning>=results.iter().flat_map(|r| r.warnings.clone()).collect();
    if fail_exit(&all,&args.fail_on){1}else{0}
}

fn print_summary(color:bool,total:usize,fixable:usize,fixed:usize,files_with:usize,total_files:usize,elapsed_ms:u128,is_fix_mode:bool,statistics:bool,results:&[FileResult],profile:bool,stderr_flag:bool){
    let file_str=if total==0 { format!("{} {}", total_files, if total_files==1{"file"}else{"files"}) } else if files_with==total_files { format!("{} {}", total_files, if total_files==1{"file"}else{"files"}) } else { format!("{files_with}/{total_files} files") };
    if total==0 {
        let prefix=if color{"\x1b[1;32mSuccess:\x1b[0m"}else{"Success:"};
        println!("\n{prefix} No issues found in {file_str} ({elapsed_ms}ms)");
    } else if fixed>0 {
        let prefix=if color{"\x1b[1;32mFixed:\x1b[0m"}else{"Fixed:"};
        println!("\n{prefix} Fixed {fixed}/{total} issues in {file_str} ({elapsed_ms}ms)");
    } else {
        let prefix=if color{"\x1b[33mIssues:\x1b[0m"}else{"Issues:"};
        println!("\n{prefix} Found {total} issues in {file_str} ({elapsed_ms}ms)");
        if fixable>0 && !is_fix_mode { println!("Run `rumdl fmt` to automatically fix {fixable} of the {total} issues"); }
        else if fixable>0 && is_fix_mode && fixed==0 {
            // In diff mode with fix effective but no... summary logic handled in diff; here is_fix_mode true only fix path - if fixed==0 due unfixable only, no hint (fixable would be >0 leads fixed>0 usually)
        }
    }
    if statistics && total>0 { print_statistics(results,color); }
    if profile {
        if stderr_flag { eprintln!("\nProfiling is disabled."); } else { println!("\nProfiling is disabled."); }
    }
}
fn print_statistics(results:&[FileResult],color:bool){
    use std::collections::HashMap;
    let mut counts:HashMap<String,(usize,usize)>=HashMap::new();
    let mut total=0; let mut total_fix=0;
    for f in results{ for w in &f.warnings{ total+=1; let e=counts.entry(w.rule_name.clone()).or_default(); e.0+=1; if w.fix.is_some(){e.1+=1; total_fix+=1;} } }
    let mut rows:Vec<(String,usize,usize)>=counts.into_iter().map(|(k,(a,b))| (k,a,b)).collect();
    rows.sort_by(|a,b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    println!();
    let title=if color{"\x1b[1;4mRule Violation Statistics:\x1b[0m"}else{"Rule Violation Statistics:"};
    println!("{title}");
    println!("Rule     Violations   Fixable  Percentage");
    println!("--------------------------------------------------");
    for (code,c,fx) in &rows{ let pct=if total>0{*c as f64/total as f64*100.0}else{0.0}; let fx_str=if *fx>0{fx.to_string()}else{"-".to_string()}; println!("{:<9}{:<13}{:<10}{:>5.1}%",code,c,fx_str,pct); }
    println!("--------------------------------------------------");
    println!("{:<9}{:<13}{:<10}{:>5.1}%","Total",total,total_fix,100.0f64);
}

fn handle_diff_mode(args:&CheckArgs,is_fmt:bool,fix_effective:bool,cfg:&Config,enabled:&[&RuleInfo],results:&[FileResult],file_data:&[(FileEntry,String)],color:bool,elapsed_ms:u128)->i32{
    let total:usize=results.iter().map(|r| r.warnings.len()).sum();
    let fixable:usize=results.iter().flat_map(|r| &r.warnings).filter(|w| w.fix.is_some()&&fix_allowed(cfg,&w.rule_name)).count();
    let files_with=results.iter().filter(|r| !r.warnings.is_empty()).count();
    if !args.silent {
        let mut out=String::new();
        for (idx,f) in results.iter().enumerate() {
            let (entry,content)=&file_data[idx];
            if !fix_effective {
                // check diff: unfixable diagnostics first (text colored)
                for w in &f.warnings{ if !(w.fix.is_some()&&fix_allowed(cfg,&w.rule_name)){ out.push_str(&format_text_warning(&f.display,w,color,None)); out.push('\n'); } }
            }
            let has_fixable=f.warnings.iter().any(|w| w.fix.is_some()&&fix_allowed(cfg,&w.rule_name));
            if has_fixable {
                let flavor=flavor_for_file(args,cfg,entry);
                let per_disabled=per_file_disabled(cfg,entry);
                let enabled_for_file:Vec<&RuleInfo>=enabled.iter().filter(|r| !per_disabled.contains(r.code)).copied().collect();
                let (fixed,_)=crate::fix::apply_fixes(content,cfg,&enabled_for_file,flavor,Some(entry.abs_path.clone()));
                // Diff generation operates on original vs fixed (normalized handling inside generate_diff? apply_fixes returns restored CRLF if uniform; diff lines compare via lines() ignoring \r differences effectively)
                let d=crate::fix::generate_diff(content,&fixed,&f.display);
                out.push_str(&d);
            }
        }
        if args.stderr_flag { eprint!("{out}"); } else { print!("{out}"); }
        if !args.quiet {
            // summary: if fmt (fix_effective) use Fixed if fixable>0 else Issues; if check use Issues with hint
            if fix_effective {
                print_summary(color,total,fixable,fixable,files_with,results.len(),elapsed_ms,true,args.statistics,results,args.profile,args.stderr_flag);
            } else {
                print_summary(color,total,fixable,0,files_with,results.len(),elapsed_ms,false,args.statistics,results,args.profile,args.stderr_flag);
            }
        }
    }
    if is_fmt {
        if args.check_flag && fixable>0 { return 1; }
        return 0;
    }
    let all:Vec<LintWarning>=results.iter().flat_map(|r| r.warnings.clone()).collect();
    if fail_exit(&all,&args.fail_on){1}else{0}
}

pub fn fix_allowed(cfg:&Config, rule:&str)->bool{
    // global fixable/unfixable
    let resolve=|s:&str| resolve_rule(s).map(|i| i.code);
    if cfg.global.unfixable.iter().any(|s| resolve(s)==Some(rule)){ return false; }
    if !cfg.global.fixable.is_empty() && !cfg.global.fixable.iter().any(|s| resolve(s)==Some(rule)){ return false; }
    true
}

fn run_stdin(args:&CheckArgs, _global:&GlobalOpts, is_fmt:bool, fix_effective:bool, cfg:&Config, enabled:&[&RuleInfo], fmt:&OutputFmt, color:bool)->i32{
    let mut input=String::new();
    if let Err(e)=std::io::stdin().read_to_string(&mut input){ eprintln!("Error reading from stdin: {e}"); return 1; }
    let filename=args.stdin_filename.clone().unwrap_or("<stdin>".to_string());
    // flavor
    let flavor=flavor_for_stdin(args,cfg,&filename);
    // per-file ignores based on filename? Use filename as rel path
    let mut per_disabled:HashSet<String>=HashSet::new();
    for (pat,rules) in &cfg.per_file_ignores{ if crate::globmatch::cross_matches(pat,&filename){ for r in rules{ if let Some(info)=resolve_rule(r){per_disabled.insert(info.code.to_string());} } } }
    let enabled_for:Vec<&RuleInfo>=enabled.iter().filter(|r| !per_disabled.contains(r.code)).copied().collect();
    let file_path_for_rules = if filename=="<stdin>" { None } else { Some(std::env::current_dir().unwrap_or(PathBuf::from(".")).join(&filename)) };
    if fix_effective {
        let initial=crate::rules::lint_content(&input,cfg,&enabled_for,flavor,file_path_for_rules.clone());
        let fixed_count=initial.iter().filter(|w| w.fix.is_some()&&fix_allowed(cfg,&w.rule_name)).count();
        let (fixed,remaining)=crate::fix::apply_fixes(&input,cfg,&enabled_for,flavor,file_path_for_rules.clone());
        print!("{fixed}"); let _=std::io::stdout().flush();
        if !args.silent && !remaining.is_empty() {
            let result=vec![FileResult{display:filename.clone(),abs_path:PathBuf::new(),warnings:remaining.clone()}];
            let out=format_by_name(fmt.name(),&result, color && matches!(fmt,OutputFmt::Text|OutputFmt::Full), 0);
            eprint!("{out}");
            eprintln!("\n{} issue(s) fixed, {} issue(s) remaining", fixed_count, remaining.len());
        }
        if is_fmt{ return 0; }
        return if fail_exit(&remaining,&args.fail_on){1}else{0};
    } else {
        let warnings=crate::rules::lint_content(&input,cfg,&enabled_for,flavor,file_path_for_rules);
        if !args.silent {
            let result=vec![FileResult{display:filename.clone(),abs_path:PathBuf::new(),warnings:warnings.clone()}];
            let out=format_by_name(fmt.name(),&result, color && matches!(fmt,OutputFmt::Text|OutputFmt::Full), 0);
            eprint!("{out}");
            if !args.quiet && fmt.has_summary() {
                if warnings.is_empty(){ eprintln!("No issues found in {filename}"); } else { eprintln!("\nFound {} issue(s) in {filename}", warnings.len()); }
            }
        }
        return if fail_exit(&warnings,&args.fail_on){1}else{0};
    }
}

fn flavor_for_stdin(args:&CheckArgs,cfg:&Config,filename:&str)->Flavor{
    if let Some(f)=&args.flavor{ return Flavor::parse_loose(f).unwrap_or(Flavor::Standard); }
    // per-file flavor first? (test later) Use cfg per-file match
    for (pat,fl) in &cfg.per_file_flavor{ if crate::globmatch::cross_matches(pat,filename){ return *fl; } }
    if cfg.global_explicit.contains("flavor"){ return cfg.global.flavor; }
    if let Some(f)=Flavor::from_filename(filename){ return f; }
    cfg.global.flavor
}

#[derive(Clone)]
pub struct FileEntry { pub abs_path: PathBuf, pub display: String, pub explicit: bool }
fn discover_files(args:&CheckArgs,cfg:&Config)->Result<Vec<FileEntry>,String>{
    // effective exclude/include/respect
    let exclude_patterns:Vec<String>= if args.no_exclude{ vec![] } else if let Some(e)=&args.exclude{ split_list(e) } else { cfg.global.exclude.clone() };
    let include_patterns:Vec<String>= if let Some(i)=&args.include{ split_list(i) } else { cfg.global.include.clone() };
    let respect_gitignore:bool = if let Some(v)=&args.respect_gitignore{ v=="true" } else { cfg.global.respect_gitignore };
    if args.verbose && !args.silent { eprintln!("Exclude patterns: {:?}", exclude_patterns); }
    let paths:Vec<String>= if args.paths.is_empty(){ vec![".".to_string()] } else { args.paths.clone() };
    let cwd=std::env::current_dir().unwrap_or(PathBuf::from("."));
    let cwd_abs=std::fs::canonicalize(&cwd).unwrap_or(cwd);
    let config_dir_abs: Option<PathBuf>=cfg.loaded_path.as_ref().and_then(|p| p.parent().map(|x| x.to_path_buf()));
    let mut entries:Vec<FileEntry>=Vec::new();
    let mut seen:HashSet<PathBuf>=HashSet::new();
    let display_for=|abs:&Path, show_full:bool|->String{
        if show_full{ return abs.to_string_lossy().to_string(); }
        if let Some(cd)=&config_dir_abs{ if let Ok(rel)=abs.strip_prefix(cd){ return rel.to_string_lossy().to_string(); } }
        if let Ok(rel)=abs.strip_prefix(&cwd_abs){ return rel.to_string_lossy().to_string(); }
        abs.to_string_lossy().to_string()
    };
    for raw in &paths {
        let p=Path::new(raw);
        let meta=std::fs::metadata(p); // follows symlinks
        let Ok(meta)=meta else { return Err(format!("File not found: {raw}")); };
        if meta.is_file() {
            let abs=std::fs::canonicalize(p).unwrap_or(p.to_path_buf());
            // explicit exclude check against candidate string (relative to cwd if possible else raw-ish)
            let candidate_rel = if let Ok(rel)=abs.strip_prefix(&cwd_abs){ rel.to_string_lossy().to_string() } else if !Path::new(raw).is_absolute() { raw.clone() } else { abs.to_string_lossy().to_string() };
            // For warning display, original uses path as provided normalized? Use candidate_rel for absolute/relative; but for sub/../ preserve raw - approximate: if raw contains ".." use raw for both candidate and warning
            let (cand_for_match, warn_path) = if raw.contains("..") { (raw.clone(), raw.clone()) } else { (candidate_rel.clone(), candidate_rel.clone()) };
            if !exclude_patterns.is_empty() {
                if let Some(matched)=crate::globmatch::explicit_match(&exclude_patterns,&cand_for_match){ if !args.silent { eprintln!("warning: {warn_path} ignored because of exclude pattern '{matched}'. Use --no-exclude to override"); } continue; }
            }
            if seen.insert(abs.clone()){ entries.push(FileEntry{abs_path:abs.clone(),display:display_for(&abs,args.show_full_path),explicit:true}); }
        } else if meta.is_dir() {
            let abs_dir=std::fs::canonicalize(p).unwrap_or(p.to_path_buf());
            // Walk
            let mut builder=ignore::WalkBuilder::new(&abs_dir);
            builder.hidden(false).follow_links(false).git_ignore(respect_gitignore).git_global(respect_gitignore).git_exclude(respect_gitignore).ignore(respect_gitignore).parents(respect_gitignore).require_git(false);
            // filter_entry for excludes (clone patterns)
            let excl=exclude_patterns.clone(); let cwd2=cwd_abs.clone();
            if !excl.is_empty(){
                builder.filter_entry(move |entry|{
                    let path=entry.path();
                    // root dir entry depth 0: check if its rel path matches exclude (sub pattern when arg is sub): entry path equals abs_dir; rel to cwd is e.g. "sub"
                    let rel = path.strip_prefix(&cwd2).map(|r| r.to_string_lossy().to_string()).unwrap_or_else(|_| path.to_string_lossy().to_string());
                    if rel.is_empty(){ return true; }
                    for pat in &excl{ if crate::globmatch::scan_matches(pat,&rel){ return false; } }
                    true
                });
            }
            for entry in builder.build() {
                let Ok(entry)=entry else { continue; };
                let is_file=entry.file_type().map(|t| t.is_file()).unwrap_or(false);
                if !is_file{ continue; }
                let path=entry.path().to_path_buf();
                if !is_markdown_file(&path){ continue; }
                let abs=std::fs::canonicalize(&path).unwrap_or(path);
                let rel_cwd = abs.strip_prefix(&cwd_abs).map(|r| r.to_string_lossy().to_string()).unwrap_or_else(|_| abs.to_string_lossy().to_string());
                if !include_patterns.is_empty() {
                    if !include_patterns.iter().any(|pat| crate::globmatch::scan_matches(pat,&rel_cwd)){ continue; }
                }
                if seen.insert(abs.clone()){ entries.push(FileEntry{abs_path:abs.clone(),display:display_for(&abs,args.show_full_path),explicit:false}); }
            }
        } else {
            return Err(format!("File not found: {raw}"));
        }
    }
    Ok(entries)
}
pub fn is_markdown_file(p:&Path)->bool{
    let name=p.file_name().and_then(|s| s.to_str()).unwrap_or("");
    [".md",".markdown",".mdx",".qmd",".Rmd",".rmd",".mdown",".mkd",".mkdn",".mdwn"].iter().any(|suf| name.ends_with(suf))
}
fn flavor_for_file(args:&CheckArgs,cfg:&Config,entry:&FileEntry)->Flavor{
    if let Some(f)=&args.flavor{ return Flavor::parse_loose(f).unwrap_or(Flavor::Standard); }
    // per-file flavor against display then abs? Use display
    for (pat,fl) in &cfg.per_file_flavor{ if crate::globmatch::cross_matches(pat,&entry.display){ return *fl; } }
    if cfg.global_explicit.contains("flavor"){ return cfg.global.flavor; }
    if let Some(f)=Flavor::from_filename(&entry.display){ return f; }
    cfg.global.flavor
}
fn per_file_disabled(cfg:&Config,entry:&FileEntry)->HashSet<String>{
    let mut set=HashSet::new();
    for (pat,rules) in &cfg.per_file_ignores{ if crate::globmatch::cross_matches(pat,&entry.display){ for r in rules{ if let Some(info)=resolve_rule(r){set.insert(info.code.to_string());} } } }
    set
}
EOF
"}

actions.command:
cat > src/check.rs <<'EOF'
use crate::cli::{ColorChoice, GlobalOpts};
use crate::config::*;
use crate::info::*;
use crate::lint::*;
use crate::output::*;
use crate::util::*;
use clap::ArgMatches;
use std::collections::{BTreeMap, HashSet};
use std::io::{Read, Write};
