pub fn apply_fixes(content:&str, cfg:&Config, enabled:&[&RuleInfo], flavor:Flavor, file_path:Option<std::path::PathBuf>)->(String,Vec<LintWarning>){
    let uniform_crlf = content.contains("\r\n") && !content.replace("\r\n","").contains('\n');
