        if fixes.is_empty(){
            let fixed=if uniform_crlf{ working.replace('\n',"\r\n") } else { working };
            return (fixed,warnings);
        }
        // sort descending by start, then descending end
        fixes.sort_by(|a,b| b.0.cmp(&a.0).then(b.1.cmp(&a.1)));
        let mut new_working=working.clone();
        let mut last_applied_start: Option<usize>=None;
        let mut applied_any=false;
        for (s,e,repl) in fixes {
            if s>new_working.len()||e>new_working.len()||s>e{ continue; }
            // skip overlaps: if this fix's end > start of already applied (higher) fix, skip
            if let Some(ls)=last_applied_start{ if e>ls { continue; } }
            // ensure char boundaries
            if !new_working.is_char_boundary(s)||!new_working.is_char_boundary(e){ continue; }
            new_working.replace_range(s..e,&repl);
            last_applied_start=Some(s);
            applied_any=true;
        }
        if !applied_any || new_working==working {
            let warnings2=crate::rules::lint_content(&working,cfg,enabled,flavor,file_path.clone());
            let fixed=if uniform_crlf{ working.replace('\n',"\r\n") } else { working };
            return (fixed,warnings2);
        }
        working=new_working;
    }
    let warnings=crate::rules::lint_content(&working,cfg,enabled,flavor,file_path);
    let fixed=if uniform_crlf{ working.replace('\n',"\r\n") } else { working };
    (fixed,warnings)
}

pub fn generate_diff(original:&str, fixed:&str, display:&str)->String{
    // Use lines() semantics for rendering, unwrap_or("") for group detection (deduced)
    let orig:Vec<&str>=original.lines().collect();
    let fixv:Vec<&str>=fixed.lines().collect();
    let maxlen=orig.len().max(fixv.len());
    let get_o=|i:usize| orig.get(i).copied().unwrap_or("");
    let get_f=|i:usize| fixv.get(i).copied().unwrap_or("");
    // find consecutive diff groups
    let mut groups:Vec<(usize,usize)>=Vec::new();
    let mut i=0;
    while i<maxlen {
        if get_o(i)!=get_f(i){
            let start=i; while i<maxlen && get_o(i)!=get_f(i){ i+=1; } let end=i-1; groups.push((start,end));
        } else { i+=1; }
    }
    let mut out=String::new();
    out.push_str(&format!("--- {display}\n"));
    out.push_str(&format!("+++ {display} (fixed)\n"));
    if groups.is_empty(){ out.push_str("No changes\n"); return out; }
    for (gs,ge) in groups {
        let hunk_start=gs.saturating_sub(3);
        let hunk_end=std::cmp::min(ge+3, maxlen-1);
        let count=hunk_end-hunk_start+1;
        out.push_str(&format!("@@ -{},{} +{},{} @@\n", hunk_start+1,count,hunk_start+1,count));
        for j in hunk_start..=hunk_end {
            match (orig.get(j), fixv.get(j)) {
                (Some(o),Some(f)) if o==f=>{ out.push_str(&format!(" {o}\n")); },
                (Some(o),Some(f))=>{ out.push_str(&format!("-{o}\n+{f}\n")); },
                (Some(o),None)=>{ out.push_str(&format!("-{o}\n")); },
                (None,Some(f))=>{ out.push_str(&format!("+{f}\n")); },
                (None,None)=>{},
            }
        }
    }
    out
}
