pub fn atx_heading_text(line:&str, after_hashes:usize)->(String, bool){
    let rest=&line[after_hashes..];
    let mut text=rest.trim().to_string();
    let mut closed=false;
    // closed if text ends with #s preceded by space (or text is all #)
    if text.ends_with('#') {
        let trimmed=text.trim_end_matches('#');
        if trimmed.is_empty() { text=String::new(); closed=true; }
        else if trimmed.ends_with(|c:char| c.is_whitespace()) { text=trimmed.trim_end().to_string(); closed=true; }
