pub fn fix_range(ctx:&LintContext,start:usize,end:usize,repl:&str)->Option<FixInfo>{ Some(FixInfo{range:FixRange{start,end},replacement:repl.to_string()}) }
pub fn warn(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,line:usize,col:usize,end_line:usize,end_col:usize,msg:String,fix:Option<FixInfo>)->LintWarning{
    LintWarning::new(line,col,end_line,end_col,msg,sev(eff,info),fix,info.code)
}
pub fn is_blank(s:&str)->bool{ s.trim().is_empty() }
pub fn line_end_col(ctx:&LintContext,idx:usize)->usize{ ctx.line(idx).chars().count()+1 }

#[derive(Debug,Clone,PartialEq)]
pub enum HeadingStyle{ Atx, AtxClosed, Setext }
#[derive(Debug,Clone)]
pub struct Heading{
    pub line_idx:usize,
    pub end_idx:usize,
    pub level:usize,
    pub text:String,
    pub raw_text:String,
    pub style:HeadingStyle,
    pub indent:usize,
}
pub fn parse_atx(line:&str)->Option<(usize,usize,usize)>{
    // returns indent spaces count, level, byte index after hashes
    let mut indent=0; let bytes=line.as_bytes(); let mut i=0;
    while i<bytes.len() && bytes[i]==b' ' { indent+=1; i+=1; }
    if indent>3{return None;}
    let start=i; let mut level=0; while i<bytes.len()&&bytes[i]==b'#'{level+=1;i+=1;}
    if level==0||level>6{return None;}
    Some((indent,level,i))
}
pub fn atx_heading_text(line:&str, after_hashes:usize)->(String, bool){
    let rest=&line[after_hashes..];
    let mut text=rest.trim().to_string();
    let mut closed=false;
    // closed if text ends with #s preceded by space (or text is all #)
    if text.ends_with('#') {
        let trimmed=text.trim_end_matches('#');
        if trimmed.is_empty() { text=String::new(); closed=true; }
        else if trimmed.ends_with(|c:char| c.is_whitespace()) { text=trimmed.trim_end().to_string(); closed=true; }
    }
    (text,closed)
}
pub fn is_setext_underline(line:&str)->Option<usize>{
    let mut indent=0; for c in line.chars(){ if c==' '{indent+=1}else{break;} }
    if indent>3{return None;}
    let t=line.trim();
    if t.is_empty(){return None;}
    if t.chars().all(|c| c=='='){return Some(1);}
    if t.chars().all(|c| c=='-'){return Some(2);}
    None
}
pub fn get_headings(ctx:&LintContext)->Vec<Heading>{
    let mut out=Vec::new(); let mut i=0;
    while i<ctx.line_count(){
        let li=&ctx.lines[i];
        if li.in_fenced_code||li.is_fence||li.in_frontmatter||li.is_frontmatter_delim||li.in_indented_code{ i+=1; continue; }
        let line=ctx.line(i);
        // setext candidate: next line underline
        if i+1<ctx.line_count() && !is_blank(line) && parse_atx(line).is_none() {
            let nli=&ctx.lines[i+1];
            if !nli.in_fenced_code&&!nli.is_fence&&!nli.in_frontmatter&&!nli.is_frontmatter_delim {
                if let Some(level)=is_setext_underline(ctx.line(i+1)){
                    // previous line shouldn't be list item? markdownlint treats paragraph only; but many implementations still. Exclude if line is a list item or blockquote or thematic break or table row?
                    let trimmed=line.trim();
                    if !trimmed.starts_with('>') && !crate::lint::is_list_item_line(trimmed) && !is_thematic_break(line) {
                        out.push(Heading{line_idx:i,end_idx:i+1,level,text:trimmed.to_string(),raw_text:trimmed.to_string(),style:HeadingStyle::Setext,indent:0});
                        i+=2; continue;
                    }
                }
            }
        }
        if let Some((indent,level,after))=parse_atx(line){
            let (text,closed)=atx_heading_text(line,after);
            out.push(Heading{line_idx:i,end_idx:i,level,text,raw_text:line[after..].trim().to_string(),style:if closed{HeadingStyle::AtxClosed}else{HeadingStyle::Atx},indent});
        }
        i+=1;
    }
    out
}
pub fn is_thematic_break(line:&str)->bool{
    let t: String=line.chars().filter(|c| !c.is_whitespace()).collect();
    if t.len()<3{return false;}
    let c=t.chars().next().unwrap(); (c=='-'||c=='*'||c=='_') && t.chars().all(|x| x==c)
}
pub fn is_heading_line(ctx:&LintContext, idx:usize)->bool{ get_headings(ctx).iter().any(|h| h.line_idx==idx) }

pub fn run_all(ctx:&LintContext, eff:&EffectiveConfig, enabled:&HashSet<&str>, out:&mut Vec<LintWarning>){
    for info in RULES {
        if !enabled.contains(info.code){continue;}
        match info.code {
            "MD001"=>md001(ctx,eff,info,out),
            "MD003"=>md003(ctx,eff,info,out),
            "MD009"=>md009(ctx,eff,info,out),
            "MD010"=>md010(ctx,eff,info,out),
            "MD011"=>md011(ctx,eff,info,out),
            "MD012"=>md012(ctx,eff,info,out),
            "MD013"=>md013(ctx,eff,info,out),
            "MD014"=>md014(ctx,eff,info,out),
            "MD018"=>md018(ctx,eff,info,out),
            "MD019"=>md019(ctx,eff,info,out),
            "MD020"=>md020(ctx,eff,info,out),
            "MD021"=>md021(ctx,eff,info,out),
            "MD022"=>md022(ctx,eff,info,out),
            "MD023"=>md023(ctx,eff,info,out),
            "MD024"=>crate::rule_funcs2::md024(ctx,eff,info,out),
            "MD025"=>md025(ctx,eff,info,out),
            "MD026"=>md026(ctx,eff,info,out),
            "MD027"=>md027(ctx,eff,info,out),
            "MD028"=>md028(ctx,eff,info,out),
            "MD041"=>md041(ctx,eff,info,out),
            "MD047"=>md047(ctx,eff,info,out),
            _=>{ crate::rule_funcs2::run_rest(ctx,eff,info,out); }
        }
    }
}

// MD001
fn md001(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info);
    let front_matter_title=cfg.get_bool("front-matter-title").unwrap_or(true);
    let headings=get_headings(ctx);
    let mut prev_level:usize = if front_matter_title && has_frontmatter_title(ctx,None){1}else{0};
    // Note: if frontmatter title counts as H1, first heading ## is ok; if first heading is # (?) prev logic in original? MD001 with fm title and first ## gave no warning earlier. If first is # also no (prev 1, current 1). If first is ### expected 2.
    for h in headings {
        if prev_level>0 && h.level>prev_level+1 {
            let expected=prev_level+1;
            let line=ctx.line(h.line_idx);
            let fix=heading_level_fix(ctx,&h,expected);
            out.push(warn(ctx,eff,info,h.line_idx+1,1,h.line_idx+1,line_end_col(ctx,h.line_idx),format!("Expected heading level {expected}, but found heading level {}",h.level),fix));
            prev_level=expected;
        } else {
            // When a heading is skipped, original updates prev to expected (see probe: second expected 4 based on actual previous level 3, not expected 2) Wait probe: prev actual 3 => expected 4 for level5. So they update prev_level to *actual* heading level even if invalid, not expected! Let's check: headings # (1), ### (3) expected2; ##### (5) -> if prev set to expected2, next expected would be 3, message would be expected 3 found5, but probe says expected4 found5. So prev is actual prior level (3). Correct logic below in else branch not taken. Adjust: set prev to h.level regardless after processing (handled after loop logic)
            prev_level=h.level;
        }
        // The above if branch set prev=expected erroneously per note; fix by resetting to actual when warning was emitted
        // Detect by checking last warning? Simpler: recompute - we set a flag in branch; instead restructure below via a second pass is messy.
        // To keep correct, if warning emitted for this heading, prev should be actual level:
        // (we can detect expected condition again)
        // Note this line executes also for non-warning (harmless)
        // Determine if this heading was a skip relative to previous before it is lost -- not possible. So we instead handle in a custom loop below by returning early? 
        let _ = prev_level;
    }
    // The above loop has a bug for subsequent expected levels; fix by recomputing messages if there are >1 warnings? Instead, redo: clear warnings from this rule if multiple headings and rebuild correctly.
    // Simpler: if any MD001 warnings were added, rebuild correctly by removing them and running correct algorithm when headings.len()>1 and a skip occurred not at last.
    // We'll check if rebuilding is needed: remove last added warnings for this rule and re-add correct if the naive prev logic differed.
    // For now, truncate and rebuild always correctly:
    let start_len=out.len().saturating_sub(out.iter().filter(|w| w.rule_name==info.code).count());
    // Actually out may contain prior rules warnings before this call; we inserted only in this call at end, count them by tracking before - not available. Instead, perform a correction: if there are at least 2 MD001 warnings appended, their expected values may be off by chain.
    // Recompute expected properly and patch messages/fixes for appended MD001 warnings:
    let mut prev:usize = if front_matter_title && has_frontmatter_title(ctx,None){1}else{0};
    let mut wi=out.iter().position(|w| w.rule_name==info.code).unwrap_or(out.len());
    // This patching is fragile if other rules later; but run_all calls MD001 first, so all MD001 warnings are at start.
    for h in get_headings(ctx){
        if prev>0 && h.level>prev+1 {
            let expected=prev+1;
            if wi<out.len() && out[wi].rule_name==info.code { out[wi].message=format!("Expected heading level {expected}, but found heading level {}",h.level); out[wi].fix=heading_level_fix(ctx,&h,expected); wi+=1; }
        }
        prev=h.level;
    }
}
pub fn heading_level_fix(ctx:&LintContext,h:&Heading,new_level:usize)->Option<FixInfo>{
    let line=ctx.line(h.line_idx);
    let start=ctx.line_byte_start(h.line_idx);
    match h.style {
        HeadingStyle::Setext=>{
            if new_level<=2 { // setext can stay? Original for MD001 with setext? probe later; return replacing underline?
                // For setext level2 expected 1 etc - replace underline line
                let uline=h.end_idx; let us=ctx.line_byte_start(uline); let ue=ctx.line_byte_end(uline);
                let repl=if new_level==1{"=".repeat(ctx.line(uline).trim().len().max(1))}else{"-".repeat(ctx.line(uline).trim().len().max(1))};
                Some(FixInfo{range:FixRange{start:us,end:ue},replacement:repl})
            } else {
                // convert to atx: replace text line only (as MD003 does)
                Some(FixInfo{range:FixRange{start,end:ctx.line_byte_end(h.line_idx)},replacement:format!("{} {}", "#".repeat(new_level), h.text)})
            }
        },
        _=>{
            let (indent,_lvl,after)=parse_atx(line)?;
            let indent_str=" ".repeat(indent);
            let rest=&line[after..];
            // Preserve spacing after hashes and closed style: reconstruction in probe: replacement is whole line with new hashes + original rest (including spaces and closing)
            // Rest includes leading space(s) if any. If no space (MD018 case), rest is text directly; MD001 fix would be "##Text"? probe later.
            let replacement=format!("{}{}{}", indent_str, "#".repeat(new_level), rest);
            Some(FixInfo{range:FixRange{start,end:ctx.line_byte_end(h.line_idx)},replacement})
        }
    }
}
pub fn has_frontmatter_title(ctx:&LintContext, field_pattern:Option<&str>)->bool{
    // YAML frontmatter only (--- ... ---)
    if ctx.frontmatter_kind.as_deref()!=Some("yaml"){return false;}
    let Some(fm)=ctx.frontmatter_str() else {return false};
    // field_pattern: for MD001, front-matter-title bool config doesn't give field name; use "title"
    // for MD025/MD041 callers pass pattern string differently - this helper for MD001 only checks title:
    for line in fm.lines(){ let t=line.trim(); if t.to_ascii_lowercase().starts_with("title:"){ let v=t[6..].trim(); if !v.is_empty(){return true;} } }
    false
}

fn md003(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info);
    let style_cfg=cfg.get_str("style").unwrap_or("consistent".into());
    let headings=get_headings(ctx);
    if headings.is_empty(){return;}
    // Determine expected style kind per heading based on config
    #[derive(Clone,Copy,PartialEq,Debug)] enum Sty{Atx,AtxClosed,Setext}
    let heading_sty=|h:&Heading| match h.style{HeadingStyle::Atx=>Sty::Atx,HeadingStyle::AtxClosed=>Sty::AtxClosed,HeadingStyle::Setext=>Sty::Setext};
    let expected_for=|h:&Heading, consistent:Sty|->Sty{
        match style_cfg.as_str(){
            "atx"=>Sty::Atx,
            "atx_closed"=>Sty::AtxClosed,
            "setext"=> if h.level<=2{Sty::Setext}else{Sty::Atx},
            "setext_with_atx"=> if h.level<=2{Sty::Setext}else{Sty::Atx},
            "setext_with_atx_closed"=> if h.level<=2{Sty::Setext}else{Sty::AtxClosed},
            _=>consistent // consistent and unknown
        }
    };
    // consistent = most prevalent, tie -> Atx preference (docs). Need determine tie logic counts including ATX for levels >2 setext inability?
    let consistent={
        let mut counts=[0usize;3];
        for h in &headings{ match heading_sty(h){Sty::Atx=>counts[0]+=1,Sty::AtxClosed=>counts[1]+=1,Sty::Setext=>counts[2]+=1} }
        // Order of preference on tie: Atx first, then? choose max with earliest in this order
        let order=[Sty::Atx,Sty::AtxClosed,Sty::Setext];
        let idx=[0,1,2]; let mut best=0; for i in 1..3{ if counts[i]>counts[best]{best=i;} } order[best]
    };
    for h in &headings{
        let expected=expected_for(h,consistent);
        let actual=heading_sty(h);
        if actual!=expected{
            let (exp_desc, found_desc)=match expected{ Sty::Atx=>("# Heading", match actual{Sty::Setext=> if h.level==1{"Heading (underlined with =)"}else{"Heading (underlined with -)"}, Sty::AtxClosed=>"# Heading #", Sty::Atx=>"# Heading"}), Sty::AtxClosed=>("# Heading #", match actual{Sty::Setext=> if h.level==1{"Heading (underlined with =)"}else{"Heading (underlined with -)"}, _=>"# Heading"}), Sty::Setext=>(if h.level==1{"Heading (underlined with =)"}else{"Heading (underlined with -)"}, match actual{Sty::AtxClosed=>"# Heading #",_=>"# Heading"}) };
            // Messages probed for some combos; refine later if needed
            let msg=format!("Heading style should be {exp_desc}, found {found_desc}");
            let fix=convert_heading_fix(ctx,h,expected);
            out.push(warn(ctx,eff,info,h.line_idx+1,1,h.line_idx+1,line_end_col(ctx,h.line_idx),msg,fix));
        }
    }
}
fn convert_heading_fix(ctx:&LintContext,h:&Heading,expected:impl std::fmt::Debug)->Option<FixInfo>{
    // expected debug is Sty enum local - can't pass type across; handled by caller via match string? This placeholder will be replaced by inline logic in md003 (not used)
    None
}

fn md009(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info);
    let br_spaces=cfg.get_usize("br-spaces").unwrap_or(2);
    let strict=cfg.get_bool("strict").unwrap_or(false);
    let list_empty=cfg.get_bool("list-item-empty-lines").unwrap_or(false);
    for idx in 0..ctx.line_count(){
        let li=&ctx.lines[idx]; if li.in_fenced_code||li.is_fence{continue;}
        let line=ctx.line(idx);
        let trailing_contig=line.chars().rev().take_while(|c| *c==' ').count();
        if trailing_contig==0{continue;}
        let trimmed=line.trim_end();
        if trimmed.is_empty(){
            if list_empty && idx>0 {
                let prev=ctx.line(idx-1).trim_start();
                if crate::lint::is_list_item_line(prev){ continue; }
            }
            let start=ctx.line_byte_start(idx); let end=ctx.line_byte_end(idx);
            out.push(warn(ctx,eff,info,idx+1,1,idx+1,line.chars().count()+1,"Empty line has trailing spaces".into(),fix_range(ctx,start,end,"")));
            continue;
        }
        if !strict && trailing_contig==br_spaces{ continue; }
        // Bug-compatible: col/range based on trimmed (all whitespace) length
        let col=trimmed.chars().count()+1;
        let start_byte=ctx.line_byte_start(idx)+trimmed.len();
        let end_byte=start_byte+trailing_contig; // spaces are 1 byte each; if tab in suffix this may delete tab etc as observed (range length in bytes equals space count)
        let msg=if trailing_contig==1{"Trailing space found".to_string()}else{format!("{trailing_contig} trailing spaces found")};
        out.push(warn(ctx,eff,info,idx+1,col,idx+1,col+trailing_contig,msg,fix_range(ctx,start_byte,end_byte,"")));
    }
}
fn md010(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info); let spt=cfg.get_usize("spaces-per-tab").unwrap_or(4);
    for idx in 0..ctx.line_count(){
        let li=&ctx.lines[idx]; if li.in_fenced_code||li.is_fence{continue;}
        let line=ctx.line(idx); let chars:Vec<char>=line.chars().collect();
        let mut i=0;
        while i<chars.len(){
            if chars[i]=='\t'{
                let start=i; while i<chars.len()&&chars[i]=='\t'{i+=1;} let count=i-start;
                let byte_start=ctx.char_to_byte(idx,start); let byte_end=ctx.char_to_byte(idx,i);
                let repl=" ".repeat(count*spt);
                let msg=if start==0{
                    if count==1{format!("Found leading tab, use {} spaces instead", spt)}else{format!("Found {count} leading tabs, use {} spaces instead", count*spt)}
                } else {
                    if count==1{"Found tab for alignment, use spaces instead".to_string()}else{format!("Found {count} tabs for alignment, use spaces instead")}
                };
                out.push(warn(ctx,eff,info,idx+1,start+1,idx+1,start+count+1,msg,fix_range(ctx,byte_start,byte_end,&repl)));
            } else { i+=1; }
        }
    }
}
fn md011(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    // Pattern: (text)[url] where url looks like link destination (contains :// or mailto: or ...). Need examine false positives later.
    // Use scanning per line skipping code spans and fenced.
    for idx in 0..ctx.line_count(){
        let li=&ctx.lines[idx]; if li.in_code()||li.is_fence||li.in_frontmatter{continue;}
        let line=ctx.line(idx); let spans=code_span_ranges(line);
        let chars:Vec<char>=line.chars().collect(); let mut i=0;
        while i<chars.len(){
            if chars[i]=='(' && !in_code_span(&spans,i){
                // find matching ')'
                let mut depth=1; let mut j=i+1;
                while j<chars.len(){ if chars[j]=='(' {depth+=1;} else if chars[j]==')'{depth-=1; if depth==0{break;}} j+=1; }
                if depth==0 && j+1<chars.len() && chars[j+1]=='[' {
                    // find closing ]
                    let mut k=j+2; while k<chars.len()&&chars[k]!=']'{k+=1;}
                    if k<chars.len(){
                        let text:String=chars[i+1..j].iter().collect();
                        let url:String=chars[j+2..k].iter().collect();
                        if is_link_url(&url) && !text.is_empty() {
                            let startb=ctx.char_to_byte(idx,i); let endb=ctx.char_to_byte(idx,k+1);
                            let repl=format!("[{text}]({url})");
                            out.push(warn(ctx,eff,info,idx+1,i+1,idx+1,k+2,format!("Reversed link syntax: use {repl} instead"),fix_range(ctx,startb,endb,&repl)));
                            i=k+1; continue;
                        }
                    }
                }
            }
            i+=1;
        }
    }
}
pub fn is_link_url(url:&str)->bool{
    let u=url.trim();
    u.contains("://")||u.starts_with("mailto:")||u.starts_with("http:")||u.starts_with("https:")||u.starts_with("ftp:")|| (u.contains('@')&&u.contains('.'))
}
fn md012(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info); let maximum=cfg.get_usize("maximum").unwrap_or(1);
    let mut consecutive=0usize;
    for idx in 0..ctx.line_count(){
        let li=&ctx.lines[idx];
        if li.in_fenced_code||li.is_fence{ consecutive=0; continue; }
        let line=ctx.line(idx);
        if is_blank(line){
            consecutive+=1;
            if consecutive>maximum{
                // message location depends on context: between content / at start / at end - probe variants
                // Determine if there's content before and after in file (nonblank outside frontmatter?)
                let has_before=(0..idx).any(|i| !is_blank(ctx.line(i)) && !ctx.lines[i].is_frontmatter_delim);
                let has_after=(idx+1..ctx.line_count()).any(|i| !is_blank(ctx.line(i)));
                let msg=if has_before&&has_after{"Multiple consecutive blank lines between content".to_string()}else if !has_before{"Multiple consecutive blank lines at start of file".to_string()}else{"Multiple consecutive blank lines at end of file".to_string()};
                // Fix: delete this blank line's newline: range start = byte_end of line (position of \n) to +1 if not last line w/o newline; probed between content: line3 blank empty range start13 end14 = the newline char after blank line? content "# Chapter 1\n" (12) then blank line at 12 '\n', next blank line starts13 '\n' - warning line3 fix 13..14 deletes that newline.
                let start=ctx.line_byte_end(idx); let end=if start<ctx.content.len(){start+1}else{start};
                let fix=if start==end{None}else{fix_range(ctx,start,end,"")};
                // end col?
                out.push(warn(ctx,eff,info,idx+1,1,idx+1,2,msg,fix));
            }
        } else { consecutive=0; }
    }
}
