fn md018(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info); let magiclink=cfg.get_bool("magiclink").unwrap_or(false);
    for idx in 0..ctx.line_count(){
        let li=&ctx.lines[idx]; if li.in_code()||li.is_fence||li.in_frontmatter||li.is_frontmatter_delim{continue;}
        let line=ctx.line(idx);
        if let Some((indent,level,after))=parse_atx(line){
            let rest=&line[after..];
            if !rest.is_empty() && !rest.starts_with(|c:char| c.is_whitespace()){
                // magiclink: Obsidian flavor etc? If magiclink true maybe allow #-tag? skip for now
                let _=magiclink;
                // Column = after hashes char col (indent+level+1?)
                let col=indent+level+1;
                let startb=ctx.char_to_byte(idx,indent+level);
                out.push(warn(ctx,eff,info,idx+1,col,idx+1,line_end_col(ctx,idx),format!("No space after {} in heading", "#".repeat(level)),fix_range(ctx,startb,startb," ")));
                // Message probe: MD018 msg in probe_rules need check exact: It is "No space after # in heading" regardless level? Let's patch later based tests.
            }
        }
    }
}
fn md019(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    for idx in 0..ctx.line_count(){
        let li=&ctx.lines[idx]; if li.in_code()||li.is_fence||li.in_frontmatter||li.is_frontmatter_delim{continue;}
        let line=ctx.line(idx);
        if let Some((indent,level,after))=parse_atx(line){
            let rest=&line[after..];
            let spaces=rest.chars().take_while(|c| *c==' ').count();
            if spaces>1 && rest.trim().len()>0 || spaces>1 {
                // Only if there's content? "#  " empty heading maybe?
