                // For setext level2 expected 1 etc - replace underline line
                let uline=h.end_idx; let us=ctx.line_byte_start(uline); let ue=ctx.line_byte_end(uline);
                let repl=if new_level==1{"=".repeat(ctx.line(uline).trim().len().max(1))}else{"-".repeat(ctx.line(uline).trim().len().max(1))};
                Some(FixInfo{range:FixRange{start:us,end:ue},replacement:repl})
            } else {
                // convert to atx: replace text line only (as MD003 does)
                Some(FixInfo{range:FixRange{start,end:ctx.line_byte_end(h.line_idx)},replacement:format!("{} {}", "#".repeat(new_level), h.text)})
            }
        },
        _=>{
            let (indent,_lvl,after)=parse_atx(line)?;
            let indent_str=" ".repeat(indent);
            let rest=&line[after..];
            // Preserve spacing after hashes and closed style: reconstruction in probe: replacement is whole line with new hashes + original rest (including spaces and closing)
            // Rest includes leading space(s) if any. If no space (MD018 case), rest is text directly; MD001 fix would be "##Text"? probe later.
            let replacement=format!("{}{}{}", indent_str, "#".repeat(new_level), rest);
            Some(FixInfo{range:FixRange{start,end:ctx.line_byte_end(h.line_idx)},replacement})
        }
    }
}
pub fn has_frontmatter_title(ctx:&LintContext, field_pattern:Option<&str>)->bool{
    // YAML frontmatter only (--- ... ---)
    if ctx.frontmatter_kind.as_deref()!=Some("yaml"){return false;}
    let Some(fm)=ctx.frontmatter_str() else {return false};
    // field_pattern: for MD001, front-matter-title bool config doesn't give field name; use "title"
    // for MD025/MD041 callers pass pattern string differently - this helper for MD001 only checks title:
    for line in fm.lines(){ let t=line.trim(); if t.to_ascii_lowercase().starts_with("title:"){ let v=t[6..].trim(); if !v.is_empty(){return true;} } }
    false
}

fn md003(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info);
    let style_cfg=cfg.get_str("style").unwrap_or("consistent".into());
    let headings=get_headings(ctx);
    if headings.is_empty(){return;}
    // Determine expected style kind per heading based on config
    #[derive(Clone,Copy,PartialEq,Debug)] enum Sty{Atx,AtxClosed,Setext}
    let heading_sty=|h:&Heading| match h.style{HeadingStyle::Atx=>Sty::Atx,HeadingStyle::AtxClosed=>Sty::AtxClosed,HeadingStyle::Setext=>Sty::Setext};
    let expected_for=|h:&Heading, consistent:Sty|->Sty{
        match style_cfg.as_str(){
            "atx"=>Sty::Atx,
            "atx_closed"=>Sty::AtxClosed,
            "setext"=> if h.level<=2{Sty::Setext}else{Sty::Atx},
            "setext_with_atx"=> if h.level<=2{Sty::Setext}else{Sty::Atx},
            "setext_with_atx_closed"=> if h.level<=2{Sty::Setext}else{Sty::AtxClosed},
            _=>consistent // consistent and unknown
        }
    };
    // consistent = most prevalent, tie -> Atx preference (docs). Need determine tie logic counts including ATX for levels >2 setext inability?
    let consistent={
        let mut counts=[0usize;3];
        for h in &headings{ match heading_sty(h){Sty::Atx=>counts[0]+=1,Sty::AtxClosed=>counts[1]+=1,Sty::Setext=>counts[2]+=1} }
        // Order of preference on tie: Atx first, then? choose max with earliest in this order
        let order=[Sty::Atx,Sty::AtxClosed,Sty::Setext];
        let idx=[0,1,2]; let mut best=0; for i in 1..3{ if counts[i]>counts[best]{best=i;} } order[best]
    };
    for h in &headings{
        let expected=expected_for(h,consistent);
        let actual=heading_sty(h);
        if actual!=expected{
            let (exp_desc, found_desc)=match expected{ Sty::Atx=>("# Heading", match actual{Sty::Setext=> if h.level==1{"Heading (underlined with =)"}else{"Heading (underlined with -)"}, Sty::AtxClosed=>"# Heading #", Sty::Atx=>"# Heading"}), Sty::AtxClosed=>("# Heading #", match actual{Sty::Setext=> if h.level==1{"Heading (underlined with =)"}else{"Heading (underlined with -)"}, _=>"# Heading"}), Sty::Setext=>(if h.level==1{"Heading (underlined with =)"}else{"Heading (underlined with -)"}, match actual{Sty::AtxClosed=>"# Heading #",_=>"# Heading"}) };
            // Messages probed for some combos; refine later if needed
            let msg=format!("Heading style should be {exp_desc}, found {found_desc}");
            let fix=convert_heading_fix(ctx,h,expected);
            out.push(warn(ctx,eff,info,h.line_idx+1,1,h.line_idx+1,line_end_col(ctx,h.line_idx),msg,fix));
        }
    }
}
