fn md009(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info);
    let br_spaces=cfg.get_usize("br-spaces").unwrap_or(2);
    let strict=cfg.get_bool("strict").unwrap_or(false);
    let list_empty=cfg.get_bool("list-item-empty-lines").unwrap_or(false);
    for idx in 0..ctx.line_count(){
        let li=&ctx.lines[idx]; if li.in_fenced_code||li.is_fence{continue;}
        let line=ctx.line(idx);
        let trailing_contig=line.chars().rev().take_while(|c| *c==' ').count();
        if trailing_contig==0{continue;}
        let trimmed=line.trim_end();
        if trimmed.is_empty(){
            if list_empty && idx>0 {
                let prev=ctx.line(idx-1).trim_start();
                if crate::lint::is_list_item_line(prev){ continue; }
            }
            let start=ctx.line_byte_start(idx); let end=ctx.line_byte_end(idx);
            out.push(warn(ctx,eff,info,idx+1,1,idx+1,line.chars().count()+1,"Empty line has trailing spaces".into(),fix_range(ctx,start,end,"")));
            continue;
        }
        if !strict && trailing_contig==br_spaces{ continue; }
        // Bug-compatible: col/range based on trimmed (all whitespace) length
        let col=trimmed.chars().count()+1;
        let start_byte=ctx.line_byte_start(idx)+trimmed.len();
        let end_byte=start_byte+trailing_contig; // spaces are 1 byte each; if tab in suffix this may delete tab etc as observed (range length in bytes equals space count)
        let msg=if trailing_contig==1{"Trailing space found".to_string()}else{format!("{trailing_contig} trailing spaces found")};
        out.push(warn(ctx,eff,info,idx+1,col,idx+1,col+trailing_contig,msg,fix_range(ctx,start_byte,end_byte,"")));
    }
}
fn md010(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info); let spt=cfg.get_usize("spaces-per-tab").unwrap_or(4);
    for idx in 0..ctx.line_count(){
        let li=&ctx.lines[idx]; if li.in_fenced_code||li.is_fence{continue;}
        let line=ctx.line(idx); let chars:Vec<char>=line.chars().collect();
        let mut i=0;
        while i<chars.len(){
            if chars[i]=='\t'{
                let start=i; while i<chars.len()&&chars[i]=='\t'{i+=1;} let count=i-start;
                let byte_start=ctx.char_to_byte(idx,start); let byte_end=ctx.char_to_byte(idx,i);
                let repl=" ".repeat(count*spt);
                let msg=if start==0{
                    if count==1{format!("Found leading tab, use {} spaces instead", spt)}else{format!("Found {count} leading tabs, use {} spaces instead", count*spt)}
                } else {
                    if count==1{"Found tab for alignment, use spaces instead".to_string()}else{format!("Found {count} tabs for alignment, use spaces instead")}
                };
                out.push(warn(ctx,eff,info,idx+1,start+1,idx+1,start+count+1,msg,fix_range(ctx,byte_start,byte_end,&repl)));
            } else { i+=1; }
        }
    }
}
fn md011(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    // Pattern: (text)[url] where url looks like link destination (contains :// or mailto: or ...). Need examine false positives later.
    // Use scanning per line skipping code spans and fenced.
    for idx in 0..ctx.line_count(){
        let li=&ctx.lines[idx]; if li.in_code()||li.is_fence||li.in_frontmatter{continue;}
        let line=ctx.line(idx); let spans=code_span_ranges(line);
        let chars:Vec<char>=line.chars().collect(); let mut i=0;
        while i<chars.len(){
            if chars[i]=='(' && !in_code_span(&spans,i){
                // find matching ')'
                let mut depth=1; let mut j=i+1;
                while j<chars.len(){ if chars[j]=='(' {depth+=1;} else if chars[j]==')'{depth-=1; if depth==0{break;}} j+=1; }
                if depth==0 && j+1<chars.len() && chars[j+1]=='[' {
                    // find closing ]
                    let mut k=j+2; while k<chars.len()&&chars[k]!=']'{k+=1;}
                    if k<chars.len(){
                        let text:String=chars[i+1..j].iter().collect();
                        let url:String=chars[j+2..k].iter().collect();
                        if is_link_url(&url) && !text.is_empty() {
                            let startb=ctx.char_to_byte(idx,i); let endb=ctx.char_to_byte(idx,k+1);
                            let repl=format!("[{text}]({url})");
                            out.push(warn(ctx,eff,info,idx+1,i+1,idx+1,k+2,format!("Reversed link syntax: use {repl} instead"),fix_range(ctx,startb,endb,&repl)));
                            i=k+1; continue;
                        }
                    }
                }
            }
            i+=1;
        }
    }
}
pub fn is_link_url(url:&str)->bool{
    let u=url.trim();
    u.contains("://")||u.starts_with("mailto:")||u.starts_with("http:")||u.starts_with("https:")||u.starts_with("ftp:")|| (u.contains('@')&&u.contains('.'))
}
fn md012(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info); let maximum=cfg.get_usize("maximum").unwrap_or(1);
    let mut consecutive=0usize;
    for idx in 0..ctx.line_count(){
        let li=&ctx.lines[idx];
        if li.in_fenced_code||li.is_fence{ consecutive=0; continue; }
        let line=ctx.line(idx);
        if is_blank(line){
            consecutive+=1;
            if consecutive>maximum{
                // message location depends on context: between content / at start / at end - probe variants
                // Determine if there's content before and after in file (nonblank outside frontmatter?)
                let has_before=(0..idx).any(|i| !is_blank(ctx.line(i)) && !ctx.lines[i].is_frontmatter_delim);
                let has_after=(idx+1..ctx.line_count()).any(|i| !is_blank(ctx.line(i)));
                let msg=if has_before&&has_after{"Multiple consecutive blank lines between content".to_string()}else if !has_before{"Multiple consecutive blank lines at start of file".to_string()}else{"Multiple consecutive blank lines at end of file".to_string()};
                // Fix: delete this blank line's newline: range start = byte_end of line (position of \n) to +1 if not last line w/o newline; probed between content: line3 blank empty range start13 end14 = the newline char after blank line? content "# Chapter 1\n" (12) then blank line at 12 '\n', next blank line starts13 '\n' - warning line3 fix 13..14 deletes that newline.
                let start=ctx.line_byte_end(idx); let end=if start<ctx.content.len(){start+1}else{start};
                let fix=if start==end{None}else{fix_range(ctx,start,end,"")};
                // end col?
                out.push(warn(ctx,eff,info,idx+1,1,idx+1,2,msg,fix));
            }
        } else { consecutive=0; }
    }
}
