fn md020(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    for h in get_headings(ctx){ if h.style!=HeadingStyle::AtxClosed{continue;}
        let line=ctx.line(h.line_idx); let trimmed=line.trim_end();
        // find closing hashes run at end
        let chars:Vec<char>=trimmed.chars().collect(); let mut start_hash=chars.len(); while start_hash>0&&chars[start_hash-1]=='#'{start_hash-=1;}
        if start_hash==0||start_hash==chars.len(){continue;}
        if chars[start_hash-1]!=' ' && chars[start_hash-1]!='\t'{
            // No space before closing hashes
            let col=start_hash+1; let byte=ctx.char_to_byte(h.line_idx,start_hash);
            out.push(warn(ctx,eff,info,h.line_idx+1,col,h.line_idx+1,line_end_col(ctx,h.line_idx),"No space inside hashes on closed heading".to_string(),fix_range(ctx,byte,byte," ")));
        }
    }
