        let chars:Vec<char>=trimmed.chars().collect(); let mut start_hash=chars.len(); while start_hash>0&&chars[start_hash-1]=='#'{start_hash-=1;}
        if start_hash==0{continue;}
        let mut space_start=start_hash; while space_start>0&&chars[space_start-1]==' '{space_start-=1;}
        let spaces=start_hash-space_start;
        if spaces>1{
