            out.push(warn(ctx,eff,info,h.line_idx+1,space_start+1,h.line_idx+1,line_end_col(ctx,h.line_idx),"Multiple spaces inside hashes on closed heading".to_string(),fix_range(ctx,startb,endb," ")));
