fn md022(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info);
    let lines_above=cfg.get_usize("lines-above").unwrap_or(1);
    let lines_below=cfg.get_usize("lines-below").unwrap_or(1);
    let allowed_at_start=cfg.get_bool("allowed-at-start").unwrap_or(true);
    let headings=get_headings(ctx);
    for h in headings{
        // above
        if lines_above>0 {
            if h.line_idx==0 {
                if !allowed_at_start { /* probe semantics later */ }
            } else {
                // count blank lines immediately above (excluding frontmatter delimiter as boundary?)
                let mut count=0; let mut j=h.line_idx;
                while j>0 { j-=1; if ctx.lines[j].is_frontmatter_delim && j==ctx.frontmatter_lines.map(|x| x.1).unwrap_or(usize::MAX){ count=lines_above; break; } if is_blank(ctx.line(j)){count+=1;}else{break;} }
                // If heading is first content after frontmatter, MD071 handles blank after frontmatter; MD022 likely doesn't require above if previous is frontmatter delim (count set above)
                if count<lines_above {
                    let needed=lines_above-count;
                    let start=ctx.line_byte_start(h.line_idx);
                    // Fix range in probes: insertion at end of previous line (byte_end prev) replacement "\n" * needed
                    let fix_pos=if h.line_idx>0{ctx.line_byte_end(h.line_idx-1)}else{start};
                    let msg=if lines_above==1{format!("Expected 1 blank line above heading")}else{format!("Expected {lines_above} blank lines above heading")};
                    out.push(warn(ctx,eff,info,h.line_idx+1,1,h.line_idx+1,line_end_col(ctx,h.line_idx),msg,fix_range(ctx,fix_pos,fix_pos,&"\n".repeat(needed))));
                }
            }
        }
        if lines_below>0 {
            let after_idx=h.end_idx+1;
            if after_idx<ctx.line_count(){
                let mut count=0; let mut j=after_idx; while j<ctx.line_count()&&is_blank(ctx.line(j)){count+=1;j+=1;}
                if count<lines_below {
                    let needed=lines_below-count;
                    let fix_pos=ctx.line_byte_end(h.end_idx);
                    let msg=if lines_below==1{format!("Expected 1 blank line below heading")}else{format!("Expected {lines_below} blank lines below heading")};
                    out.push(warn(ctx,eff,info,h.line_idx+1,1,h.line_idx+1,line_end_col(ctx,h.line_idx),msg,fix_range(ctx,fix_pos,fix_pos,&"\n".repeat(needed))));
                }
            }
        }
    }
}
