fn md025(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info);
    let level=cfg.get_usize("level").unwrap_or(1);
    let fm_title_field=cfg.get_str("front-matter-title").unwrap_or("title".into());
    let allow_sections=cfg.get_bool("allow-document-sections").unwrap_or(false);
    let allow_sep=cfg.get_bool("allow-with-separators").unwrap_or(false);
    let headings=get_headings(ctx);
    let mut seen=0usize;
    // frontmatter title counts as one top-level heading if level==1 and field non-empty and matches in fm
    if level==1 && frontmatter_has_field(ctx,&fm_title_field){ seen=1; }
    for h in headings{
        if h.level!=level{continue;}
        if seen>=1{
            // check separators: if allow_document_sections / allow_with_separators and there's a thematic break since previous heading at this level, allow and reset? Probing later.
            let mut allowed=false;
            if allow_sections||allow_sep {
                // find previous heading of level - simplified: if any thematic break line between prev top heading and this, allowed
                // computed in rule_funcs2 maybe - keep false for now
            }
            if !allowed{
                let col=if h.style==HeadingStyle::Setext{1}else{h.indent+h.level+1};
                // Column in probes: "# A" second H1 at "# B" line col 3 - that's after "# " (?) level1 col3. For setext col1.
                let mut fix=None;
                if level<6 { fix=heading_level_fix(ctx,&h,level+1); }
                out.push(warn(ctx,eff,info,h.line_idx+1,col,h.line_idx+1,line_end_col(ctx,h.line_idx),format!("Multiple top-level headings (level {level}) in the same document"),fix));
            }
        }
        seen+=1;
    }
}
pub fn frontmatter_has_field(ctx:&LintContext, field:&str)->bool{
    if field.is_empty(){return false;}
    if ctx.frontmatter_kind.as_deref()!=Some("yaml"){return false;}
    let Some(fm)=ctx.frontmatter_str() else{return false};
    // field is a regex pattern in MD025 docs ("title" default regex?) It may use regex matching on fm start e.g. "^\\s*title\\s*:" Using field as regex pattern against fm?
    // Try regex crate: format pattern as given; if it's plain word, check keys case-insensitive
    // We'll implement: if pattern contains regex meta, use regex search on fm; else check line starts with field:
    let has_meta=field.chars().any(|c| "^$.*+?()[]{}|\\".contains(c));
    if has_meta {
        if let Ok(re)=regex::Regex::new(field){ return re.is_match(&fm); }
    }
    for line in fm.lines(){ let t=line.trim_start(); if let Some((k,v))=t.split_once(':'){ if k.trim().eq_ignore_ascii_case(field) && !v.trim().is_empty(){return true;} } }
    false
}
fn md026(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info); let punct=cfg.get_str("punctuation").unwrap_or(".,;:!".into());
    for h in get_headings(ctx){
        let text=h.text.trim_end();
        if text.is_empty(){continue;}
        let last=text.chars().last().unwrap();
        if punct.contains(last){
            // Column: heading text end position in raw line. For ATX: find last char position of text in line (account closing hashes)
            let line=ctx.line(h.line_idx);
            // Determine char idx of punctuation in raw line: search from end skipping closing hashes and spaces
            let mut chars:Vec<char>=line.chars().collect();
            // For setext, text line is line itself trimmed? Use trimmed length
            let pos_char=if h.style==HeadingStyle::Setext{ line.trim_end().chars().count() } else {
                // locate text substring: use rfind of last char before closing hashes
                let mut end=line.trim_end().len();
                // strip closing hashes/spaces for position: compute byte index of punct as trim_end of text portion
                // Simpler: find heading text in line after hashes
                let after=parse_atx(line).map(|x| x.2).unwrap_or(0);
                let rest=&line[after..];
                let rest_trimmed=rest.trim_start();
                let start_offset=line[..after].chars().count() + (rest.len()-rest_trimmed.len());
                // Text may include closing hashes stripped in h.text; punct is at start_offset + h.text.chars.count() -1 (char index), +1 col = that+1
                start_offset + h.text.chars().count()
            };
            let col=pos_char; // 1-based column of punct char is pos_char (since start_offset is count before text, +len-1 zero-based => +1 = start+len)
            // Fix: remove punctuation char (byte range of that char)
            let byte_start=ctx.char_to_byte(h.line_idx, col-1); let byte_end=ctx.char_to_byte(h.line_idx,col);
            out.push(warn(ctx,eff,info,h.line_idx+1,col,h.line_idx+1,line_end_col(ctx,h.line_idx),format!("Heading '{}' ends with punctuation '{}'", text,last),fix_range(ctx,byte_start,byte_end,"")));
        }
    }
}
fn md027(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    for idx in 0..ctx.line_count(){
        let li=&ctx.lines[idx]; if li.in_code()||li.is_fence||li.in_frontmatter{continue;}
        let line=ctx.line(idx);
        // match leading spaces (<=3?), then '>' (possibly repeated > >) then 2+ spaces
        let mut pos_chars=0usize; let chars:Vec<char>=line.chars().collect(); let mut i=0;
        while i<chars.len()&&chars[i]==' '{i+=1;}
        if i>3{continue;}
        // process each > marker
        let mut idx_char=i;
        let mut found=false;
        while idx_char<chars.len()&&chars[idx_char]=='>'{
            let mut j=idx_char+1; let mut spaces=0; while j<chars.len()&&chars[j]==' '{spaces+=1;j+=1;}
            if spaces>1 && j<chars.len() {
                let startb=ctx.char_to_byte(idx,idx_char+1); let endb=ctx.char_to_byte(idx,idx_char+1+spaces);
                out.push(warn(ctx,eff,info,idx+1,idx_char+1,idx+1,line_end_col(ctx,idx),"Multiple spaces after blockquote syntax".to_string(),fix_range(ctx,startb,endb," ")));
                found=true;
            }
            // move to next > if present after spaces (single space expected)
            idx_char=j;
