fn md028(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    // Blank line between two blockquote lines
    for idx in 0..ctx.line_count(){
        if !is_blank(ctx.line(idx)){continue;}
        if idx==0||idx+1>=ctx.line_count(){continue;}
        let prev=ctx.line(idx-1).trim_start(); let next=ctx.line(idx+1).trim_start();
        if prev.starts_with('>')&&next.starts_with('>'){
            let start=ctx.line_byte_start(idx);
            out.push(warn(ctx,eff,info,idx+1,1,idx+1,1,"Blank line inside blockquote".to_string(),fix_range(ctx,start,start,">")));
        }
    }
}
fn md041(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){ crate::rule_funcs2::md041(ctx,eff,info,out); }
fn md047(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    if ctx.content.is_empty(){return;}
    if !ctx.content.ends_with('\n'){
