new=r'''fn closed_heading_parts(line:&str)->Option<(usize,usize,usize,usize,usize,usize,String)>{
    // returns (indent, level, after_open_byte, start_spaces, end_spaces, close_hash_count, text)
    let (indent,level,after)=parse_atx(line)?;
    let trimmed_end=line.trim_end();
    let chars:Vec<char>=trimmed_end.chars().collect();
    let mut close_start=chars.len(); while close_start>0&&chars[close_start-1]=='#'{close_start-=1;}
    let close_count=chars.len()-close_start;
    if close_count==0{return None;}
    // closing hashes must not be the opening hashes themselves: there must be content or spaces between
    // Compute char indices: opening hashes occupy indent..indent+level in chars if no tabs (approx bytes=chars for # and spaces)
    let open_end_char=indent+level;
    if close_start<=open_end_char{return None;}
    let mut start_spaces=0; let mut i=open_end_char; while i<chars.len()&&chars[i]==' '{start_spaces+=1;i+=1;}
    let mut end_spaces=0; let mut j=close_start; while j>open_end_char&&chars[j-1]==' '{end_spaces+=1;j-=1;}
    // text between after start spaces and before end spaces
    let text_start=open_end_char+start_spaces; let text_end=close_start-end_spaces;
    if text_start>text_end{return None;}
    let text:String=chars[text_start..text_end].iter().collect();
    Some((indent,level,after,start_spaces,end_spaces,close_count,text))
}
