fn md018(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info); let magiclink=cfg.get_bool("magiclink").unwrap_or(false);
    for idx in 0..ctx.line_count(){
        let li=&ctx.lines[idx]; if li.in_code()||li.is_fence||li.in_frontmatter||li.is_frontmatter_delim{continue;}
        let line=ctx.line(idx);
        if let Some((indent,level,after))=parse_atx(line){
            let rest=&line[after..];
            if !rest.is_empty() && !rest.starts_with(|c:char| c.is_whitespace()){
                // Obsidian / magiclink exceptions
                if ctx.flavor==Flavor::Obsidian && level==1 {
