fn is_table_separator(line:&str)->bool{
    let t=line.trim();
    if !t.contains('|') && !t.contains('-'){return false;}
    // split by |
    let mut cells:Vec<&str>=t.split('|').collect();
    // remove empty first/last due leading/trailing pipe
    if cells.first().map(|s| s.trim().is_empty()).unwrap_or(false){cells.remove(0);}
    if cells.last().map(|s| s.trim().is_empty()).unwrap_or(false){cells.pop();}
    if cells.is_empty(){return false;}
    cells.iter().all(|c| { let x=c.trim(); let x=x.trim_start_matches(':').trim_end_matches(':'); !x.is_empty() && x.chars().all(|ch| ch=='-') })
}
pub fn table_line_set(ctx:&LintContext)->HashSet<usize>{
    let mut set=HashSet::new();
    let mut i=0;
    while i+1<ctx.line_count() {
        if ctx.lines[i].in_code()||ctx.lines[i].is_fence{ i+=1; continue; }
        let line=ctx.line(i);
        if line.contains('|') && !is_blank(line) && is_table_separator(ctx.line(i+1)) {
            set.insert(i); set.insert(i+1);
            let mut j=i+2;
            while j<ctx.line_count() && !is_blank(ctx.line(j)) && ctx.line(j).contains('|') && !ctx.lines[j].in_code() { set.insert(j); j+=1; }
            i=j; continue;
        }
        i+=1;
    }
    set
}

