            if idx+1<chars.len() && chars[idx]==']' && chars[idx+1]=='(' {
                // find closing )
                let mut j=idx+2; let mut depth=1;
                while j<chars.len(){ if chars[j]=='(' {depth+=1;} else if chars[j]==')'{depth-=1; if depth==0{break;}} j+=1; }
                if j<chars.len(){
                    let dest:String=chars[idx+2..j].iter().collect();
                    // destination is first token? Whole inside used for length determination - original seems whole dest string
                    out.push_str("](");
                    if dest.chars().count()>15 { out.push_str("..."); } else { out.push_str(&dest); }
                    out.push(')');
                    idx=j+1; continue;
                }
            }
