pub fn md013(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info);
    // effective line length: MD013 raw if present else global line_length (if global explicit or any - global default 80 same)
    let mut limit:u64 = if eff.config.rules.get("MD013").map(|m| m.contains_key("line-length")).unwrap_or(false) && !eff.invalid_rules.contains("MD013") { cfg.get_i64("line-length").map(|i| i as u64).unwrap_or(80) } else if eff.config.global_explicit.contains("line-length") { eff.config.global.line_length } else { cfg.get_i64("line-length").map(|i| i as u64).unwrap_or(80) };
    if limit==0{return;}
    let code_blocks=cfg.get_bool("code-blocks").unwrap_or(true);
    let tables=cfg.get_bool("tables").unwrap_or(false);
    let headings=cfg.get_bool("headings").unwrap_or(true);
    let paragraphs=cfg.get_bool("paragraphs").unwrap_or(true);
    let strict=cfg.get_bool("strict").unwrap_or(false);
    let reflow=cfg.get_bool("reflow").unwrap_or(false);
    let length_mode=cfg.get_str("length-mode").unwrap_or("visual".into());
    let heading_lines:HashSet<usize>=get_headings(ctx).iter().map(|h| h.line_idx).collect();
    let table_lines=table_line_set(ctx);
    for idx in 0..ctx.line_count(){
        let li=&ctx.lines[idx];
        if li.in_frontmatter||li.is_frontmatter_delim{continue;}
        let line=ctx.line(idx);
        if is_blank(line){continue;}
        let is_code=li.in_fenced_code||li.is_fence||li.in_indented_code;
        let is_heading=heading_lines.contains(&idx);
        let is_table=table_lines.contains(&idx);
        // categorization
        if is_code { if !code_blocks{continue;} }
        else if is_heading { if !headings{continue;} }
        else if is_table { if !tables{continue;} }
        else {
            // skip blockquote and HTML lines entirely (observed)
            let trimmed=line.trim_start();
            if trimmed.starts_with('>'){continue;}
            if trimmed.starts_with('<'){continue;}
            if !paragraphs{continue;}
            if !strict && is_ref_def_line(line){continue;}
        }
        let effective=shorten_for_length(line,strict);
        let len=visual_width(&effective,&length_mode) as u64;
        if len>limit{
            let col=(limit+1).min((line.chars().count()+1) as u64) as usize;
            let end_col=line.chars().count()+1;
            let fix=if reflow { crate::reflow::md013_fix(ctx,idx,eff) } else { None };
            out.push(warn(ctx,eff,info,idx+1,col,idx+1,end_col,format!("Line length {len} exceeds {limit} characters"),fix));
        }
    }
}

pub fn md014(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info); if !cfg.get_bool("show-output").unwrap_or(true){return;}
    let shell_langs=["bash","shell","sh","zsh","console","terminal","shellsession","shell-session",""];
    for cb in &ctx.code_blocks {
        let lang=cb.lang.to_ascii_lowercase();
        if !shell_langs.contains(&lang.as_str()){continue;}
        let end=cb.end_line.unwrap_or(ctx.line_count());
        let mut commands:Vec<(usize,String)>=Vec::new();
        let mut has_output=false;
        for idx in cb.start_line+1..end {
            let line=ctx.line(idx);
            if is_blank(line){continue;}
            let t=line.trim_start();
            if t.starts_with("$ ")||t=="$" { commands.push((idx,t.to_string())); } else { has_output=true; break; }
        }
        if !commands.is_empty() && !has_output {
            let first_idx=commands[0].0;
            let first_cmd=commands[0].1.trim_start_matches('$').trim().to_string();
            // Fix range: start of first code line to end of last code line including its newline if present
            let start=ctx.line_byte_start(cb.start_line+1);
            let last_idx=end.saturating_sub(1);
            let mut endb=ctx.line_byte_end(last_idx);
            if endb<ctx.content.len() && ctx.content.as_bytes().get(endb)==Some(&b'\n'){ endb+=1; }
            // replacement preserves blank lines between commands and indentation? Build from original lines stripping leading $ prompt preserving indent before $?
            let mut repl=String::new();
            for idx in cb.start_line+1..end {
                let line=ctx.line(idx);
                if is_blank(line){ repl.push('\n'); continue; }
                // Remove "$ " after indent
                let mut chars=line.chars().peekable(); let mut prefix=String::new(); while let Some(&c)=chars.peek(){ if c==' '||c=='\t'{prefix.push(c); chars.next();}else{break;} }
                let rest:String=chars.collect();
                let stripped=if rest.starts_with("$ "){&rest[2..]}else if rest=="$"{""}else{&rest};
                repl.push_str(&prefix); repl.push_str(stripped); repl.push('\n');
            }
            out.push(warn(ctx,eff,info,first_idx+1,1,first_idx+1,line_end_col(ctx,first_idx),format!("Command '{first_cmd}' should show output (add example output or remove $ prompt)"),fix_range(ctx,start,endb,&repl)));
        }
    }
}

pub fn md024(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info);
    let siblings_only=cfg.get_bool("siblings-only").unwrap_or(true);
    let allow_diff_nesting=cfg.get_bool("allow-different-nesting").unwrap_or(false);
    let headings=get_headings(ctx);
    let norm=|s:&str| s.trim().to_ascii_lowercase();
    if siblings_only {
        // key: (parent line idx (-1 for root as i64), level, text) -- but allow_different_nesting may change parent definition to parent level only?
        let mut seen:HashMap<(i64,usize,String),()>=HashMap::new();
        let mut stack:Vec<(usize,usize,String)>=Vec::new(); // level,line_idx,text
        for h in &headings{
            while let Some(top)=stack.last(){ if top.0>=h.level{stack.pop();}else{break;} }
            let parent_line=stack.last().map(|x| x.1 as i64).unwrap_or(-1);
            let key=(parent_line,h.level,norm(&h.text));
            if seen.contains_key(&key){
                let col=heading_text_col(ctx,h);
                out.push(warn(ctx,eff,info,h.line_idx+1,col,h.line_idx+1,line_end_col(ctx,h.line_idx),format!("Duplicate heading: '{}'.",h.text),None));
            } else { seen.insert(key,()); }
            stack.push((h.level,h.line_idx,h.text.clone()));
        }
    } else {
        let mut seen:HashMap<(String,Option<usize>),()>=HashMap::new();
        for h in &headings{
            let key=(norm(&h.text), if allow_diff_nesting{Some(h.level)}else{None});
            if seen.contains_key(&key){ let col=heading_text_col(ctx,h); out.push(warn(ctx,eff,info,h.line_idx+1,col,h.line_idx+1,line_end_col(ctx,h.line_idx),format!("Duplicate heading: '{}'.",h.text),None)); } else {seen.insert(key,());}
        }
    }
}
pub fn heading_text_col(ctx:&LintContext,h:&Heading)->usize{
    if h.style==HeadingStyle::Setext{ return h.indent+1; }
    let line=ctx.line(h.line_idx); if let Some((indent,level,after))=parse_atx(line){ let spaces=line[after..].chars().take_while(|c| *c==' '||*c=='\t').count(); return indent+level+spaces+1; }
    1
}

pub fn md041(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info);
    let level=cfg.get_usize("level").unwrap_or(1);
    let fix_enabled=cfg.get_bool("fix").unwrap_or(false);
    let fm_field=cfg.get_str("front-matter-title").unwrap_or("title".into());
    let fm_pattern=cfg.get_str("front-matter-title-pattern").unwrap_or_default();
    // frontmatter title check
    if ctx.frontmatter_kind.as_deref()==Some("yaml") {
        if !fm_pattern.is_empty(){
            if let Ok(re)=regex::RegexBuilder::new(&fm_pattern).multi_line(true).build(){ if let Some(fm)=ctx.frontmatter_str(){ if re.is_match(&fm){return;} } }
        } else if !fm_field.is_empty() && frontmatter_has_field(ctx,&fm_field){ return; }
    }
    // find first content line skipping frontmatter, blanks, html comments (whole-line)
    let start_idx=ctx.frontmatter_lines.map(|(_,b)| b+1).unwrap_or(0);
    let mut i=start_idx; let mut in_comment=false;
    let mut first_idx:Option<usize>=None;
    while i<ctx.line_count(){
        let line=ctx.line(i); let t=line.trim();
        if in_comment { if t.contains("-->") { let after=t.split("-->").last().unwrap_or(""); if after.trim().is_empty(){ in_comment=false; i+=1; continue; } else { first_idx=Some(i); break; } } else { i+=1; continue; } }
        if t.is_empty(){ i+=1; continue; }
        if t.starts_with("<!--") {
            if t.contains("-->") { let after=t.rsplit("-->").next().unwrap_or(""); if after.trim().is_empty(){ i+=1; continue; } else { first_idx=Some(i); break; } } else { in_comment=true; i+=1; continue; }
        }
        // MkDocs anchor lines skip - handled later with flavor
        first_idx=Some(i); break;
    }
    let Some(fi)=first_idx else{return;};
    let line=ctx.line(fi); let t=line.trim_start();
    // HTML heading
    if t.to_ascii_lowercase().starts_with("<h") && t.len()>=3 {
        let ch=t.chars().nth(2).unwrap_or(' ');
        if ch.is_ascii_digit() { let hl=ch as usize - '0' as usize; if hl==level{return;} }
    }
    // heading at this line
    let headings=get_headings(ctx);
    let mut is_heading_wrong=false;
    if let Some(h)=headings.iter().find(|h| h.line_idx==fi){ if h.level==level{return;} is_heading_wrong=true; }
    // warning
    let fix=if fix_enabled && is_heading_wrong { Some(FixInfo{range:FixRange{start:ctx.line_byte_start(fi),end:ctx.line_byte_end(fi)},replacement:String::new()}) } else { None };
    out.push(warn(ctx,eff,info,fi+1,1,fi+1,line_end_col(ctx,fi),format!("First line in file should be a level {level} heading"),fix));
}
