fn custom_fix(code:&str, content:&str, cfg:&Config, enabled:&[&RuleInfo], flavor:Flavor, file_path:Option<std::path::PathBuf>)->Option<String>{
    let eff=crate::rules::validate_and_build(cfg);
    let info=crate::info::rule_by_code(code)?;
    let rc=crate::rules::RuleCfg{eff:&eff,code};
    let ctx=LintContext::new(content,flavor,file_path);
    match code {
        "MD001"=>{
            let front=rc.get_bool("front-matter-title").unwrap_or(true);
            let mut prev:usize=if front&&crate::rule_funcs::has_frontmatter_title(&ctx,None){1}else{0};
            let headings=crate::rule_funcs::get_headings(&ctx);
            let mut edits:Vec<(usize,usize,String)>=Vec::new();
            for h in &headings{
                let corrected=if prev>0&&h.level>prev+1{prev+1}else{h.level};
                let line=ctx.line(h.line_idx);
                let repl=match h.style{
                    crate::rule_funcs::HeadingStyle::Setext=>{
                        if corrected<=2{ let ch=if corrected==1{"="}else{"-"}; format!("{}\n{}", h.text, ch.repeat(h.text.chars().count().max(1))) } else { format!("{} {}", "#".repeat(corrected), h.text) }
                    },
                    _=>{
                        if let Some((indent,_,after))=crate::rule_funcs::parse_atx(line){ format!("{}{}{}", " ".repeat(indent), "#".repeat(corrected), &line[after..]) } else { line.to_string() }
                    }
                };
                edits.push((ctx.line_byte_start(h.line_idx),ctx.line_byte_end(h.line_idx),repl));
                prev=corrected;
            }
            edits.sort_by(|a,b| b.0.cmp(&a.0)); let mut out=content.to_string(); for (s,e,r) in edits{ out.replace_range(s..e,&r); } Some(out)
        },
        "MD025"=>{
            let level=rc.get_usize("level").unwrap_or(1);
            let field=rc.get_str("front-matter-title").unwrap_or("title".into());
            let mut seen=if level==1&&crate::rule_funcs::frontmatter_has_field(&ctx,&field){1}else{0};
            let headings=crate::rule_funcs::get_headings(&ctx);
            let mut edits:Vec<(usize,usize,String)>=Vec::new();
            for h in &headings{
                if h.level!=level{continue;}
                if seen>=1 {
                    let new_level=level+1; if new_level>6{continue;}
                    match h.style{
                        crate::rule_funcs::HeadingStyle::Setext=>{
                            if new_level<=2{ let ch=if new_level==1{"="}else{"-"}; edits.push((ctx.line_byte_start(h.end_idx),ctx.line_byte_end(h.end_idx),ch.repeat(h.text.chars().count().max(1)))); }
                            else { edits.push((ctx.line_byte_start(h.line_idx),ctx.line_byte_end(h.end_idx),format!("{} {}", "#".repeat(new_level), h.text))); }
                        },
                        _=>{
                            let line=ctx.line(h.line_idx); if let Some((indent,_,after))=crate::rule_funcs::parse_atx(line){ edits.push((ctx.line_byte_start(h.line_idx),ctx.line_byte_end(h.line_idx),format!("{}{}{}", " ".repeat(indent), "#".repeat(new_level), &line[after..]))); }
                        }
                    }
                }
                seen+=1;
            }
            edits.sort_by(|a,b| b.0.cmp(&a.0)); let mut out=content.to_string(); for (s,e,r) in edits{ out.replace_range(s..e,&r); } Some(out)
        },
        "MD041"=>{
            if !rc.get_bool("fix").unwrap_or(false){return None;}
            let level=rc.get_usize("level").unwrap_or(1);
            let headings=crate::rule_funcs::get_headings(&ctx);
            // find first heading that is the first content (warning line) - use first heading overall if its line is before any nonblank non-comment content; simpler: take first heading in doc and verify all lines before it (after fm) are blank or html comments
            let h=headings.first()?;
            let start_idx=ctx.frontmatter_lines.map(|(_,b)| b+1).unwrap_or(0);
            // check preamble
            let mut in_comment=false; let mut ok=true;
            for i in start_idx..h.line_idx{ let t=ctx.line(i).trim(); if in_comment{ if t.contains("-->"){in_comment=false;} continue; } if t.is_empty(){continue;} if t.starts_with("<!--"){ if !t.contains("-->"){in_comment=true;} continue; } ok=false; break; }
            if !ok{return None;}
            // build new heading line(s)
            let new_heading_line=match h.style{
                crate::rule_funcs::HeadingStyle::Setext=>format!("{} {}", "#".repeat(level), h.text),
                _=>{ let line=ctx.line(h.line_idx); if let Some((indent,_,after))=crate::rule_funcs::parse_atx(line){ format!("{}{}{}", " ".repeat(indent), "#".repeat(level), &line[after..]) } else { line.to_string() } }
            };
            // Remove original heading lines (text..end inclusive plus their newlines) and insert at start_idx
            let remove_start=ctx.line_byte_start(h.line_idx);
            let remove_end=if h.end_idx+1<ctx.line_count(){ctx.line_byte_start(h.end_idx+1)}else{ctx.content.len()};
            let insert_pos=if start_idx<ctx.line_count(){ctx.line_byte_start(start_idx)}else{ctx.content.len()};
            let mut out=content.to_string();
            // Remove first (ranges after insert_pos)
            out.replace_range(remove_start..remove_end,"");
            out.insert_str(insert_pos,&format!("{new_heading_line}\n"));
            Some(out)
        },
        _=>None
    }
}
