fn marker_fix(ctx:&LintContext,item:&ListItem,repl:&str)->Option<FixInfo>{
    let start=ctx.char_to_byte(item.line_idx,item.marker_char_start); Some(FixInfo{range:FixRange{start,end:start+1},replacement:repl.to_string()})
}

fn md004(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info); let style=cfg.get_str("style").unwrap_or("consistent".into());
    let items=get_list_items(ctx);
    let ul:Vec<&ListItem>=items.iter().filter(|i| !i.ordered).collect();
    if ul.is_empty(){return;}
    // consistent expected
    let consistent={
        let mut counts:HashMap<char,usize>=HashMap::new(); for it in &ul{ *counts.entry(it.marker.chars().next().unwrap()).or_default()+=1; }
        // priority tie: '-' > '*' > '+'
        let order=['-','*','+']; let mut best='-'; let mut bestn=0; for c in order{ let n=*counts.get(&c).unwrap_or(&0); if n>bestn{bestn=n;best=c;} } best
    };
    for it in ul {
        let actual=it.marker.chars().next().unwrap();
        let (expected,msg)=match style.as_str() {
            "asterisk"=>('*',format!("List marker '{}' does not match expected style '*'",actual)),
            "plus"=>('+',format!("List marker '{}' does not match expected style '+'",actual)),
            "dash"=>('-',format!("List marker '{}' does not match expected style '-'",actual)),
            "sublist"=>{ let exp=['*','+','-'][it.level%3]; (exp,format!("List marker '{}' does not match expected style '{}' for nesting level {}",actual,exp,it.level)) },
            _=>(consistent,format!("List marker '{}' does not match expected style '{}'",actual,consistent)),
        };
        if actual!=expected{
            out.push(warn(ctx,eff,info,it.line_idx+1,it.marker_char_start+1,it.line_idx+1,it.marker_char_start+2,msg,marker_fix(ctx,it,&expected.to_string())));
        }
    }
}

fn md005(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let items=get_list_items(ctx);
    // Group by (block adjusted, level). Adjust block when top-level orderedness changes.
    let mut expected:HashMap<(usize,usize),usize>=HashMap::new();
    let mut adj_block=0usize; let mut last_root_ordered:Option<bool>=None; let mut current_block=usize::MAX;
    for it in &items {
        if it.block_id!=current_block{ current_block=it.block_id; adj_block+=1; last_root_ordered=None; }
        if it.level==0 {
            if let Some(prev_ord)=last_root_ordered{ if prev_ord!=it.ordered{ adj_block+=1; } }
            last_root_ordered=Some(it.ordered);
        }
        let key=(adj_block,it.level);
        if let Some(exp)=expected.get(&key){
            if it.indent!=*exp{
                let start=ctx.char_to_byte(it.line_idx,it.bq_chars); let end=ctx.char_to_byte(it.line_idx,it.marker_char_start);
                out.push(warn(ctx,eff,info,it.line_idx+1,1,it.line_idx+1,it.marker_char_start+1,format!("Expected indentation of {} spaces, found {}",exp,it.indent),fix_range(ctx,start,end,&" ".repeat(*exp))));
            }
        } else { expected.insert(key,it.indent); }
    }
}

pub fn md007_effective_style(eff:&EffectiveConfig)->String{
    let raw=eff.config.rules.get("MD007");
    let has_style=raw.map(|m| m.contains_key("style")).unwrap_or(false);
    let has_indent=raw.map(|m| m.contains_key("indent")).unwrap_or(false);
    if eff.invalid_rules.contains("MD007") { return "text-aligned".to_string(); }
    if has_style { if let Some(toml::Value::String(s))=raw.and_then(|m| m.get("style")){ return s.clone(); } }
    if has_indent { return "fixed".to_string(); }
    "text-aligned".to_string()
}
fn md007(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info);
    let indent_cfg=cfg.get_usize("indent").unwrap_or(2);
    let start_indented=cfg.get_bool("start-indented").unwrap_or(false);
    let start_indent=cfg.get_usize("start-indent").unwrap_or(2);
    let style=md007_effective_style(eff);
    let items=get_list_items(ctx);
    // expected indent map by item index in items vec computed recursively (parents indices refer to items positions as stored in parent field? Our ListItem.parent is index into items vec (my_idx at push). Good.
    let mut expected_map:HashMap<usize,usize>=HashMap::new();
    for (idx,it) in items.iter().enumerate(){
        let exp=if it.level==0 { if start_indented{start_indent}else{0} } else {
            let parent=it.parent.and_then(|pi| items.get(pi));
            if style=="fixed" && !(parent.map(|p| p.ordered).unwrap_or(false)) {
                (if start_indented{start_indent}else{0}) + it.level*indent_cfg
            } else {
                // text-aligned (or parent ordered)
                if let Some(p)=parent{ let p_exp=*expected_map.get(&it.parent.unwrap()).unwrap_or(&p.indent); p_exp + p.marker.chars().count() + p.after_spaces.max(1) } else { it.level*indent_cfg }
                // after_spaces in visual terms: if tab, count approx 1? parent after_spaces is chars - use visual: for typical one space fine
            }
        };
        expected_map.insert(idx,exp);
        if it.ordered{continue;}
        if it.indent!=exp{
            let start=ctx.char_to_byte(it.line_idx,it.bq_chars); let end=ctx.char_to_byte(it.line_idx,it.marker_char_start);
            out.push(warn(ctx,eff,info,it.line_idx+1,1,it.line_idx+1,it.marker_char_start+1,format!("Expected {} spaces for indent depth {}, found {}",exp,it.level,it.indent),fix_range(ctx,start,end,&" ".repeat(exp))));
        }
    }
}

fn md030(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info);
    let ul_single=cfg.get_usize("ul-single").unwrap_or(1); let ul_multi=cfg.get_usize("ul-multi").unwrap_or(1); let ol_single=cfg.get_usize("ol-single").unwrap_or(1); let ol_multi=cfg.get_usize("ol-multi").unwrap_or(1);
    let items=get_list_items(ctx);
    for (idx,it) in items.iter().enumerate(){
        if it.line_idx>=ctx.line_count(){continue;}
        // Determine if this item is multi-line: any line after it before next item at level <= it.level (in items order) that is not blank? Or blank lines within item.
        let mut multi=false;
        let next_item_line=items.iter().skip(idx+1).find(|n| n.level<=it.level).map(|n| n.line_idx).unwrap_or(ctx.line_count());
        // Lines between this item and next sibling/ancestor: if count of lines >1 (excluding trailing blank lines at end of doc/block)
        let mut last_nonblank=it.line_idx;
        for j in it.line_idx+1..next_item_line{ if !is_blank(ctx.line(j)){ last_nonblank=j; } }
        if last_nonblank>it.line_idx{ multi=true; }
        let expected=if it.ordered{ if multi{ol_multi}else{ol_single} } else { if multi{ul_multi}else{ul_single} };
        // Actual spaces: count space chars only? Tabs count? Original after marker tab might be considered 1? Use after_spaces chars where tab counts as? For now chars.
        let actual=it.after_spaces;
        // Empty list item (no content) - after_spaces may be trailing spaces; markdownlint may skip? Test later.
        let content_empty=it.content_char_start>=ctx.line(it.line_idx).chars().count();
        if content_empty{continue;}
        if actual!=expected{
            let start_char=it.marker_char_start+it.marker.chars().count();
            let start=ctx.char_to_byte(it.line_idx,start_char); let end=ctx.char_to_byte(it.line_idx,start_char+actual);
            out.push(warn(ctx,eff,info,it.line_idx+1,start_char+1,it.line_idx+1,start_char+actual+1,format!("Spaces after list markers (Expected: {expected}; Actual: {actual})"),fix_range(ctx,start,end,&" ".repeat(expected))));
        }
    }
}

fn md031(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info); let _list_items=cfg.get_bool("list-items").unwrap_or(true);
    for cb in &ctx.code_blocks{
        // before
        if cb.start_line>0 && !is_blank(ctx.line(cb.start_line-1)) && !ctx.lines[cb.start_line-1].is_frontmatter_delim {
            let pos=ctx.line_byte_start(cb.start_line);
            out.push(warn(ctx,eff,info,cb.start_line+1,1,cb.start_line+1,line_end_col(ctx,cb.start_line),"No blank line before fenced code block".to_string(),fix_range(ctx,pos,pos,"\n")));
        }
        if let Some(end_line)=cb.end_line{
            if end_line+1<ctx.line_count() && !is_blank(ctx.line(end_line+1)) {
                let pos=ctx.line_byte_end(end_line);
                out.push(warn(ctx,eff,info,end_line+1,1,end_line+1,line_end_col(ctx,end_line),"No blank line after fenced code block".to_string(),fix_range(ctx,pos,pos,"\n")));
            }
        }
    }
}
fn md032(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info); let allow_lazy=cfg.get_bool("allow-lazy-continuation").unwrap_or(true);
    let items=get_list_items(ctx);
    if items.is_empty(){return;}
    // Group by block_id, consider only top-level start and end per block
    let mut blocks:BTreeMap<usize,Vec<&ListItem>>=BTreeMap::new(); for it in &items{blocks.entry(it.block_id).or_default().push(it);}
    for (_bid,its) in blocks{
        let first=its[0];
        // before: previous line nonblank and not frontmatter delim and not a list item (it isn't by grouping)
        if first.line_idx>0 && !is_blank(ctx.line(first.line_idx-1)) && !ctx.lines[first.line_idx-1].is_frontmatter_delim {
            // If previous line is inside a list item? No first is start.
            let pos=ctx.line_byte_start(first.line_idx);
            out.push(warn(ctx,eff,info,first.line_idx+1,1,first.line_idx+1,line_end_col(ctx,first.line_idx),"List should be preceded by blank line".to_string(),fix_range(ctx,pos,pos,"\n")));
        }
        // Determine last line belonging to list block: last item's line plus its continuation lines (indented or lazy?) Until blank / next non-indent content
        let last_item=its[its.len()-1];
        let mut end_idx=last_item.line_idx;
        let mut j=end_idx+1;
        while j<ctx.line_count(){
            let line=ctx.line(j);
            if is_blank(line){ break; }
            // continuation lines are indented or (lazy) paragraph lines - if allow_lazy, treat following nonblank paragraph as continuation and do not flag after
            let indent=visual_col_of_prefix(&line.chars().take_while(|c| *c==' '||*c=='\t').collect::<String>());
            let is_heading=get_headings(ctx).iter().any(|h| h.line_idx==j);
            if is_heading || ctx.lines[j].is_fence || is_thematic_break(line){ break; }
            if indent>0 { end_idx=j; j+=1; continue; }
            // lazy continuation at indent 0
            if allow_lazy {
                // If this line could be a new paragraph, original still treats as continuation (no after warning in docs example) - so consume all consecutive nonblank lines as continuation and suppress after check entirely
                // Mark end at this line and suppress
                end_idx=j; 
                // Consume rest of paragraph
                j+=1; while j<ctx.line_count()&&!is_blank(ctx.line(j)){end_idx=j;j+=1;}
                break;
            } else {
                // Without lazy: this line is continuation that should be indented - warning is different (see docs: fix indents it). Original probe needed; for now treat as after-list content requiring blank and fix by indenting? handled below special
                break;
            }
        }
        // after check
        let after=end_idx+1;
        if after<ctx.line_count() && !is_blank(ctx.line(after)) {
            if allow_lazy {
                // If we consumed lazy paragraph above, after would be blank/eof; if after is heading/fence/hr and directly after list item, flag
                let pos=ctx.line_byte_end(end_idx);
                out.push(warn(ctx,eff,info,after+1,1,after+1,line_end_col(ctx,after),"List should be followed by blank line".to_string(),fix_range(ctx,pos,pos,"\n")));
            } else {
                // Lazy continuation line at after (indent 0, non-heading)
                let line=ctx.line(after);
                let is_heading=get_headings(ctx).iter().any(|h| h.line_idx==after);
                if !is_heading && !ctx.lines[after].is_fence && !is_thematic_break(line){
                    // Message/fix for lazy continuation need probing; placeholder uses followed message with indent fix
                    let content_col=last_item.content_col;
                    let pos=ctx.line_byte_start(after);
                    out.push(warn(ctx,eff,info,after+1,1,after+1,line_end_col(ctx,after),"List should be followed by blank line".to_string(),fix_range(ctx,pos,pos,&" ".repeat(content_col))));
                } else {
                    let pos=ctx.line_byte_end(end_idx);
                    out.push(warn(ctx,eff,info,after+1,1,after+1,line_end_col(ctx,after),"List should be followed by blank line".to_string(),fix_range(ctx,pos,pos,"\n")));
                }
            }
        }
    }
}
fn md035(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info); let style_cfg=cfg.get_str("style").unwrap_or("consistent".into());
    // Collect HR lines: thematic break and not setext underline (get_headings setext end lines excluded) and not in code/frontmatter/list?
    let setext_ends:HashSet<usize>=get_headings(ctx).iter().filter(|h| h.style==HeadingStyle::Setext).map(|h| h.end_idx).collect();
    let mut hrs:Vec<(usize,String)>=Vec::new();
    for idx in 0..ctx.line_count(){
        let li=&ctx.lines[idx]; if li.in_code()||li.is_fence||li.in_frontmatter||li.is_frontmatter_delim{continue;}
        if setext_ends.contains(&idx){continue;}
        let line=ctx.line(idx);
        if is_thematic_break(line){
            // A line of dashes after a paragraph would be setext u handled. Also list item "- - -" is HR in CommonMark ambiguous - if line is list item with content "- -" our is_thematic_break of all dashes/spaces would count; original likely uses context
            hrs.push((idx,line.trim().to_string()));
        }
    }
    if hrs.is_empty(){return;}
    let expected=if style_cfg=="consistent"||style_cfg.is_empty(){ hrs[0].1.clone() } else { style_cfg.clone() };
    for (idx,actual) in hrs{
        if actual!=expected{
            let line=ctx.line(idx);
            // Fix whole line? Probe shows range likely line
            out.push(warn(ctx,eff,info,idx+1,1,idx+1,line_end_col(ctx,idx),format!("Expected: {expected}; Actual: {actual}"),whole_line_fix(ctx,idx,expected.clone())));
            let _=line;
        }
    }
}
fn md046(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info); let style_cfg=cfg.get_str("style").unwrap_or("consistent".into());
    // Identify code blocks: fenced blocks from ctx, indented blocks are groups of in_indented_code lines not list items
    #[derive(PartialEq,Clone,Copy,Debug)] enum Kind{Fenced,Indented}
    let mut blocks:Vec<(usize,Kind,Vec<usize>)>=Vec::new();
    for cb in &ctx.code_blocks{ blocks.push((cb.start_line,Kind::Fenced,(cb.start_line..=cb.end_line.unwrap_or(ctx.line_count().saturating_sub(1))).collect())); }
    let mut i=0; while i<ctx.line_count(){ if ctx.lines[i].in_indented_code{ let start=i; let mut lines=vec![]; while i<ctx.line_count()&&(ctx.lines[i].in_indented_code||is_blank(ctx.line(i))){ if ctx.lines[i].in_indented_code{lines.push(i);} i+=1; } if !lines.is_empty(){blocks.push((start,Kind::Indented,lines));} } else {i+=1;} }
    blocks.sort_by_key(|b| b.0);
    if blocks.is_empty(){return;}
    let expected_kind=match style_cfg.as_str(){ "fenced"=>Kind::Fenced,"indented"=>Kind::Indented,_=>blocks[0].1 };
    for (start,kind,lines) in &blocks{
        if *kind!=expected_kind{
            let exp_str=match expected_kind{Kind::Fenced=>"Fenced",Kind::Indented=>"Indented"};
            let act_str=match kind{Kind::Fenced=>"Fenced",Kind::Indented=>"Indented"};
            // Message probe needed
            let fix=convert_code_block_fix(ctx,*kind,expected_kind,lines);
            out.push(warn(ctx,eff,info,start+1,1,start+1,line_end_col(ctx,*start),format!("Code block style: Expected {exp_str}; Actual: {act_str}"),fix));
        }
    }
    fn convert_code_block_fix(ctx:&LintContext,from:impl std::fmt::Debug,to:impl std::fmt::Debug,lines:&[usize])->Option<FixInfo>{ None }
}
fn md048(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info); let style_cfg=cfg.get_str("style").unwrap_or("consistent".into());
    if ctx.code_blocks.is_empty(){return;}
    let expected_char:char=match style_cfg.as_str(){ "backtick"=>'`',"tilde"=>'~',_=>ctx.code_blocks[0].fence_char };
    let exp_name=if expected_char=='`'{"Backtick"}else{"Tilde"};
    for cb in &ctx.code_blocks{
        if cb.fence_char!=expected_char{
            // Warning at opening fence only? Or both fences counted as one? Probe later
            let line_idx=cb.start_line;
            let line=ctx.line(line_idx);
            // fix replace fence chars in opening and closing - warning fix may be just opening line; iterative will fix closing in next pass if separate warnings? We'll make fix for opening only here and add closing warning if original does - test via compare
            let mut new_line=line.to_string();
