            if let Some(pos)=new_line.find(cb.fence_char){ let fence_str=expected_char.to_string().repeat(cb.fence_len); new_line.replace_range(pos..pos+cb.fence_len,&fence_str); }
            out.push(warn(ctx,eff,info,line_idx+1,1,line_idx+1,line_end_col(ctx,line_idx),format!("Code fence style: Expected {exp_name}; Actual: {}", if cb.fence_char=='`'{"Backtick"}else{"Tilde"}),whole_line_fix(ctx,line_idx,new_line)));
            if let Some(end_idx)=cb.end_line{
                let line2=ctx.line(end_idx); let mut new_line2=line2.to_string(); if let Some(pos)=new_line2.find(cb.fence_char){ let count=new_line2[pos..].chars().take_while(|c| *c==cb.fence_char).count(); new_line2.replace_range(pos..pos+count,&expected_char.to_string().repeat(count)); }
                out.push(warn(ctx,eff,info,end_idx+1,1,end_idx+1,line_end_col(ctx,end_idx),format!("Code fence style: Expected {exp_name}; Actual: {}", if cb.fence_char=='`'{"Backtick"}else{"Tilde"}),whole_line_fix(ctx,end_idx,new_line2)));
            }
        }
    }
}
