fn marker_fix(ctx:&LintContext,item:&ListItem,repl:&str)->Option<FixInfo>{
    let start=ctx.char_to_byte(item.line_idx,item.marker_char_start); Some(FixInfo{range:FixRange{start,end:start+1},replacement:repl.to_string()})
}

fn md004(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info); let style=cfg.get_str("style").unwrap_or("consistent".into());
    let items=get_list_items(ctx);
    let ul:Vec<&ListItem>=items.iter().filter(|i| !i.ordered).collect();
    if ul.is_empty(){return;}
    // consistent expected
    let consistent={
        let mut counts:HashMap<char,usize>=HashMap::new(); for it in &ul{ *counts.entry(it.marker.chars().next().unwrap()).or_default()+=1; }
        // priority tie: '-' > '*' > '+'
        let order=['-','*','+']; let mut best='-'; let mut bestn=0; for c in order{ let n=*counts.get(&c).unwrap_or(&0); if n>bestn{bestn=n;best=c;} } best
    };
    for it in ul {
        let actual=it.marker.chars().next().unwrap();
        let (expected,msg)=match style.as_str() {
            "asterisk"=>('*',format!("List marker '{}' does not match expected style '*'",actual)),
            "plus"=>('+',format!("List marker '{}' does not match expected style '+'",actual)),
            "dash"=>('-',format!("List marker '{}' does not match expected style '-'",actual)),
            "sublist"=>{ let exp=['*','+','-'][it.level%3]; (exp,format!("List marker '{}' does not match expected style '{}' for nesting level {}",actual,exp,it.level)) },
            _=>(consistent,format!("List marker '{}' does not match expected style '{}'",actual,consistent)),
        };
        if actual!=expected{
            out.push(warn(ctx,eff,info,it.line_idx+1,it.marker_char_start+1,it.line_idx+1,it.marker_char_start+2,msg,marker_fix(ctx,it,&expected.to_string())));
        }
    }
}

fn md005(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let items=get_list_items(ctx);
    // Group by (block adjusted, level). Adjust block when top-level orderedness changes.
    let mut expected:HashMap<(usize,usize),usize>=HashMap::new();
    let mut adj_block=0usize; let mut last_root_ordered:Option<bool>=None; let mut current_block=usize::MAX;
    for it in &items {
        if it.block_id!=current_block{ current_block=it.block_id; adj_block+=1; last_root_ordered=None; }
        if it.level==0 {
            if let Some(prev_ord)=last_root_ordered{ if prev_ord!=it.ordered{ adj_block+=1; } }
            last_root_ordered=Some(it.ordered);
        }
        let key=(adj_block,it.level);
        if let Some(exp)=expected.get(&key){
            if it.indent!=*exp{
                let start=ctx.char_to_byte(it.line_idx,it.bq_chars); let end=ctx.char_to_byte(it.line_idx,it.marker_char_start);
                out.push(warn(ctx,eff,info,it.line_idx+1,1,it.line_idx+1,it.marker_char_start+1,format!("Expected indentation of {} spaces, found {}",exp,it.indent),fix_range(ctx,start,end,&" ".repeat(*exp))));
            }
        } else { expected.insert(key,it.indent); }
    }
}

pub fn md007_effective_style(eff:&EffectiveConfig)->String{
    let raw=eff.config.rules.get("MD007");
    let has_style=raw.map(|m| m.contains_key("style")).unwrap_or(false);
    let has_indent=raw.map(|m| m.contains_key("indent")).unwrap_or(false);
    if eff.invalid_rules.contains("MD007") { return "text-aligned".to_string(); }
    if has_style { if let Some(toml::Value::String(s))=raw.and_then(|m| m.get("style")){ return s.clone(); } }
    if has_indent { return "fixed".to_string(); }
    "text-aligned".to_string()
}
fn md007(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info);
