    let start_indent=cfg.get_usize("start-indent").unwrap_or(2);
    let style=md007_effective_style(eff);
    let items=get_list_items(ctx);
    // expected indent map by item index in items vec computed recursively (parents indices refer to items positions as stored in parent field? Our ListItem.parent is index into items vec (my_idx at push). Good.
    let mut expected_map:HashMap<usize,usize>=HashMap::new();
    for (idx,it) in items.iter().enumerate(){
        let exp=if it.level==0 { if start_indented{start_indent}else{0} } else {
            let parent=it.parent.and_then(|pi| items.get(pi));
            if style=="fixed" && !(parent.map(|p| p.ordered).unwrap_or(false)) {
                (if start_indented{start_indent}else{0}) + it.level*indent_cfg
            } else {
                // text-aligned (or parent ordered)
                if let Some(p)=parent{ let p_exp=*expected_map.get(&it.parent.unwrap()).unwrap_or(&p.indent); p_exp + p.marker.chars().count() + p.after_spaces.max(1) } else { it.level*indent_cfg }
                // after_spaces in visual terms: if tab, count approx 1? parent after_spaces is chars - use visual: for typical one space fine
            }
        };
        expected_map.insert(idx,exp);
        if it.ordered{continue;}
        if it.indent!=exp{
            let start=ctx.char_to_byte(it.line_idx,it.bq_chars); let end=ctx.char_to_byte(it.line_idx,it.marker_char_start);
            out.push(warn(ctx,eff,info,it.line_idx+1,1,it.line_idx+1,it.marker_char_start+1,format!("Expected {} spaces for indent depth {}, found {}",exp,it.level,it.indent),fix_range(ctx,start,end,&" ".repeat(exp))));
