fn md030(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info);
    let ul_single=cfg.get_usize("ul-single").unwrap_or(1); let ul_multi=cfg.get_usize("ul-multi").unwrap_or(1); let ol_single=cfg.get_usize("ol-single").unwrap_or(1); let ol_multi=cfg.get_usize("ol-multi").unwrap_or(1);
