fn custom_fix_md035(ctx:&LintContext, content:&str, cfg:&Config)->Option<String>{
    let eff=crate::rules::validate_and_build(cfg);
    let info=crate::info::rule_by_code("MD035")?;
    let rc=crate::rules::RuleCfg{eff:&eff,code:"MD035"};
    let style_cfg=rc.get_str("style").unwrap_or("consistent".into());
    let setext_ends:std::collections::HashSet<usize>=crate::rule_funcs::get_headings(ctx).iter().filter(|h| h.style==crate::rule_funcs::HeadingStyle::Setext).map(|h| h.end_idx).collect();
    let mut hrs:Vec<(usize,String)>=Vec::new();
    for idx in 0..ctx.line_count(){ let li=&ctx.lines[idx]; if li.in_code()||li.is_fence||li.in_frontmatter||li.is_frontmatter_delim{continue;} if setext_ends.contains(&idx){continue;} let line=ctx.line(idx); if crate::rule_funcs::is_thematic_break(line){ hrs.push((idx,line.trim().to_string())); } }
    if hrs.is_empty(){return None;}
    let expected=if style_cfg=="consistent"||style_cfg.is_empty(){hrs[0].1.clone()}else{style_cfg};
    let mut edits:Vec<(usize,usize,String)>=Vec::new();
    for (idx,actual) in hrs{ if actual!=expected{ edits.push((ctx.line_byte_start(idx),ctx.line_byte_end(idx),expected.clone())); } }
    if edits.is_empty(){return None;}
    edits.sort_by(|a,b| b.0.cmp(&a.0)); let mut out=content.to_string(); for (s,e,r) in edits{out.replace_range(s..e,&r);} Some(out)
}
fn custom_fix_md046(ctx:&LintContext, content:&str, cfg:&Config)->Option<String>{
    let eff=crate::rules::validate_and_build(cfg);
    let rc=crate::rules::RuleCfg{eff:&eff,code:"MD046"};
    let style_cfg=rc.get_str("style").unwrap_or("consistent".into());
    #[derive(PartialEq,Clone,Copy)] enum Kind{Fenced,Indented}
    // Determine expected
    let has_fenced=!ctx.code_blocks.is_empty();
    let mut indented_groups:Vec<Vec<usize>>=Vec::new();
    let mut i=0; while i<ctx.line_count(){ if ctx.lines[i].in_indented_code{ let mut lines=vec![]; while i<ctx.line_count()&&ctx.lines[i].in_indented_code{lines.push(i);i+=1;} if !lines.is_empty(){indented_groups.push(lines);} } else {i+=1;} }
    let expected=match style_cfg.as_str(){ "fenced"=>Kind::Fenced,"indented"=>Kind::Indented,_=>{ if has_fenced{Kind::Fenced}else{Kind::Indented} } };
    // consistent majority recomputed like warning: counts of blocks (fenced vs grouped indented including blanks as one group for count?) Use warning logic approx: count fenced blocks vs indented_groups merged across blanks? For transformation we only need expected for mismatches; if expected matches all, return None below by no edits.
    let expected=if style_cfg!="fenced"&&style_cfg!="indented"{
        let fenced_count=ctx.code_blocks.len();
        // indented groups merged across blank lines count as one if separated only by blanks and next is indented
        let mut merged=0usize; let mut prev_end:Option<usize>=None;
        for g in &indented_groups{ if let Some(pe)=prev_end{ let between_blank=(pe+1..g[0]).all(|j| crate::rule_funcs::is_blank(ctx.line(j))); if !between_blank{merged+=1;} } else {merged+=1;} prev_end=Some(*g.last().unwrap()); }
        if merged>fenced_count{Kind::Indented}else{Kind::Fenced}
    } else {expected};
    let mut lines:Vec<String>=content.lines().map(|s| s.to_string()).collect();
    let trailing_newline=content.ends_with('\n');
    // We will rebuild walking original line indices, replacing blocks.
    let mut out_lines:Vec<String>=Vec::new();
    let mut idx=0;
    let mut changed=false;
    while idx<ctx.line_count(){
        if let Some(cb)=ctx.code_blocks.iter().find(|cb| cb.start_line==idx){
            if expected==Kind::Fenced {
                let end=cb.end_line.unwrap_or(ctx.line_count().saturating_sub(1));
                for j in cb.start_line..=end.min(ctx.line_count().saturating_sub(1)){ out_lines.push(ctx.line(j).to_string()); }
                idx=end+1;
            } else {
                changed=true;
                let end=cb.end_line.unwrap_or(ctx.line_count());
                for j in cb.start_line+1..end{ let l=ctx.line(j); if l.is_empty(){out_lines.push(String::new());}else{out_lines.push(format!("    {l}"));} }
                idx=end+1;
            }
            continue;
        }
        if ctx.lines[idx].in_indented_code {
            // collect one chunk of consecutive indented lines (not blanks)
            let mut chunk:Vec<usize>=Vec::new(); while idx<ctx.line_count()&&ctx.lines[idx].in_indented_code{chunk.push(idx);idx+=1;}
            if expected==Kind::Indented { for j in chunk{out_lines.push(ctx.line(j).to_string());} }
            else { changed=true; out_lines.push("```".to_string()); for j in chunk{out_lines.push(crate::rule_funcs3::dedent_indented(ctx.line(j)));} out_lines.push("```".to_string()); }
            continue;
        }
        out_lines.push(ctx.line(idx).to_string()); idx+=1;
    }
    if !changed{return None;}
    let mut out=out_lines.join("\n"); if trailing_newline{out.push('\n');} Some(out)
}
