    let fix_enabled=cfg.get_bool("fix").unwrap_or(false);
    let br_style=cfg.get_str("br-style").unwrap_or("trailing-spaces".into());
    let gfm_tags=["script","iframe","form","object","embed","style","link","meta","base","title","frame","frameset","applet","xmp","noembed","noframes","plaintext","listing"];
    let mut disallowed_expanded:Vec<String>=Vec::new();
