                    let mut token:String=chars[i..j].iter().collect();
                    // trim trailing punctuation and unmatched closing parens/brackets
                    token=trim_url_trailing(&token);
                    let tlen=token.chars().count();
                    matched=Some((tlen,token,false)); break;
                }
