                if chars[i].is_alphanumeric()||chars[i]=='_'||chars[i]=='.'||chars[i]=='%'||chars[i]=='+'||chars[i]=='-' {
                    if i==0||!(chars[i-1].is_alphanumeric()||"._%+-@<".contains(chars[i-1])) {
                        let mut j=i; while j<chars.len()&&(chars[j].is_alphanumeric()||"._%+-@".contains(chars[j])){j+=1;}
                        let token:String=chars[i..j].iter().collect();
                        if is_email(&token){ matched=Some((token.chars().count(),token,true)); }
                    }
                }
            }
            if let Some((tlen,token,is_email))=matched{
                let startb=ctx.char_to_byte(idx,i); let endb=ctx.char_to_byte(idx,i+tlen);
                let msg=if is_email{format!("Email address without angle brackets or link formatting: '{token}'")}else{format!("URL without angle brackets or link formatting: '{token}'")};
                out.push(warn(ctx,eff,info,idx+1,i+1,idx+1,i+tlen+1,msg,fix_range(ctx,startb,endb,&format!("<{token}>"))));
                i+=tlen; continue;
            }
            i+=1;
        }
    }
}
pub fn trim_url_trailing(token:&str)->String{
    let mut t=token.to_string();
    loop {
        if t.is_empty(){break;}
        let last=t.chars().last().unwrap();
        if ".,;:!?".contains(last){ t.pop(); continue; }
        if last==')' && t.matches('(').count()<t.matches(')').count(){ t.pop(); continue; }
        if last==']' && t.matches('[').count()<t.matches(']').count(){ t.pop(); continue; }
        if last=='\''||last=='"'{ t.pop(); continue; }
        break;
    }
    t
}
fn is_email(s:&str)->bool{
    let mut parts=s.split('@'); let a=parts.next().unwrap_or(""); let b=parts.next().unwrap_or("");
    parts.next().is_none()&&!a.is_empty()&&b.contains('.')&&!b.starts_with('.')&&!b.ends_with('.')&&b.chars().all(|c| c.is_alphanumeric()||c=='.'||c=='-')
}
fn is_ref_def_for_md034(line:&str)->bool{ let t=line.trim_start(); t.starts_with('[')&&t.contains("]:") }
pub fn link_destination_ranges(line:&str)->Vec<(usize,usize)>{
    let chars:Vec<char>=line.chars().collect(); let mut ranges=Vec::new(); let mut i=0;
    while i<chars.len(){
        if chars[i]=='<' { let mut j=i+1; while j<chars.len()&&chars[j]!='>'{j+=1;} if j<chars.len(){ranges.push((i,j+1)); i=j+1; continue;} }
        if chars[i]==']' && i+1<chars.len()&&chars[i+1]=='(' { let mut j=i+2; let mut depth=1; while j<chars.len(){ if chars[j]=='(' {depth+=1;} else if chars[j]==')'{depth-=1; if depth==0{break;}} j+=1; } ranges.push((i+1, (j+1).min(chars.len()))); i=j+1; continue; }
        if chars[i]==':' && i>0 && chars[i-1]==']' { // ref def destination to end of first token - cover rest of line to be safe? original line skipped separately
        }
