        let chars:Vec<char>=line.chars().collect(); let mut i=0;
        while i<chars.len(){
            if chars[i]=='`'{
                let mut j=i; while j<chars.len()&&chars[j]=='`'{j+=1;} let run=j-i;
                // find closing run equal
                let mut k=j; let mut found=None;
                while k<chars.len(){ if chars[k]=='`'{let mut k2=k; while k2<chars.len()&&chars[k2]=='`'{k2+=1;} if k2-k==run{found=Some((k,k2));break;} k=k2;}else{k+=1;} }
                if let Some((cs,ce))=found{
                    let inner:String=chars[j..cs].iter().collect();
                    let lead=inner.chars().take_while(|c| *c==' ').count(); let trail=inner.chars().rev().take_while(|c| *c==' ').count();
                    let all_spaces=!inner.is_empty()&&inner.chars().all(|c| c==' ');
