                    if !is_exception && !flavor_skip && (lead>0||trail>0) {
                        let repl=format!("{}{}{}", "`".repeat(run), inner.trim(), "`".repeat(run));
                        let startb=ctx.char_to_byte(idx,i); let endb=ctx.char_to_byte(idx,ce);
                        out.push(warn(ctx,eff,info,idx+1,i+1,idx+1,ce+1,"Spaces inside code span elements".to_string(),fix_range(ctx,startb,endb,&repl)));
                    }
                    i=ce; continue;
                }
                i=j; continue;
            }
            i+=1;
        }
    }
