    fn matches_req(h:&Heading, e:&(Option<usize>,String), match_case:bool)->bool{
        if let Some(l)=e.0{ if h.level!=l{return false;} }
        if match_case{ h.text==e.1 } else { h.text.eq_ignore_ascii_case(&e.1) }
