pub fn generate_alt_text(dest:&str, placeholder:&str)->String{
    let d=dest.trim_matches(|c| c=='<'||c=='>');
    let file=d.rsplit('/').next().unwrap_or(d);
    let stem=file.rsplit_once('.').map(|(s,_)| s).unwrap_or(file);
    if stem.trim().is_empty(){return placeholder.to_string();}
    let words:Vec<String>=stem.split(|c:char| c=='-'||c=='_'||c==' ').filter(|s| !s.is_empty()).map(|w|{
        // Title case: first char upper, rest as-is? q4 -> Q4, 2024 unchanged
        let mut cs=w.chars(); match cs.next(){Some(f)=>f.to_ascii_uppercase().to_string()+cs.as_str(),None=>String::new()}
    }).collect();
    if words.is_empty(){return placeholder.to_string();}
    format!("{} image", words.join(" "))
}
