// Helper: iterate non-code lines, provide comment ranges state? For many rules, HTML comments are skipped as content by their parsers - code_span_ranges doesn't include comments. We'll compute a simple per-line stripped-of-comments view for some rules via inline module later.

fn md033(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info);
    let mut allowed:Vec<String>=cfg.get_vec("allowed-elements");
    if allowed.is_empty() { if let Some(m)=eff.config.rules.get("MD033"){ if let Some(toml::Value::Array(a))=m.get("allowed"){ allowed=a.iter().filter_map(|v| if let toml::Value::String(s)=v{Some(s.clone())}else{None}).collect(); } } }
    let mut disallowed:Vec<String>=cfg.get_vec("disallowed-elements");
    if disallowed.is_empty() { if let Some(m)=eff.config.rules.get("MD033"){ if let Some(toml::Value::Array(a))=m.get("disallowed"){ disallowed=a.iter().filter_map(|v| if let toml::Value::String(s)=v{Some(s.clone())}else{None}).collect(); } } }
    let fix_enabled=cfg.get_bool("fix").unwrap_or(false);
    let br_style=cfg.get_str("br-style").unwrap_or("trailing-spaces".into());
    let gfm_tags=["script","iframe","form","object","embed","style","link","meta","base","title","frame","frameset","applet","xmp","noembed","noframes","plaintext","listing"];
    let mut disallowed_expanded:Vec<String>=Vec::new();
    for d in &disallowed{ if d.eq_ignore_ascii_case("gfm"){ for t in gfm_tags{disallowed_expanded.push(t.into());} } else {disallowed_expanded.push(d.to_ascii_lowercase());} }
    let allowed_lower:HashSet<String>=allowed.iter().map(|s| s.to_ascii_lowercase()).collect();
    let has_allowed=!allowed.is_empty(); let has_disallowed=!disallowed.is_empty();
    for idx in 0..ctx.line_count(){
        let li=&ctx.lines[idx]; if li.in_fenced_code||li.is_fence||li.in_frontmatter{continue;}
        let line=ctx.line(idx); let spans=code_span_ranges(line);
        let chars:Vec<char>=line.chars().collect(); let mut i=0;
        while i<chars.len(){
            if chars[i]=='<' && !in_code_span(&spans,i){
                // skip comments
                if line[ctx.char_to_byte(idx,i)-ctx.line_byte_start(idx)..].starts_with("<!--") { if let Some(end)=line[ctx.char_to_byte(idx,i)-ctx.line_byte_start(idx)..].find("-->"){ i+=line[ctx.char_to_byte(idx,i)-ctx.line_byte_start(idx)..][..end+3].chars().count(); continue; } else { break; } }
                // parse tag
                let mut j=i+1; if j<chars.len()&&chars[j]=='/'{ i+=1; continue; } // closing tags not flagged
                if j>=chars.len()||!chars[j].is_ascii_alphabetic(){ i+=1; continue; }
                let name_start=j; while j<chars.len()&&(chars[j].is_ascii_alphanumeric()||chars[j]=='-'||chars[j]=='_'||chars[j]==':'){j+=1;}
                let name:String=chars[name_start..j].iter().collect(); let lname=name.to_ascii_lowercase();
                // must be followed by space, >, / or end
                if j<chars.len()&&!(chars[j]==' '||chars[j]=='\t'||chars[j]=='>'||chars[j]=='/'){ i+=1; continue; }
                // find closing >
                let mut k=j; let mut in_q:Option<char>=None; while k<chars.len(){ let c=chars[k]; if let Some(q)=in_q{ if c==q{in_q=None;} } else if c=='"'||c=='\''{in_q=Some(c);} else if c=='>'{break;} k+=1; }
                if k>=chars.len(){ i+=1; continue; }
                let tag_text:String=chars[i..=k].iter().collect();
                // Flavor exceptions (basic)
                if ctx.flavor==Flavor::MkDocs && tag_text.contains("markdown") { i=k+1; continue; }
                let mut should_flag=false;
                if has_disallowed && !has_allowed { should_flag=disallowed_expanded.contains(&lname); }
                else if has_allowed { should_flag=!allowed_lower.contains(&lname); }
                else { should_flag=true; }
                if should_flag{
                    // MkDocs allowed elements with markdown attr handled above; MDX: components starting uppercase are JSX - original may skip capitalized tags in MDX flavor
                    if ctx.flavor==Flavor::Mdx && name.chars().next().map(|c| c.is_ascii_uppercase()).unwrap_or(false){ i=k+1; continue; }
                    let fix=if fix_enabled{ md033_fix(ctx,idx,i,k,&lname,&tag_text,&br_style) } else {None};
                    out.push(warn(ctx,eff,info,idx+1,i+1,idx+1,k+2,format!("Inline HTML found: {tag_text}"),fix));
                }
                i=k+1; continue;
            }
            i+=1;
        }
    }
}
fn md033_fix(ctx:&LintContext,idx:usize,start_char:usize,end_char:usize,lname:&str,tag_text:&str,br_style:&str)->Option<FixInfo>{
    // Only simple conversions; complex tags return None (original may handle more in fix() custom - refine later)
    let byte_start=ctx.char_to_byte(idx,start_char); let byte_end=ctx.char_to_byte(idx,end_char+1);
    let repl=match lname{
        "br"=> if br_style=="backslash"{"\\\n".to_string()}else{"  \n".to_string()},
        "strong"|"b"=>"**".to_string(),
        "em"|"i"=>"*".to_string(),
        "code"=>"`".to_string(),
        _=>return None,
    };
    Some(FixInfo{range:FixRange{start:byte_start,end:byte_end},replacement:repl})
}

fn md034(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    // Use regex via manual scanning for schemes and emails
    for idx in 0..ctx.line_count(){
        let li=&ctx.lines[idx]; if li.in_code()||li.is_fence||li.in_frontmatter{continue;}
        let line=ctx.line(idx);
        if is_ref_def_for_md034(line){continue;}
        let spans=code_span_ranges(line);
        // Find link destinations ranges and autolink ranges to skip
        let skip_ranges=link_destination_ranges(line);
        let chars:Vec<char>=line.chars().collect();
        // URL patterns: scan for "http://", "https://", "ftp://", "xmpp:", "www."
        let mut i=0;
        while i<chars.len(){
            if in_code_span(&spans,i)||skip_ranges.iter().any(|(s,e)| i>=*s&&i<*e){ i+=1; continue; }
            let remaining:String=chars[i..].iter().collect();
            let mut matched:Option<(usize,String,bool)>=None; // char len, token, is_email
            for pat in ["https://","http://","ftp://","xmpp:","www."]{
                if remaining.starts_with(pat){
                    // preceding char must not be alnum or < or ( or " or ' etc
                    if i>0 && (chars[i-1]=='<'||chars[i-1]=='('||chars[i-1].is_alphanumeric()){ break; }
                    let mut j=i; while j<chars.len()&&!chars[j].is_whitespace()&&chars[j]!='<'&&chars[j]!='>'{j+=1;}
                    let mut token:String=chars[i..j].iter().collect();
                    // trim trailing punctuation and unmatched closing parens/brackets
                    token=trim_url_trailing(&token);
                    let tlen=token.chars().count();
                    matched=Some((tlen,token,false)); break;
                }
            }
            if matched.is_none() {
                // email: word chars ._%+- @ domain . tld
                if chars[i].is_alphanumeric()||chars[i]=='_'||chars[i]=='.'||chars[i]=='%'||chars[i]=='+'||chars[i]=='-' {
                    if i==0||!(chars[i-1].is_alphanumeric()||"._%+-@<".contains(chars[i-1])) {
                        let mut j=i; while j<chars.len()&&(chars[j].is_alphanumeric()||"._%+-@".contains(chars[j])){j+=1;}
                        let token:String=chars[i..j].iter().collect();
                        if is_email(&token){ matched=Some((token.chars().count(),token,true)); }
                    }
                }
            }
            if let Some((tlen,token,is_email))=matched{
                let startb=ctx.char_to_byte(idx,i); let endb=ctx.char_to_byte(idx,i+tlen);
                let msg=if is_email{format!("Email address without angle brackets or link formatting: '{token}'")}else{format!("URL without angle brackets or link formatting: '{token}'")};
                out.push(warn(ctx,eff,info,idx+1,i+1,idx+1,i+tlen+1,msg,fix_range(ctx,startb,endb,&format!("<{token}>"))));
                i+=tlen; continue;
            }
            i+=1;
        }
    }
}
pub fn trim_url_trailing(token:&str)->String{
    let mut t=token.to_string();
    loop {
        if t.is_empty(){break;}
        let last=t.chars().last().unwrap();
        if ".,;:!?".contains(last){ t.pop(); continue; }
        if last==')' && t.matches('(').count()<t.matches(')').count(){ t.pop(); continue; }
        if last==']' && t.matches('[').count()<t.matches(']').count(){ t.pop(); continue; }
        if last=='\''||last=='"'{ t.pop(); continue; }
        break;
    }
    t
}
fn is_email(s:&str)->bool{
    let mut parts=s.split('@'); let a=parts.next().unwrap_or(""); let b=parts.next().unwrap_or("");
    parts.next().is_none()&&!a.is_empty()&&b.contains('.')&&!b.starts_with('.')&&!b.ends_with('.')&&b.chars().all(|c| c.is_alphanumeric()||c=='.'||c=='-')
}
fn is_ref_def_for_md034(line:&str)->bool{ let t=line.trim_start(); t.starts_with('[')&&t.contains("]:") }
pub fn link_destination_ranges(line:&str)->Vec<(usize,usize)>{
    let chars:Vec<char>=line.chars().collect(); let mut ranges=Vec::new(); let mut i=0;
    while i<chars.len(){
        if chars[i]=='<' { let mut j=i+1; while j<chars.len()&&chars[j]!='>'{j+=1;} if j<chars.len(){ranges.push((i,j+1)); i=j+1; continue;} }
        if chars[i]==']' && i+1<chars.len()&&chars[i+1]=='(' { let mut j=i+2; let mut depth=1; while j<chars.len(){ if chars[j]=='(' {depth+=1;} else if chars[j]==')'{depth-=1; if depth==0{break;}} j+=1; } ranges.push((i+1, (j+1).min(chars.len()))); i=j+1; continue; }
        if chars[i]==':' && i>0 && chars[i-1]==']' { // ref def destination to end of first token - cover rest of line to be safe? original line skipped separately
        }
        i+=1;
    }
    ranges
}

fn md036(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info); let punct=cfg.get_str("punctuation").unwrap_or(".,;:!?".into()); let fix_enabled=cfg.get_bool("fix").unwrap_or(false); let heading_level=cfg.get_usize("heading-level").unwrap_or(2); let heading_style=cfg.get_str("heading-style").unwrap_or("atx".into());
    for idx in 0..ctx.line_count(){
        let li=&ctx.lines[idx]; if li.in_code()||li.is_fence||li.in_frontmatter{continue;}
        let line=ctx.line(idx); let t=line.trim();
        if t.is_empty(){continue;}
        // must be standalone paragraph: previous and next lines blank or boundaries (from docs examples all separated) - original may not require blank after if next is text? It is a paragraph by itself if next line isn't a continuation (nonblank would make it part of para). Require next blank/eof and prev blank/eof or heading? Probe fallback: allow regardless? We'll require prev blank/start and next blank/end to reduce false positives.
        // Parse single emphasis span covering whole trimmed line with *, **, _, __ but not *** / ___
        let parsed=parse_whole_emphasis(t);
        if let Some((marker,text))=parsed{
            if text.trim().is_empty(){continue;}
            if text.trim_end().chars().last().map(|c| punct.contains(c)).unwrap_or(false){continue;}
            // Lines that are list items: t starts with emphasis so not list.
            let fix=if fix_enabled{
                let repl=match heading_style.as_str(){ "atx_closed"=>format!("{} {} {}", "#".repeat(heading_level), text.trim(), "#".repeat(heading_level)), "setext"=> if heading_level==1{format!("{}\n{}",text.trim(),"=".repeat(text.trim().chars().count()))}else if heading_level==2{format!("{}\n{}",text.trim(),"-".repeat(text.trim().chars().count()))}else{format!("{} {}", "#".repeat(heading_level), text.trim())}, _=>format!("{} {}", "#".repeat(heading_level), text.trim()) };
                whole_line_fix(ctx,idx,repl)
            } else {None};
            out.push(warn(ctx,eff,info,idx+1,1,idx+1,line_end_col(ctx,idx),format!("Emphasis used instead of a heading: '{}'",text.trim()),fix));
            let _=marker;
        }
    }
}
pub fn parse_whole_emphasis(t:&str)->Option<(String,String)>{
    for marker in ["**","__","*","_"]{
        if t.starts_with(marker)&&t.ends_with(marker)&&t.len()>2*marker.len(){
            let inner=&t[marker.len()..t.len()-marker.len()];
            if inner.starts_with(|c:char| c=='*'||c=='_')||inner.ends_with(|c:char| c=='*'||c=='_'){continue;}
            // Ensure inner doesn't contain the marker (for * and ** distinction)
            if marker=="*"&&inner.contains('*'){continue;}
            if marker=="_"&&inner.contains('_'){continue;}
            return Some((marker.to_string(),inner.to_string()));
        }
    }
    None
}

fn md037(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    for idx in 0..ctx.line_count(){
