pub struct LinkSpan{ pub start_char:usize, pub end_char:usize,pub text_start:usize,pub text_end:usize,pub text:String,pub dest:Option<String>,pub is_image:bool,pub whole:String, pub dest_start:Option<usize>,pub dest_end:Option<usize>,pub ref_label:Option<String> }
pub fn find_links(line:&str)->Vec<LinkSpan>{
