pub fn md040(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info);
    let style=cfg.get_str("style").unwrap_or("disabled".into());
    let allowed=cfg.get_vec("allowed-languages");
    let disallowed=cfg.get_vec("disallowed-languages");
    let unknown_action=cfg.get_str("unknown-language-action").unwrap_or("ignore".into());
    let preferred=cfg.raw_table("preferred-aliases").unwrap_or_default();
    // Group for consistent
    let mut by_canon: HashMap<String, Vec<(String,usize)>>=HashMap::new(); // label lower counts order preserved via vec
    let mut label_order: HashMap<String, Vec<String>>=HashMap::new();
    if style=="consistent" {
        for cb in &ctx.code_blocks{
            if cb.lang.is_empty(){continue;}
            if let Some(canon)=canonical_language(&cb.lang){ let e=label_order.entry(canon.clone()).or_default(); if !e.iter().any(|x| x.eq_ignore_ascii_case(&cb.lang)){e.push(cb.lang.clone());} by_canon.entry(canon).or_default().push((cb.lang.to_ascii_lowercase(),1)); }
        }
    }
    let preferred_for=|canon:&str|->Option<String>{
        // preferred-aliases keys are canonical names (case-insensitive)
        for (k,v) in &preferred{ if k.eq_ignore_ascii_case(canon){return Some(v.clone());} }
        if let Some(labels)=label_order.get(canon){
            // count occurrences per lowercase label
            let mut counts:Vec<(String,usize)>=Vec::new();
            for cb in &ctx.code_blocks{ if canonical_language(&cb.lang).as_deref()==Some(canon){ let l=cb.lang.to_ascii_lowercase(); if let Some(e)=counts.iter_mut().find(|e| e.0==l){e.1+=1;}else{counts.push((l,1));} } }
            counts.sort_by(|a,b| b.1.cmp(&a.1)); // stable sort in Rust Vec sort_by is stable? sort_by is stable yes first encountered wins tie
            return counts.first().map(|e| e.0.clone());
        }
        None
    };
    for cb in &ctx.code_blocks{
        let line_idx=cb.start_line;
        let raw_line=ctx.line(line_idx);
        let info_str_full = {
            // after fence run in (possibly blockquote stripped coordinate?) use parse_fence_line on original or stripped - our CodeBlock.lang only first token. For missing detection we need full info string emptiness; cb.lang empty but mkdocs title attr could be present.
            crate::lint::parse_fence_line(crate::lint::strip_blockquote_prefix(raw_line)).map(|x| x.3).unwrap_or_default()
        };
        if info_str_full.trim().is_empty(){
            // MkDocs: fence with title attribute but no lang is in info_str, not empty, handled below as label token could be title=...
            let fence_start_char=raw_line.find(cb.fence_char).unwrap_or(0);
            let fence_start_byte=ctx.line_byte_start(line_idx)+fence_start_char;
            let fence_str=cb.fence_char.to_string().repeat(cb.fence_len);
            out.push(warn(ctx,eff,info,line_idx+1,1,line_idx+1,line_end_col(ctx,line_idx),format!("Code block (```) missing language"),Some(FixInfo{range:FixRange{start:fence_start_byte,end:fence_start_byte+cb.fence_len},replacement:format!("{fence_str}text")})));
            continue;
        }
        let label=cb.lang.clone();
        if label.is_empty(){continue;}
        // MkDocs: info token starting with title= counts as having no language but allowed? original docs say allow title= without language in mkdocs. If first token contains '=', treat as attribute-only and skip missing (and don't process as lang)
        if ctx.flavor==Flavor::MkDocs && label.contains('='){continue;}
        let canon=canonical_language(&label);
        // Allowed/disallowed take precedence as in original: if allowed non-empty, check allowed; else if disallowed check.
        let mut flagged=false;
        if !allowed.is_empty(){
            let is_allowed=match &canon{ Some(c)=>allowed.iter().any(|a| { let ac=canonical_language(a).unwrap_or(a.clone()); ac.eq_ignore_ascii_case(c) }), None=>false };
            if !is_allowed{
                let msg=if let Some(c)=&canon{format!("Language '{label}' ({c}) is not in the allowed list: {}",allowed.join(", "))}else{format!("Language '{label}' is not in the allowed list: {}",allowed.join(", "))};
                out.push(warn(ctx,eff,info,line_idx+1,1,line_idx+1,line_end_col(ctx,line_idx),msg,None)); flagged=true;
            }
        } else if !disallowed.is_empty(){
            if let Some(c)=&canon{ let is_dis=disallowed.iter().any(|a| { let ac=canonical_language(a).unwrap_or(a.clone()); ac.eq_ignore_ascii_case(c) }); if is_dis{ out.push(warn(ctx,eff,info,line_idx+1,1,line_idx+1,line_end_col(ctx,line_idx),format!("Language '{label}' ({c}) is disallowed"),None)); flagged=true; } }
        }
        if flagged{continue;}
        if canon.is_none(){
            match unknown_action.as_str(){
                "warn"=>{ out.push(warn(ctx,eff,info,line_idx+1,1,line_idx+1,line_end_col(ctx,line_idx),format!("Unknown language '{label}' (not in GitHub Linguist). Syntax highlighting may not work."),None)); },
                "error"=>{ let mut w=warn(ctx,eff,info,line_idx+1,1,line_idx+1,line_end_col(ctx,line_idx),format!("Unknown language '{label}' (not in GitHub Linguist)"),None); w.severity=Severity::Error; out.push(w); },
                _=>{}
            }
            continue;
        }
        if style=="consistent"{
            let canon=canon.unwrap();
            if let Some(pref)=preferred_for(&canon){
                if label!=pref{
                    // fix range: label token within line after fence
                    if let Some((indent,_fc,_cnt,_info))={ let stripped=crate::lint::strip_blockquote_prefix(raw_line); crate::lint::parse_fence_line(stripped).map(|(a,b,c,d)| (a,b,c,d)) } {
                        let _=indent;
                    }
                    // find label in raw line after fence run
                    let fence_pos=raw_line.find(&cb.fence_char.to_string()).unwrap_or(0);
                    let after_fence=fence_pos+cb.fence_len;
                    let label_byte_start=ctx.line_byte_start(line_idx)+after_fence;
                    // label may be immediately after fence (no spaces typical)
                    let start=label_byte_start; let end=start+label.len();
                    out.push(warn(ctx,eff,info,line_idx+1,1,line_idx+1,line_end_col(ctx,line_idx),format!("Inconsistent language label '{label}' for {canon} (use '{pref}')"),Some(FixInfo{range:FixRange{start,end},replacement:pref})));
                }
            }
        }
    }
}
