#[derive(Debug,Clone)]
pub struct TableInfo{ pub header_idx:usize, pub sep_idx:usize, pub row_indices:Vec<usize>, pub header_cells:Vec<String> }
pub fn split_table_cells(line:&str)->Vec<String>{
    let mut cells=Vec::new(); let mut cur=String::new(); let mut chars=line.chars().peekable(); let mut in_code=false; let mut code_run=0usize;
    // Trim leading/trailing pipe handled by caller? This returns cells for a row by splitting on unescaped pipes outside code spans, dropping empty first/last from leading/trailing pipe.
    let trimmed=line.trim();
    let mut cs:Vec<char>=trimmed.chars().collect();
    // tokenize keeping escapes
    let mut i=0; let mut code_ticks=0usize;
    while i<cs.len(){
        let c=cs[i];
        if c=='\\' && i+1<cs.len() && cs[i+1]=='|' { cur.push('|'); i+=2; continue; }
        if c=='`' { let mut j=i; while j<cs.len()&&cs[j]=='`'{j+=1;} let run=j-i; if code_ticks==0{code_ticks=run;}else if run==code_ticks{code_ticks=0;} for _ in 0..run{cur.push('`');} i=j; continue; }
        if c=='|' && code_ticks==0 { cells.push(cur.trim().to_string()); cur=String::new(); i+=1; continue; }
        cur.push(c); i+=1;
    }
    cells.push(cur.trim().to_string());
    if trimmed.starts_with('|'){ if !cells.is_empty(){cells.remove(0);} }
    if trimmed.ends_with('|') && !trimmed.ends_with("\\|"){ if !cells.is_empty(){cells.pop();} }
    cells
}
pub fn get_tables(ctx:&LintContext)->Vec<TableInfo>{
    let mut out=Vec::new(); let mut i=0;
    while i+1<ctx.line_count(){
        if ctx.lines[i].in_code()||ctx.lines[i].is_fence{ i+=1; continue; }
        let line=ctx.line(i);
        if line.contains('|') && !is_blank(line) && crate::rule_funcs2::is_table_separator_pub(ctx.line(i+1)) {
            let header_cells=split_table_cells(line);
            let mut rows=Vec::new(); let mut j=i+2;
            while j<ctx.line_count() && !is_blank(ctx.line(j)) && ctx.line(j).contains('|') && !ctx.lines[j].in_code() { rows.push(j); j+=1; }
            out.push(TableInfo{header_idx:i,sep_idx:i+1,row_indices:rows,header_cells});
            i=j; continue;
        }
        i+=1;
    }
    out
}
