use crate::config::*;
use crate::info::*;
use crate::lint::*;
use crate::rule_funcs::*;
use crate::rule_funcs4::{find_links,LinkSpan};
use crate::rules::*;
use std::collections::{HashMap, HashSet};

pub fn run_rest5(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    match info.code {
        "MD051"=>md051(ctx,eff,info,out),
        "MD052"=>md052(ctx,eff,info,out),
        "MD053"=>md053(ctx,eff,info,out),
        "MD054"=>md054(ctx,eff,info,out),
        "MD055"=>md055(ctx,eff,info,out),
        "MD056"=>md056(ctx,eff,info,out),
        "MD057"=>md057(ctx,eff,info,out),
        _=>{ crate::rule_funcs6::run_rest6(ctx,eff,info,out); }
    }
}

pub fn github_slug(text:&str)->String{
    // Strip basic markdown formatting from heading text first (caller passes h.text already mostly plain but may contain links/code/html)
    let mut plain=String::new();
    let chars:Vec<char>=text.chars().collect(); let mut i=0;
    while i<chars.len(){
        if chars[i]=='<'{ while i<chars.len()&&chars[i]!='>'{i+=1;} i+=1; continue; }
        if chars[i]=='`'||chars[i]=='*'||chars[i]=='_'||chars[i]=='~' { i+=1; continue; }
        if chars[i]=='['{ i+=1; continue; }
        if chars[i]==']'{ // skip ](...) destination
            if i+1<chars.len()&&chars[i+1]=='(' { let mut depth=1; i+=2; while i<chars.len(){ if chars[i]=='(' {depth+=1;} else if chars[i]==')'{depth-=1; if depth==0{break;}} i+=1; } i+=1; continue; } else { i+=1; continue; }
        }
        plain.push(chars[i]); i+=1;
    }
    let mut slug=String::new();
    for c in plain.to_lowercase().chars(){
        if c.is_alphanumeric()||c=='-'||c=='_'{ slug.push(c); }
        else if c.is_whitespace(){ slug.push('-'); }
        else {}
    }
    slug
}
pub fn heading_anchors(ctx:&LintContext)->Vec<String>{
    let mut counts:HashMap<String,usize>=HashMap::new(); let mut out=Vec::new();
    for h in get_headings(ctx){
        // custom anchor {#id} in heading raw
        let mut anchors=Vec::new();
        let raw=ctx.line(h.line_idx);
        if let Some(pos)=raw.rfind("{#"){
            if let Some(end)=raw[pos..].find('}'){ anchors.push(raw[pos+2..pos+end].trim().to_string()); }
        }
        let base=github_slug(&h.text);
        let count=counts.entry(base.clone()).or_insert(0);
        let slug=if *count==0{base.clone()}else{format!("{}-{}",base,count)};
        *count+=1; anchors.push(slug);
        out.extend(anchors);
    }
    // HTML anchors <a id="x"> / name=
    for idx in 0..ctx.line_count(){
        let line=ctx.line(idx);
        for cap in ["id=\"","id='","name=\"","name='"]{
            let mut start=0; while let Some(pos)=line[start..].find(cap){ let p=start+pos+cap.len(); let quote=cap.chars().last().unwrap(); if let Some(end)=line[p..].find(quote){ out.push(line[p..p+end].to_string()); start=p+end; } else {break;} }
        }
    }
    out
}
fn percent_decode(s:&str)->String{
    let mut out:Vec<u8>=Vec::new(); let bytes=s.as_bytes(); let mut i=0;
    while i<bytes.len(){ if bytes[i]==b'%'&&i+2<bytes.len(){ if let Ok(v)=u8::from_str_radix(std::str::from_utf8(&bytes[i+1..i+3]).unwrap_or(""),16){out.push(v); i+=3; continue;} } out.push(bytes[i]); i+=1; }
    String::from_utf8_lossy(&out).to_string()
}
pub fn dest_first_token(dest:&str)->String{
    let t=dest.trim();
    if t.starts_with('<'){ if let Some(end)=t.find('>'){ return t[1..end].to_string(); } }
    t.split_whitespace().next().unwrap_or("").to_string()
}
fn md051(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info); let _anchor_style=cfg.get_str("anchor-style").unwrap_or("github".into());
    let anchors:HashSet<String>=heading_anchors(ctx).into_iter().collect();
    let defs=reference_definitions(ctx);
    for idx in 0..ctx.line_count(){
        let li=&ctx.lines[idx]; if li.in_code()||li.is_fence||li.in_frontmatter{continue;}
        if is_ref_def_line_full(ctx.line(idx)){continue;}
        let line=ctx.line(idx);
        for link in find_links(line){
            let dest_opt=resolve_link_dest(&link,&defs);
            let Some(dest_raw)=dest_opt else{continue;};
            let dest=dest_first_token(&dest_raw);
            if let Some(frag)=dest.strip_prefix('#'){
                if frag.is_empty(){continue;}
                let decoded=percent_decode(frag);
                if !anchors.contains(&decoded){
                    out.push(warn(ctx,eff,info,idx+1,link.start_char+1,idx+1,link.end_char+1,format!("Link anchor '#{frag}' does not exist in document headings"),None));
                }
            }
        }
    }
}
pub fn is_ref_def_line_full(line:&str)->bool{
    let t=line.trim_start(); t.starts_with('[')&&t.contains("]:")&&!t.starts_with("[^")
}
pub fn reference_definitions(ctx:&LintContext)->HashMap<String,(usize,String,usize)>{
    // normalized label -> (line_idx, dest raw, dest_start_char)
    let mut map=HashMap::new();
    for idx in 0..ctx.line_count(){
        if ctx.lines[idx].in_code()||ctx.lines[idx].is_fence||ctx.lines[idx].in_frontmatter{continue;}
        let line=ctx.line(idx); let t=line.trim_start(); let indent_chars=line.chars().take_while(|c| c.is_whitespace()).count();
        if indent_chars>3{continue;}
        if !t.starts_with('[')||t.starts_with("[^"){continue;}
        if let Some(close)=t.find("]:") {
            let label=&t[1..close];
            let after=&t[close+2..];
            let dest_raw=after.trim_start();
            let dest_start_char=indent_chars + (t.len()-dest_raw.len()) + 0; // approx char count: use byte positions converted later as chars (labels ascii mostly)
            // dest start char in original line: chars before dest_raw in original line
            let pre_len=line.len()-dest_raw.len(); let dest_start_char2=line[..pre_len].chars().count();
            map.entry(normalize_ref_label(label)).or_insert((idx,dest_raw.to_string(),dest_start_char2));
        }
    }
    map
}
pub fn normalize_ref_label(s:&str)->String{ s.split_whitespace().collect::<Vec<_>>().join(" ").to_ascii_lowercase() }
pub fn resolve_link_dest(link:&LinkSpan, defs:&HashMap<String,(usize,String,usize)>)->Option<String>{
    if let Some(d)=&link.dest{return Some(d.clone());}
    if let Some(r)=&link.ref_label{
        let label=if r.is_empty(){link.text.clone()}else{r.clone()};
        if let Some((_,dest,_))=defs.get(&normalize_ref_label(&label)){return Some(dest.clone());}
    }
    None
}
fn md052(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let defs=reference_definitions(ctx);
    for idx in 0..ctx.line_count(){
        let li=&ctx.lines[idx]; if li.in_code()||li.is_fence||li.in_frontmatter{continue;}
        if is_ref_def_line_full(ctx.line(idx)){continue;}
        let line=ctx.line(idx);
        for link in find_links(line){
            if let Some(r)=&link.ref_label{
                let label=if r.is_empty(){link.text.clone()}else{r.clone()};
                if !defs.contains_key(&normalize_ref_label(&label)){
                    // MkDocs autorefs: in mkdocs flavor, [Class][] where label has dot or is capitalized identifier may be allowed - docs: autoref shorthand
                    if ctx.flavor==Flavor::MkDocs { continue; }
                    out.push(warn(ctx,eff,info,idx+1,link.start_char+1,idx+1,link.end_char+1,format!("Reference '{}' not found",label),None));
                }
            }
        }
    }
}
fn md053(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info); let ignored:HashSet<String>=cfg.get_vec("ignored-definitions").iter().map(|s| normalize_ref_label(s.trim_matches(|c| c=='['||c==']'))).collect();
    let defs=reference_definitions(ctx);
    let mut used:HashSet<String>=HashSet::new();
    for idx in 0..ctx.line_count(){
        if ctx.lines[idx].in_code()||ctx.lines[idx].is_fence{continue;}
        if is_ref_def_line_full(ctx.line(idx)){continue;}
        let line=ctx.line(idx);
        for link in find_links(line){
            if let Some(r)=&link.ref_label{ let label=if r.is_empty(){link.text.clone()}else{r.clone()}; used.insert(normalize_ref_label(&label)); }
            else if link.dest.is_none() {
                // shortcut [label] counts as usage if it matches a definition
                let label=normalize_ref_label(&link.text); if defs.contains_key(&label){used.insert(label);}
            }
        }
    }
    // Preserve definition order by line
    let mut def_list:Vec<(usize,String)>=defs.iter().map(|(k,(line,_,_))| (*line,k.clone())).collect(); def_list.sort();
    // Need original label as written for message: parse from line again
    for (line_idx,norm_label) in def_list{
        if used.contains(&norm_label)||ignored.contains(&norm_label){continue;}
        let line=ctx.line(line_idx); let label=line.trim_start().trim_start_matches('[').split(']').next().unwrap_or(&norm_label);
        out.push(warn(ctx,eff,info,line_idx+1,1,line_idx+1,line_end_col(ctx,line_idx),format!("Unused link/image reference: [{label}]"),None));
    }
}
fn md054(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info);
    let allowed=|key:&str| cfg.get_bool(key).unwrap_or(true);
    let defs=reference_definitions(ctx);
    for idx in 0..ctx.line_count(){
        let li=&ctx.lines[idx]; if li.in_code()||li.is_fence||li.in_frontmatter{continue;}
        if is_ref_def_line_full(ctx.line(idx)){continue;}
        let line=ctx.line(idx); let spans=code_span_ranges(line);
        // Autolinks <http...>
        {
            let chars:Vec<char>=line.chars().collect(); let mut i=0;
            while i<chars.len(){
                if chars[i]=='<'&&!in_code_span(&spans,i){
                    let rest:String=chars[i..].iter().collect();
                    if rest.starts_with("<http://")||rest.starts_with("<https://")||rest.starts_with("<ftp://")||rest.starts_with("<mailto:") {
                        if let Some(end)=rest.find('>'){
                            if !allowed("autolink"){ out.push(warn(ctx,eff,info,idx+1,i+1,idx+1,i+end+2,"Link/image style 'autolink' is not allowed".to_string(),None)); }
                            i+=end+1; continue;
                        }
                    }
                }
                i+=1;
            }
        }
        for link in find_links(line){
            let (style_name,key)=if let Some(dest)=&link.dest{
                let dest_tok=dest_first_token(dest);
                if link.text==dest_tok { ("url_inline","url-inline") } else { ("inline","inline") }
            } else if let Some(r)=&link.ref_label{
                if r.is_empty(){("collapsed","collapsed")}else{("full","full")}
            } else {
                // shortcut only if resolves to a definition
                if defs.contains_key(&normalize_ref_label(&link.text)){ ("shortcut","shortcut") } else { continue; }
            };
            if !allowed(key){
                let col=if link.is_image{link.start_char+2}else{link.start_char+1};
                out.push(warn(ctx,eff,info,idx+1,col,idx+1,link.end_char+1,format!("Link/image style '{style_name}' is not allowed"),None));
            }
        }
    }
}
fn expected_pipe_style_name(style:&str)->&'static str{ match style{"leading-and-trailing"=>"leading and trailing","no-leading-or-trailing"=>"no leading or trailing","leading-only"=>"leading only","trailing-only"=>"trailing only",_=>"leading and trailing"} }
fn row_pipe_category(line:&str)->&'static str{
    let t=line.trim(); let lead=t.starts_with('|'); let trail=t.ends_with('|')&&!t.ends_with("\\|");
