pub fn reference_definitions(ctx:&LintContext)->HashMap<String,(usize,String,usize)>{
    // normalized label -> (line_idx, dest raw, dest_start_char)
    let mut map=HashMap::new();
    for idx in 0..ctx.line_count(){
        if ctx.lines[idx].in_code()||ctx.lines[idx].is_fence||ctx.lines[idx].in_frontmatter{continue;}
        let line=ctx.line(idx); let t=line.trim_start(); let indent_chars=line.chars().take_while(|c| c.is_whitespace()).count();
        if indent_chars>3{continue;}
        if !t.starts_with('[')||t.starts_with("[^"){continue;}
        if let Some(close)=t.find("]:") {
            let label=&t[1..close];
            let after=&t[close+2..];
            let dest_raw=after.trim_start();
            let dest_start_char=indent_chars + (t.len()-dest_raw.len()) + 0; // approx char count: use byte positions converted later as chars (labels ascii mostly)
            // dest start char in original line: chars before dest_raw in original line
            let pre_len=line.len()-dest_raw.len(); let dest_start_char2=line[..pre_len].chars().count();
            map.entry(normalize_ref_label(label)).or_insert((idx,dest_raw.to_string(),dest_start_char2));
        }
    }
