pub fn github_slug(text:&str)->String{
    // Strip basic markdown formatting from heading text first (caller passes h.text already mostly plain but may contain links/code/html)
    let mut plain=String::new();
    let chars:Vec<char>=text.chars().collect(); let mut i=0;
    while i<chars.len(){
        if chars[i]=='<'{ while i<chars.len()&&chars[i]!='>'{i+=1;} i+=1; continue; }
        if chars[i]=='`'||chars[i]=='*'||chars[i]=='_'||chars[i]=='~' { i+=1; continue; }
        if chars[i]=='['{ i+=1; continue; }
        if chars[i]==']'{ // skip ](...) destination
            if i+1<chars.len()&&chars[i+1]=='(' { let mut depth=1; i+=2; while i<chars.len(){ if chars[i]=='(' {depth+=1;} else if chars[i]==')'{depth-=1; if depth==0{break;}} i+=1; } i+=1; continue; } else { i+=1; continue; }
        }
        plain.push(chars[i]); i+=1;
    }
    let mut slug=String::new();
    for c in plain.to_lowercase().chars(){
        if c.is_alphanumeric()||c=='-'||c=='_'{ slug.push(c); }
        else if c.is_whitespace(){ slug.push('-'); }
        else {}
    }
    slug
}
pub fn heading_anchors(ctx:&LintContext)->Vec<String>{
