    let mut used_defs:HashSet<String>=HashSet::new();
    for idx in 0..ctx.line_count(){
        if ctx.lines[idx].in_code()||is_ref_def_line_full(ctx.line(idx)){continue;}
        for link in find_links(ctx.line(idx)){
            if let Some(r)=&link.ref_label{ let label=if r.is_empty(){link.text.clone()}else{r.clone()}; used_defs.insert(normalize_ref_label(&label)); }
        }
    }
    for (label,(line_idx,dest_raw,dest_start_char)) in &defs{
        if !used_defs.contains(label){continue;}
        let dest=dest_first_token(dest_raw);
