fn check_relative_dest(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>,idx:usize,dest_start_char:usize,dest:&str,base_dir:&std::path::Path){
    if dest.is_empty(){return;}
