    if is_external_url(dest){return;}
    let file_part=dest.split('#').next().unwrap_or(dest); let file_part=file_part.split('?').next().unwrap_or(file_part);
    if file_part.is_empty(){return;}
    let decoded=percent_decode(file_part);
    let target=base_dir.join(&decoded);
