    }
}
pub fn is_external_url(dest:&str)->bool{
    let lower=dest.to_ascii_lowercase();
    lower.contains("://")||lower.starts_with("mailto:")||lower.starts_with("tel:")||lower.starts_with("data:")||lower.starts_with("javascript:")||lower.starts_with("ftp:")||lower.starts_with("file:")
}
