    match info.code {
        "MD060"=>md060(ctx,eff,info,out),
        "MD061"=>md061(ctx,eff,info,out),
        "MD063"=>md063(ctx,eff,info,out),
        "MD066"=>md066(ctx,eff,info,out),
        "MD067"=>md067(ctx,eff,info,out),
        "MD068"=>md068(ctx,eff,info,out),
        "MD070"=>md070(ctx,eff,info,out),
        "MD071"=>md071(ctx,eff,info,out),
        "MD072"=>md072(ctx,eff,info,out),
        "MD073"=>md073(ctx,eff,info,out),
        _=>{}
    }
}

fn md060(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info);
    if !cfg.get_bool("enabled").unwrap_or(false){return;}
    crate::table_format::md060(ctx,eff,info,out);
}
fn md061(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info); let terms=cfg.get_vec("terms"); if terms.is_empty(){return;}
    let case_sensitive=cfg.get_bool("case-sensitive").unwrap_or(true);
    for idx in 0..ctx.line_count(){
        let li=&ctx.lines[idx]; if li.in_code()||li.is_fence||li.in_frontmatter||li.is_frontmatter_delim{continue;}
        let line=ctx.line(idx);
        if line.trim_start().starts_with("<!--"){continue;}
        let spans=code_span_ranges(line);
        let chars:Vec<char>=line.chars().collect();
        for term in &terms{
            if term.is_empty(){continue;}
            let hay:Vec<char>=if case_sensitive{chars.clone()}else{line.to_ascii_lowercase().chars().collect()};
            let needle:Vec<char>=(if case_sensitive{term.clone()}else{term.to_ascii_lowercase()}).chars().collect();
            if needle.is_empty(){continue;}
            let mut start=0;
            while start+needle.len()<=hay.len(){
                if hay[start..start+needle.len()]==needle[..]{
                    let before_ok=start==0||!(chars[start-1].is_alphanumeric()||chars[start-1]=='_');
                    let after_ok=start+needle.len()>=chars.len()||!(chars[start+needle.len()].is_alphanumeric()||chars[start+needle.len()]=='_');
                    if before_ok&&after_ok&&!in_code_span(&spans,start){
                        out.push(warn(ctx,eff,info,idx+1,start+1,idx+1,start+needle.len()+1,format!("Found forbidden term '{term}'"),None));
                    }
                    start+=needle.len();
                } else { start+=1; }
            }
        }
    }
}
fn md063(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info); if !cfg.get_bool("enabled").unwrap_or(false){return;}
    let style=cfg.get_str("style").unwrap_or("title_case".into());
    let lowercase_words:HashSet<String>=cfg.get_vec("lowercase-words").iter().map(|s| s.to_ascii_lowercase()).collect();
    let ignore_words=cfg.get_vec("ignore-words");
    let preserve=cfg.get_bool("preserve-cased-words").unwrap_or(true);
    let min_level=cfg.get_usize("min-level").unwrap_or(1); let max_level=cfg.get_usize("max-level").unwrap_or(6);
    for h in get_headings(ctx){
        if h.level<min_level||h.level>max_level{continue;}
        let transformed=transform_heading_case(&h.text,&style,&lowercase_words,&ignore_words,preserve);
        // transformed is a rendered heading text segment preserving links/code/custom id - our transform operates on h.text which strips closing hashes but preserves markdown inside
        if transformed!=h.text{
            let line=ctx.line(h.line_idx);
            let replacement=match h.style{
                HeadingStyle::Setext=>transformed.clone(),
                HeadingStyle::Atx => format!("{}{} {}", " ".repeat(h.indent), "#".repeat(h.level), transformed),
                HeadingStyle::AtxClosed => format!("{}{} {} {}", " ".repeat(h.indent), "#".repeat(h.level), transformed, "#".repeat(h.level)),
            };
            let style_name=match style.as_str(){"sentence_case"=>"sentence case","all_caps"=>"ALL CAPS",_=>"title case"};
            let col=heading_text_start_col(ctx,&h);
            out.push(warn(ctx,eff,info,h.line_idx+1,col,h.line_idx+1,line_end_col(ctx,h.line_idx),format!("Heading should use {style_name}: '{}' -> '{}'",h.text,transformed),whole_line_fix(ctx,h.line_idx,replacement)));
            let _=line;
        }
    }
}
pub fn heading_text_start_col(ctx:&LintContext,h:&Heading)->usize{
    if h.style==HeadingStyle::Setext{ return h.indent+1; }
    let line=ctx.line(h.line_idx); if let Some((indent,level,after))=parse_atx(line){ let spaces=line[after..].chars().take_while(|c| *c==' '||*c=='\t').count(); return indent+level+spaces+1; } 1
}
fn transform_heading_case(text:&str,style:&str,lowercase:&HashSet<String>,ignore:&Vec<String>,preserve:bool)->String{
    // Preserve custom id suffix {#...} as separate token unchanged
    let mut suffix="";
    let mut body=text;
    if let Some(pos)=text.rfind("{#"){ if text.ends_with('}'){ suffix=&text[pos..]; body=text[..pos].trim_end(); } }
    // Process preserving code spans and link destinations: token-based approach on body preserving spaces
    // Split into segments: code spans and link destinations and custom braces - simple parser
    let mut out=String::new();
    let mut word_index=0usize;
    let total_words=count_words(body);
    let mut i=0; let chars:Vec<char>=body.chars().collect();
    while i<chars.len(){
        // code span
        if chars[i]=='`'{ let mut j=i; while j<chars.len()&&chars[j]=='`'{j+=1;} let run=j-i; let mut k=j; let mut found=None; while k<chars.len(){ if chars[k]=='`'{let mut k2=k;while k2<chars.len()&&chars[k2]=='`'{k2+=1;} if k2-k==run{found=Some(k2);break;} k=k2;}else{k+=1;} } if let Some(end)=found{ out.extend(&chars[i..end]); word_index+=1; i=end; continue; } }
        // link destination (...) after ] - preserve as is but link text inside [] should be processed: handled by word tokenization including '[' as prefix punctuation
        if chars[i]=='(' && i>0 && chars[i-1]==']'{ let mut j=i; let mut depth=0; while j<chars.len(){ if chars[j]=='(' {depth+=1;} else if chars[j]==')'{depth-=1;j+=1; if depth==0{break;} continue;} j+=1;} out.extend(&chars[i..j]); i=j; continue; }
        if chars[i].is_whitespace(){ out.push(chars[i]); i+=1; continue; }
        // word token until whitespace
        let start=i; while i<chars.len()&&!chars[i].is_whitespace(){i+=1;}
        let token:String=chars[start..i].iter().collect();
        let transformed=transform_word(&token,style,lowercase,ignore,preserve,word_index,total_words);
        out.push_str(&transformed); word_index+=1;
    }
    if !suffix.is_empty(){ if !out.ends_with(' '){out.push(' ');} out.push_str(suffix); }
    out
}
fn count_words(s:&str)->usize{ s.split_whitespace().count() }
fn transform_word(token:&str,style:&str,lowercase:&HashSet<String>,ignore:&Vec<String>,preserve:bool,word_index:usize,total_words:usize)->String{
    // Separate leading/trailing punctuation (non alphanumeric) preserving brackets etc.
    let mut start=0; let chars:Vec<char>=token.chars().collect();
    while start<chars.len()&&!chars[start].is_alphanumeric(){start+=1;}
    let mut end=chars.len(); while end>start&&!chars[end-1].is_alphanumeric(){end-=1;}
    if start>=end{return token.to_string();}
    let prefix:String=chars[..start].iter().collect(); let core:String=chars[start..end].iter().collect(); let suffix:String=chars[end..].iter().collect();
    // ignore-words exact match case-insens returns ignore entry
    for ig in ignore{ if ig.eq_ignore_ascii_case(&core){ return format!("{prefix}{ig}{suffix}"); } }
    if preserve {
        // word with internal capital after first char (not all upper) or digit+cap pattern
        let has_internal_cap=core.chars().skip(1).any(|c| c.is_ascii_uppercase());
        let is_all_upper=!core.is_empty()&&core.chars().any(|c| c.is_alphabetic())&&core.chars().filter(|c| c.is_alphabetic()).all(|c| c.is_ascii_uppercase());
        if has_internal_cap&&!is_all_upper{ return token.to_string(); }
        if style!="all_caps" && is_all_upper && core.chars().count()>1 {
            // Acronyms preserve? Docs preserve-cased words auto-preserve words with internal capitals; an all-caps word might be acronym. Test later. Keep preserve for title/sentence? javascript->Javascript in example was not acronym.
            // We'll preserve all-caps words of length <=4 as acronyms (common) - may be wrong, refine via tests
            if core.chars().count()<=4 { return token.to_string(); }
        }
    }
    let transformed_core=match style{
        "all_caps"=>core.to_ascii_uppercase(),
        "sentence_case"=>{
            if word_index==0{ capitalize_word(&core.to_ascii_lowercase()) } else { core.to_ascii_lowercase() }
        },
        _=>{ // title case
            // hyphen parts
            let is_lower_word=lowercase.contains(&core.to_ascii_lowercase());
            if is_lower_word && word_index!=0 && word_index+1!=total_words { core.to_ascii_lowercase() } else { core.split('-').map(|part| capitalize_word(&part.to_ascii_lowercase())).collect::<Vec<_>>().join("-") }
        }
    };
    format!("{prefix}{transformed_core}{suffix}")
}
fn capitalize_word(w:&str)->String{ let mut c=w.chars(); match c.next(){Some(f)=>f.to_ascii_uppercase().to_string()+c.as_str(),None=>String::new()} }

// Footnotes
pub struct FootnoteDef{pub label:String,pub line_idx:usize,pub content:String}
pub fn footnote_defs(ctx:&LintContext)->Vec<FootnoteDef>{
    let mut out=Vec::new();
    for idx in 0..ctx.line_count(){
        if ctx.lines[idx].in_code()||ctx.lines[idx].is_fence{continue;}
        let line=ctx.line(idx); let t=line.trim_start();
        if t.starts_with("[^"){
            if let Some(close)=t.find("]:"){
                let label=t[2..close].to_string();
                let mut content=t[close+2..].trim().to_string();
                // Multi-line continuations indented at least 4 spaces (?) following lines
                let mut j=idx+1;
                while j<ctx.line_count(){
                    let l=ctx.line(j);
                    if is_blank(l){ 
                        // blank then indented could still be footnote content; lookahead
                        if j+1<ctx.line_count() && (ctx.line(j+1).starts_with("    ")||ctx.line(j+1).starts_with('\t')){ j+=1; continue; } else {break;}
                    }
                    if l.starts_with("    ")||l.starts_with('\t'){ if !content.is_empty(){content.push(' ');} content.push_str(l.trim()); j+=1; } else {break;}
                }
                out.push(FootnoteDef{label,line_idx:idx,content});
            }
        }
    }
    out
}
pub fn footnote_refs(ctx:&LintContext)->Vec<(usize,String)>{
    // (line_idx,label) in order, excluding definitions
    let def_lines:HashSet<usize>=footnote_defs(ctx).iter().map(|d| d.line_idx).collect();
    let mut out=Vec::new();
    for idx in 0..ctx.line_count(){
        if ctx.lines[idx].in_code()||ctx.lines[idx].is_fence||def_lines.contains(&idx){continue;}
        let line=ctx.line(idx); let spans=code_span_ranges(line);
        let mut start=0;
        while let Some(pos)=line[start..].find("[^"){
            let p=start+pos; let char_pos=line[..p].chars().count();
            if in_code_span(&spans,char_pos){ start=p+2; continue; }
            if let Some(end)=line[p..].find(']'){ let label=line[p+2..p+end].to_string(); if !label.is_empty()&&!label.contains('['){ out.push((idx,label)); } start=p+end+1; } else {break;}
        }
    }
    out
}
fn md066(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let defs=footnote_defs(ctx); let refs=footnote_refs(ctx);
    let def_set:HashSet<String>=defs.iter().map(|d| d.label.clone()).collect();
    let ref_set:HashSet<String>=refs.iter().map(|r| r.1.clone()).collect();
    // Orphaned references: one per unique label? Original per occurrence? If same missing referenced twice, likely one per occurrence or one per label - use per occurrence but column is 1
    let mut seen_missing:HashSet<String>=HashSet::new();
    for (idx,label) in &refs{
        if !def_set.contains(label){
            // Should we dedup? Test later.
            out.push(warn(ctx,eff,info,idx+1,1,idx+1,line_end_col(ctx,*idx),format!("Footnote reference '[^{label}]' has no corresponding definition"),None));
        }
    }
    for d in &defs{
        if !ref_set.contains(&d.label){
            out.push(warn(ctx,eff,info,d.line_idx+1,1,d.line_idx+1,line_end_col(ctx,d.line_idx),format!("Footnote definition '[^{}]' is never referenced",d.label),None));
        }
    }
}
fn md067(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let defs=footnote_defs(ctx); let refs=footnote_refs(ctx);
    // Reference order unique by first occurrence
    let mut ref_order:Vec<String>=Vec::new(); for (_,l) in &refs{ if !ref_order.contains(l){ref_order.push(l.clone());} }
    // Only consider definitions that are referenced, in order
    let mut expected_iter=ref_order.iter();
    for d in &defs{
        if let Some(exp)=expected_iter.next(){
            // Advance expected until matching? Original warns at first def where its label != next expected ref label, one warning only.
            if d.label!=*exp{
                out.push(warn(ctx,eff,info,d.line_idx+1,1,d.line_idx+1,line_end_col(ctx,d.line_idx),format!("Footnote definition '[^{}]' is out of order; expected '[^{exp}]' next (based on reference order)",d.label),None));
                break;
            }
        }
    }
}
fn md068(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    for d in footnote_defs(ctx){ if d.content.trim().is_empty(){ out.push(warn(ctx,eff,info,d.line_idx+1,1,d.line_idx+1,line_end_col(ctx,d.line_idx),format!("Footnote definition '[^{}]' is empty",d.label),None)); } }
}
fn md070(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    for cb in &ctx.code_blocks{
        let lang=cb.lang.to_ascii_lowercase();
        if !(lang.is_empty()||lang=="markdown"||lang=="md"){continue;}
        let end=cb.end_line.unwrap_or(ctx.line_count());
        for idx in cb.start_line+1..end{
            let line=ctx.line(idx);
            if let Some((_indent,fc,cnt,_info))=crate::lint::parse_fence_line(crate::lint::strip_blockquote_prefix(line)){
                if fc==cb.fence_char && cnt>=cb.fence_len {
                    // Need max inner fence length among all such lines for suggested outer length
                    let mut max_inner=cnt;
                    for j in cb.start_line+1..end{ if let Some((_,f2,c2,_))=crate::lint::parse_fence_line(crate::lint::strip_blockquote_prefix(ctx.line(j))){ if f2==cb.fence_char{max_inner=max_inner.max(c2);} } }
                    let outer_suggest=cb.fence_char.to_string().repeat(max_inner+1);
                    let fence_str=cb.fence_char.to_string().repeat(cb.fence_len);
                    out.push(warn(ctx,eff,info,cb.start_line+1,1,cb.start_line+1,line_end_col(ctx,cb.start_line),format!("Nested {fence_str} at line {} closes block prematurely — use {outer_suggest} for outer fence",idx+1),None));
                    break;
                }
            }
        }
    }
}
