use crate::lint::*;
use crate::rule_funcs::*;
use crate::rules::*;
use crate::info::*;
use std::collections::HashSet;

pub fn md072(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let Some((start,end))=ctx.frontmatter_lines else{return;};
    let kind=ctx.frontmatter_kind.clone().unwrap_or("yaml".into());
    // Parse top-level keys with their line blocks
    #[derive(Clone)] struct Entry{key:String,lines:Vec<String>}
    let mut entries:Vec<Entry>=Vec::new();
    if kind=="json" {
        // Parse JSON object preserving order via serde_json with preserve_order
        let fm_text = (start..=end).map(|i| ctx.line(i)).collect::<Vec<_>>().join("\n");
        if let Ok(serde_json::Value::Object(map))=serde_json::from_str::<serde_json::Value>(&fm_text){
            let keys:Vec<String>=map.keys().cloned().collect();
            let sorted={let mut s=keys.clone(); s.sort_by(|a,b| a.to_ascii_lowercase().cmp(&b.to_ascii_lowercase())); s};
            if keys!=sorted{
                // find first out-of-order pair for message: iterate sorted expected order vs actual: Message gives a key that should come before another - original: find first key in sorted order that is misplaced? Example keys [title,author] sorted [author,title] message 'author' should come before 'title' (sorted[0] before actual[0])
                let (should,before)=find_first_misplaced(&keys,&sorted);
                // Build fixed JSON pretty with sorted keys (serde_json Map insertion order)
                let mut new_map=serde_json::Map::new(); for k in &sorted{ new_map.insert(k.clone(),map.get(k).unwrap().clone()); }
                let fixed_json=serde_json::to_string_pretty(&serde_json::Value::Object(new_map)).unwrap();
                // Whole document replacement range 0..byte_end of last line (content len minus final newline if present? original replacement in probe is whole doc without final newline)
                let mut fixed_doc=fixed_json;
                // Append remainder of document after frontmatter
                for i in end+1..ctx.line_count(){ fixed_doc.push('\n'); fixed_doc.push_str(ctx.line(i)); }
                let range_end=ctx.content.len();
                out.push(warn(ctx,eff,info,start+2,1,start+2,line_end_col(ctx,start+1),format!("JSON frontmatter keys are not sorted alphabetically: '{should}' should come before '{before}'"),Some(FixInfo{range:FixRange{start:0,end:range_end},replacement:fixed_doc})));
            }
        }
        return;
    }
    // YAML / TOML line based
    for idx in start+1..end{
        let line=ctx.line(idx);
        if line.trim().is_empty(){ if let Some(last)=entries.last_mut(){last.lines.push(line.to_string());} continue; }
        let is_top = !line.starts_with(|c:char| c.is_whitespace()) && !line.trim_start().starts_with('-');
        let key_opt=if is_top {
            if kind=="toml" { line.split('=').next().map(|s| s.trim().trim_matches(|c| c=='"'||c=='\'').to_string()) } else { line.split(':').next().map(|s| s.trim().trim_matches(|c| c=='"'||c=='\'').to_string()) }
        } else {None};
        if let Some(key)=key_opt{ if !key.is_empty()&&!key.starts_with('#') { entries.push(Entry{key,lines:vec![line.to_string()]}); continue; } }
        if let Some(last)=entries.last_mut(){ last.lines.push(line.to_string()); }
    }
    let keys:Vec<String>=entries.iter().map(|e| e.key.clone()).collect();
    let mut sorted_idx:Vec<usize>=(0..entries.len()).collect(); sorted_idx.sort_by(|&a,&b| entries[a].key.to_ascii_lowercase().cmp(&entries[b].key.to_ascii_lowercase()));
    let sorted_keys:Vec<String>=sorted_idx.iter().map(|&i| entries[i].key.clone()).collect();
    if keys!=sorted_keys{
        let (should,before)=find_first_misplaced(&keys,&sorted_keys);
        let format_name=if kind=="toml"{"TOML"}else{"YAML"};
        // Build fixed whole document
        let mut fixed_lines:Vec<String>=Vec::new();
        fixed_lines.push(ctx.line(start).to_string());
        for &i in &sorted_idx{ for l in &entries[i].lines{fixed_lines.push(l.clone());} }
        fixed_lines.push(ctx.line(end).to_string());
        for i in end+1..ctx.line_count(){ fixed_lines.push(ctx.line(i).to_string()); }
        // Lines before start is 0 always for frontmatter
        let fixed_doc=fixed_lines.join("\n");
        let range_end=ctx.content.len();
        out.push(warn(ctx,eff,info,start+2,1,start+2,line_end_col(ctx,start+1),format!("{format_name} frontmatter keys are not sorted alphabetically: '{should}' should come before '{before}'"),Some(FixInfo{range:FixRange{start:0,end:range_end},replacement:fixed_doc})));
    }
}
fn find_first_misplaced(actual:&[String],sorted:&[String])->(String,String){
    for i in 0..actual.len(){ if actual[i]!=sorted[i]{ return (sorted[i].clone(),actual[i].clone()); } }
    (String::new(),String::new())
}

pub fn md073(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    // Marker based only: find <!-- toc --> exact lower and <!-- tocstop -->
    let mut toc_start:Option<usize>=None; let mut toc_end:Option<usize>=None;
    for idx in 0..ctx.line_count(){
        let t=ctx.line(idx).trim();
        if t=="<!-- toc -->"{toc_start=Some(idx);}
        else if t=="<!-- tocstop -->"&&toc_start.is_some(){toc_end=Some(idx);break;}
    }
    let (Some(ts),Some(te))=(toc_start,toc_end) else{return;};
    let cfg=crate::rules::RuleCfg{eff,code:"MD073"};
    let min_level=cfg.get_usize("min-level").unwrap_or(2); let max_level=cfg.get_usize("max-level").unwrap_or(4); let enforce_order=cfg.get_bool("enforce-order").unwrap_or(true);
    let indent_cfg={
        // MD073 indent default in defaults is 2 but docs say default from MD007 if not explicitly set. Our defaults map gives 2 always; check raw presence
        if eff.config.rules.get("MD073").map(|m| m.contains_key("indent")).unwrap_or(false){ cfg.get_usize("indent").unwrap_or(2) } else {
            let cfg7=crate::rules::RuleCfg{eff,code:"MD007"}; cfg7.get_usize("indent").unwrap_or(2)
        }
    };
    // Headings after toc_end
    let headings=get_headings(ctx);
    let expected:Vec<&Heading>=headings.iter().filter(|h| h.line_idx>te&&h.level>=min_level&&h.level<=max_level).collect();
    // Parse existing TOC entries between markers: list items with links [text](#anchor)
    #[derive(Debug)] struct TocEntry{text:String,anchor:String,line_idx:usize,level:usize}
    let mut existing:Vec<TocEntry>=Vec::new();
    for idx in ts+1..te{
        let line=ctx.line(idx);
        for link in crate::rule_funcs4::find_links(line){
            if let Some(dest)=&link.dest{ if let Some(frag)=dest.strip_prefix('#'){ 
                let indent=line.chars().take_while(|c| *c==' ').count();
                existing.push(TocEntry{text:link.text.clone(),anchor:frag.to_string(),line_idx:idx,level:indent/indent_cfg.max(1)});
            } }
        }
    }
    // Build expected anchors with duplicate handling using heading_anchors order aligned with get_headings (custom anchors complicate; use github_slug with counts across all headings in doc)
