use crate::lint::*;
use crate::rule_funcs::*;
use crate::rules::*;
use crate::info::*;

fn split_raw(line:&str)->Vec<String>{
    // like split_table_cells but preserve \| as-is in cell text
    let trimmed=line.trim(); let chars:Vec<char>=trimmed.chars().collect(); let mut cells=Vec::new(); let mut cur=String::new(); let mut i=0; let mut code_run=0usize;
    while i<chars.len(){
        let c=chars[i];
        if c=='\\'&&i+1<chars.len()&&chars[i+1]=='|'{cur.push('\\');cur.push('|');i+=2;continue;}
        if c=='`'{let mut j=i;while j<chars.len()&&chars[j]=='`'{j+=1;}let run=j-i;if code_run==0{code_run=run;}else if run==code_run{code_run=0;}for _ in 0..run{cur.push('`');}i=j;continue;}
        if c=='|'&&code_run==0{cells.push(cur.trim().to_string());cur=String::new();i+=1;continue;}
        cur.push(c);i+=1;
    }
    cells.push(cur.trim().to_string());
    if trimmed.starts_with('|'){if !cells.is_empty(){cells.remove(0);}}
    if trimmed.ends_with('|')&&!trimmed.ends_with("\\|"){if !cells.is_empty(){cells.pop();}}
    cells
}
fn vwidth(s:&str)->usize{ s.chars().map(|c| if c=='\t'{1}else{unicode_width::UnicodeWidthChar::width(c).unwrap_or(0)}).sum() }
fn pad_align(text:&str,width:usize,align:&str)->String{
    let w=vwidth(text); if w>=width{return text.to_string();}
    let pad=width-w;
    match align{ "right"=>format!("{}{}", " ".repeat(pad),text), "center"=>{let left=pad/2; let right=pad-left; format!("{}{}{}"," ".repeat(left),text," ".repeat(right))}, _=>format!("{}{}",text," ".repeat(pad)) }
}
fn delim_align(cell:&str)->&'static str{ let t=cell.trim(); if t.starts_with(':')&&t.ends_with(':')&&t.len()>1{"center"}else if t.ends_with(':'){"right"}else{"left"} }
fn make_delim(width:usize,align:&str,total_len:usize)->String{
    // total_len is segment length between pipes (for aligned = width, for no-space=width+2)
    match align{ "right"=>format!("{}:", "-".repeat(total_len.saturating_sub(1))), "center"=>format!(":{}:", "-".repeat(total_len.saturating_sub(2))), "left-explicit"=>format!(":{}", "-".repeat(total_len.saturating_sub(1))), _=>"-".repeat(total_len) }
}
pub fn md060(ctx:&LintContext,eff:&EffectiveConfig,info:&RuleInfo,out:&mut Vec<LintWarning>){
    let cfg=rcfg(eff,info);
