    let col_align_body_raw=eff.config.rules.get("MD060").and_then(|m| m.get("column-align-body")).and_then(|v| if let toml::Value::String(s)=v{Some(s.clone())}else{None});
    let loose_last=cfg.get_bool("loose-last-column").unwrap_or(false);
    // max-width threshold
    let threshold:Option<usize>=if max_width_cfg>0{Some(max_width_cfg as usize)}else{
        // smart inherit: only if MD013 tables=true and line-length>0 and MD013 not in global disable list (config)
        let cfg13=RuleCfg{eff,code:"MD013"};
        let tables13=cfg13.get_bool("tables").unwrap_or(false);
        let ll=if eff.config.rules.get("MD013").map(|m| m.contains_key("line-length")).unwrap_or(false){cfg13.get_i64("line-length").unwrap_or(80)}else if eff.config.global_explicit.contains("line-length"){eff.config.global.line_length as i64}else{cfg13.get_i64("line-length").unwrap_or(80)};
        let md013_disabled=eff.config.global.disable.iter().any(|s| crate::info::resolve_rule(s).map(|i| i.code)==Some("MD013"));
        if tables13&&ll>0&&!md013_disabled{Some(ll as usize)}else{None}
    };
    for table in get_tables(ctx){
        let mut all_rows=vec![table.header_idx,table.sep_idx]; all_rows.extend(table.row_indices.iter());
        // skip complex unicode
        let all_text:Vec<String>=all_rows.iter().map(|&r| ctx.line(r).to_string()).collect();
        if all_text.iter().any(|l| l.contains('\u{200d}')||l.contains('\u{200b}')||l.contains('\u{200c}')||l.contains('\u{2060}')){continue;}
        let header_cells=split_raw(ctx.line(table.header_idx));
        let ncols=header_cells.len(); if ncols==0{continue;}
        let delim_cells=split_raw(ctx.line(table.sep_idx));
        let mut body_cells:Vec<Vec<String>>=Vec::new();
        for &r in &table.row_indices{ let mut c=split_raw(ctx.line(r)); c.truncate(ncols); while c.len()<ncols{c.push(String::new());} body_cells.push(c); }
        let mut widths=vec![3usize;ncols];
        for (i,cell) in header_cells.iter().enumerate(){widths[i]=widths[i].max(vwidth(cell));}
        for row in &body_cells{ for (i,cell) in row.iter().enumerate(){widths[i]=widths[i].max(vwidth(cell));} }
