        let header_spec=col_align_header_raw.clone().unwrap_or(col_align.clone());
        let body_spec=col_align_body_raw.clone().unwrap_or(col_align.clone());
        let format_table=|style:&str|->Vec<String>{
            let mut lines=Vec::new();
            match style{
                "tight"=>{
                    lines.push(format!("|{}|",header_cells.join("|")));
                    // delimiter preserve trimmed segments
                    let segs=(0..ncols).map(|i| delim_cells.get(i).cloned().unwrap_or("---".into())).collect::<Vec<_>>();
                    lines.push(format!("|{}|",segs.join("|")));
                    for row in &body_cells{lines.push(format!("|{}|",row.join("|")));}
                },
                "compact"=>{
                    lines.push(format!("| {} |",header_cells.join(" | ")));
                    let segs=(0..ncols).map(|i| delim_cells.get(i).cloned().unwrap_or("---".into())).collect::<Vec<_>>();
                    lines.push(format!("| {} |",segs.join(" | ")));
                    for row in &body_cells{lines.push(format!("| {} |",row.join(" | ")));}
                },
                "aligned-no-space"=>{
                    let mut header_segs=Vec::new(); for i in 0..ncols{header_segs.push(pad_align(&header_cells[i],widths[i],&explicit_align(&header_spec,i)));}
                    lines.push(format!("| {} |",header_segs.join(" | ")));
                    let mut dsegs=Vec::new(); for i in 0..ncols{ let al=explicit_align(&col_align,i); let orig=delim_cells.get(i).map(|s| s.as_str()).unwrap_or("---"); let eff_align=if orig.starts_with(':')&&orig.ends_with(':')&&orig.len()>1{"center"}else if orig.ends_with(':'){"right"}else if orig.starts_with(':'){"left-explicit"}else{"none"}; dsegs.push(make_delim(widths[i],eff_align,widths[i]+2)); }
                    lines.push(format!("|{}|",dsegs.join("|")));
                    for row in &body_cells{ let mut segs=Vec::new(); for i in 0..ncols{ if loose_last&&i==ncols-1{segs.push(row[i].clone());}else{segs.push(pad_align(&row[i],widths[i],&explicit_align(&body_spec,i)));} } lines.push(format!("| {} |",segs.join(" | "))); }
                },
                _=>{ // aligned
                    let mut header_segs=Vec::new(); for i in 0..ncols{header_segs.push(pad_align(&header_cells[i],widths[i],&explicit_align(&header_spec,i)));}
                    lines.push(format!("| {} |",header_segs.join(" | ")));
                    let mut dsegs=Vec::new(); for i in 0..ncols{ let orig=delim_cells.get(i).map(|s| s.as_str()).unwrap_or("---"); let eff_align=if orig.starts_with(':')&&orig.ends_with(':')&&orig.len()>1{"center"}else if orig.ends_with(':'){"right"}else if orig.starts_with(':'){"left-explicit"}else{"none"}; dsegs.push(make_delim(widths[i],eff_align,widths[i])); }
                    lines.push(format!("| {} |",dsegs.join(" | ")));
                    for row in &body_cells{ let mut segs=Vec::new(); for i in 0..ncols{ if loose_last&&i==ncols-1{segs.push(row[i].clone());}else{segs.push(pad_align(&row[i],widths[i],&explicit_align(&body_spec,i)));} } lines.push(format!("| {} |",segs.join(" | "))); }
                }
            }
            lines
        };
        let effective_style:String=if style_cfg=="any"{
            // choose style with least diffs
            let mut best=("compact",usize::MAX);
            for cand in ["aligned","compact","tight","aligned-no-space"]{
                let formatted=format_table(cand); let diffs=formatted.iter().zip(all_rows.iter()).filter(|(f,&r)| *f!=ctx.line(r)).count();
                if diffs<best.1{best=(cand,diffs);}
            }
            best.0.to_string()
        } else {style_cfg.clone()};
        let mut formatted=format_table(&effective_style);
        if (effective_style=="aligned"||effective_style=="aligned-no-space"){
            if let Some(th)=threshold{ let maxlen=formatted.iter().map(|l| vwidth(l)).max().unwrap_or(0); if maxlen>th{ formatted=format_table("compact"); } }
        }
        let table_start=ctx.line_byte_start(table.header_idx); let last_row=*all_rows.last().unwrap(); let mut table_end=ctx.line_byte_end(last_row); if table_end<ctx.content.len(){/* keep like MD055: original adds +1 */ table_end+=1;}
        let fixed_table=formatted.join("\n");
        for (k,&r) in all_rows.iter().enumerate(){
            if ctx.line(r)!=formatted[k]{
                out.push(warn(ctx,eff,info,r+1,1,r+1,line_end_col(ctx,r),"Table columns should be aligned".to_string(),Some(FixInfo{range:FixRange{start:table_start,end:table_end},replacement:fixed_table.clone()})));
            }
        }
    }
}
