use crate::config::*;
use crate::info::*;
use crate::lint::*;
use std::collections::HashSet;

pub struct InlineResult {
    pub cfg: Config,
    pub disabled_by_line: Vec<HashSet<String>>, // contains "ALL" or codes
}

fn parse_rules_tokens(s:&str)->Vec<String>{
    let mut out=Vec::new();
    for tok in s.split(|c:char| c.is_whitespace()||c==','){
        if tok.is_empty(){continue;}
        if tok.eq_ignore_ascii_case("all"){out.push("ALL".to_string()); continue;}
        if let Some(info)=resolve_rule(tok){out.push(info.code.to_string());}
    }
    out
}

pub fn preprocess(ctx:&LintContext, base:&Config)->InlineResult{
    let mut cfg=base.clone();
    let n=ctx.line_count();
    let mut disabled_all=false;
    let mut disabled:Set=HashSet::new();
    type Set=HashSet<String>;
    let mut stack:Vec<(bool,Set)>=Vec::new();
    let mut next_all=false; let mut next_rules:Set=HashSet::new();
    let mut file_all=false; let mut file_rules:Set=HashSet::new();
    let mut by_line:Vec<Set>=vec![HashSet::new(); n];
    // For multiline comments, track in_comment across lines and accumulate comment text, applying when --> is found on line where it closes? Comments commands are usually single line.
    let mut in_comment=false; let mut comment_buf=String::new(); let mut comment_start_line=0usize;
    for idx in 0..n{
        let mut current:Set=HashSet::new();
        if disabled_all{current.insert("ALL".into());} else { for r in &disabled{current.insert(r.clone());} }
        if next_all{current.insert("ALL".into());} else { for r in &next_rules{current.insert(r.clone());} }
        next_all=false; next_rules.clear();
        if ctx.lines[idx].in_fenced_code || ctx.lines[idx].in_indented_code || ctx.lines[idx].in_frontmatter {
            by_line[idx]=current; continue;
        }
        let line=ctx.line(idx);
        let spans=code_span_ranges(line);
        // collect comments on this line (including closing a multiline)
        let mut comments:Vec<String>=Vec::new();
        let chars:Vec<char>=line.chars().collect();
        let mut i=0;
        if in_comment {
            if let Some(end_pos)=line.find("-->"){ comment_buf.push_str(&line[..end_pos]); comments.push(comment_buf.clone()); comment_buf.clear(); in_comment=false; i=line[..end_pos+3].chars().count(); } else { comment_buf.push_str(line); by_line[idx]=current; continue; }
        }
        while i<chars.len(){
            // find <!--
            let substr:String=chars[i..].iter().collect();
            if substr.starts_with("<!--") && !in_code_span(&spans,i){
                if let Some(end_rel)=substr[4..].find("-->"){ comments.push(substr[4..4+end_rel].to_string()); i+=4+end_rel+3; continue; }
                else { in_comment=true; comment_start_line=idx; comment_buf=substr[4..].to_string(); break; }
            }
            i+=1;
        }
        for comment in comments{
            let inner=comment.trim();
            if inner=="prettier-ignore" { next_all=true; continue; }
            let mut rest:Option<&str>=None;
            for pre in ["rumdl-","markdownlint-"]{ if inner.starts_with(pre){rest=Some(&inner[pre.len()..]); break;} }
            let Some(rest)=rest else{continue;};
            let mut parts=rest.splitn(2,|c:char| c.is_whitespace());
            let cmd=parts.next().unwrap_or("");
            let arg=parts.next().unwrap_or("").trim();
            match cmd {
                "disable"=>{
                    let rules=parse_rules_tokens(arg);
                    if arg.is_empty()||rules.iter().any(|r| r=="ALL"){disabled_all=true; disabled.clear(); current.insert("ALL".into());}
                    else { for r in &rules{disabled.insert(r.clone()); current.insert(r.clone());} }
                },
                "enable"=>{
                    let rules=parse_rules_tokens(arg);
                    if arg.is_empty()||rules.iter().any(|r| r=="ALL"){disabled_all=false; disabled.clear(); current.remove("ALL"); current.clear();}
                    else { for r in &rules{disabled.remove(r); current.remove(r);} }
                },
                "disable-line"=>{
                    let rules=parse_rules_tokens(arg);
                    if arg.is_empty()||rules.iter().any(|r| r=="ALL"){current.insert("ALL".into());}else{for r in rules{current.insert(r);}}
                },
                "disable-next-line"=>{
                    let rules=parse_rules_tokens(arg);
                    if arg.is_empty()||rules.iter().any(|r| r=="ALL"){next_all=true;}else{for r in rules{next_rules.insert(r);}}
                },
                "disable-file"=>{
                    let rules=parse_rules_tokens(arg);
                    if arg.is_empty()||rules.iter().any(|r| r=="ALL"){file_all=true;}else{for r in rules{file_rules.insert(r);}}
                },
                "enable-file"=>{
                    // markdownlint enable-file likely cancels disable-file for whole file; approximation
                    file_all=false; file_rules.clear();
                },
                "capture"=>{ stack.push((disabled_all,disabled.clone())); },
                "restore"=>{ if let Some((a,s))=stack.pop(){disabled_all=a;disabled=s; // recompute current for this line as restored state (comment only line)
                    current.clear(); if disabled_all{current.insert("ALL".into());}else{for r in &disabled{current.insert(r.clone());}}
                } },
                "configure-file"=>{
                    let json_str=arg.trim();
                    if let Ok(serde_json::Value::Object(map))=serde_json::from_str::<serde_json::Value>(json_str){
                        for (rk,rv) in map{
                            if let Some(info)=resolve_rule(&rk){
                                if let serde_json::Value::Object(entries)=rv{
                                    cfg.rule_sections.insert(info.code.to_string());
                                    let m=cfg.rules.entry(info.code.to_string()).or_default();
                                    for (k,v) in entries{
                                        let nk=norm_key(&k);
                                        if nk=="severity"{ if let serde_json::Value::String(s)=&v{ if let Some(sev)=Severity::parse(s){cfg.severities.insert(info.code.to_string(),sev);} } continue; }
                                        if let Some(tv)=crate::import_convert::json_to_toml(&v){ if let toml::Value::Table(_)=tv{ cfg.rule_tables.entry(info.code.to_string()).or_default().insert(nk,tv); } else { m.insert(nk,tv); } }
                                    }
                                }
                            }
                        }
                    }
                },
                _=>{}
            }
        }
        by_line[idx]=current;
    }
    if file_all { for s in &mut by_line{ s.insert("ALL".into()); } } else if !file_rules.is_empty(){ for s in &mut by_line{ for r in &file_rules{s.insert(r.clone());} } }
    InlineResult{cfg,disabled_by_line:by_line}
}

