            embedded_changed_total+=emb_count;
            if fixed!=*content { any_diff=true; let d=crate::fix::generate_diff(content,&fixed,&f.display); out.push_str(&d); }
        }
        if args.stderr_flag { eprint!("{out}"); } else { print!("{out}"); }
        if !args.quiet {
            if fix_effective {
                let fixed_for_summary=fixable+embedded_changed_total;
                print_summary(color,total,fixable,fixed_for_summary,files_with,results.len(),elapsed_ms,true,args.statistics,results,args.profile,args.stderr_flag);
            } else {
                if total==0 && any_diff {
                    let prefix=if color{"\x1b[33mIssues:\x1b[0m"}else{"Issues:"};
                    let file_str=format!("{} {}", results.len(), if results.len()==1{"file"}else{"files"});
                    println!("\n{prefix} Found 0 issues in {file_str} ({elapsed_ms}ms)");
                    if args.statistics { /* no stats for 0 */ }
                    if args.profile { if args.stderr_flag{eprintln!("\nProfiling is disabled.");}else{println!("\nProfiling is disabled.");} }
                } else {
                    print_summary(color,total,fixable,0,files_with,results.len(),elapsed_ms,false,args.statistics,results,args.profile,args.stderr_flag);
                }
            }
        }
    } else {
        // silent: still need embedded count / any_diff for fmt --check exit
        for (idx,(entry,content)) in file_data.iter().enumerate() {
            let flavor=flavor_for_file(args,cfg,entry);
            let per_disabled=per_file_disabled(cfg,entry);
            let enabled_for_file:Vec<&RuleInfo>=enabled.iter().filter(|r| !per_disabled.contains(r.code)).copied().collect();
            let ((fixed,_),emb_count)=crate::fix::apply_fixes_embedded(content,cfg,&enabled_for_file,flavor,Some(entry.abs_path.clone()),true);
            embedded_changed_total+=emb_count; if fixed!=*content{any_diff=true;}
            let _=idx;
        }
    }
    if is_fmt {
        if args.check_flag && (fixable>0 || any_diff) { return 1; }
        return 0;
    }
    let all:Vec<LintWarning>=results.iter().flat_map(|r| r.warnings.clone()).collect();
    if fail_exit(&all,&args.fail_on){1}else{0}
}

