#[derive(Serialize,Deserialize)]
pub struct CachedFix{ pub range: FixRange, pub replacement:String }
#[derive(Serialize,Deserialize)]
pub struct CachedWarning{ pub message:String, pub line:usize, pub column:usize, pub end_line:usize, pub end_column:usize, pub severity:Severity, pub fix:Option<CachedFix>, pub rule_name:String }
#[derive(Serialize,Deserialize)]
pub struct CacheEntry{ pub file_hash:String, pub config_hash:String, pub rules_hash:String, pub version:String, pub warnings:Vec<CachedWarning>, pub timestamp:u64 }
