}
pub fn save_cache(cache_dir:&Path,file_hash:&str,config_hash:&str,rules_hash:&str,warnings:&[LintWarning]){
    let path=cache_file_path(cache_dir,file_hash,rules_hash);
    if let Some(parent)=path.parent(){let _=std::fs::create_dir_all(parent);}
    let entry=CacheEntry{file_hash:file_hash.to_string(),config_hash:config_hash.to_string(),rules_hash:rules_hash.to_string(),version:"0.1.13".to_string(),warnings:warnings.iter().map(|w| CachedWarning{message:w.message.clone(),line:w.line,column:w.column,end_line:w.end_line,end_column:w.end_column,severity:w.severity,fix:w.fix.as_ref().map(|f| CachedFix{range:f.range.clone(),replacement:f.replacement.clone()}),rule_name:w.rule_name.clone()}).collect(),timestamp:std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_secs()).unwrap_or(0)};
    if let Ok(s)=serde_json::to_string_pretty(&entry){ let _=std::fs::write(path,s); }
