// Workspace index (simplified bincode-like format with RWSI magic)
#[derive(Clone,Debug)]
pub struct WsEntry{ pub headings:Vec<(String,String)>, pub hash:String }
#[derive(Clone,Debug,Default)]
pub struct WorkspaceIndex{ pub files:BTreeMap<PathBuf,WsEntry> }
fn write_varint(out:&mut Vec<u8>, mut v:u64){
    if v<251{out.push(v as u8);}else if v<=0xFFFF{out.push(251); out.extend_from_slice(&(v as u16).to_le_bytes());}else if v<=0xFFFFFFFF{out.push(252); out.extend_from_slice(&(v as u32).to_le_bytes());}else{out.push(253); out.extend_from_slice(&v.to_le_bytes());}
}
fn read_varint(data:&[u8], pos:&mut usize)->Option<u64>{
    let b=*data.get(*pos)?; *pos+=1;
    match b{ 251=>{ let v=u16::from_le_bytes(data.get(*pos..*pos+2)?.try_into().ok()?) as u64; *pos+=2; Some(v)},252=>{let v=u32::from_le_bytes(data.get(*pos..*pos+4)?.try_into().ok()?) as u64; *pos+=4; Some(v)},253=>{let v=u64::from_le_bytes(data.get(*pos..*pos+8)?.try_into().ok()?); *pos+=8; Some(v)}, _=>Some(b as u64) }
}
fn write_str(out:&mut Vec<u8>,s:&str){ write_varint(out,s.len() as u64); out.extend_from_slice(s.as_bytes()); }
fn read_str(data:&[u8],pos:&mut usize)->Option<String>{ let len=read_varint(data,pos)? as usize; let bytes=data.get(*pos..*pos+len)?; *pos+=len; Some(String::from_utf8_lossy(bytes).to_string()) }
