    pub fn load(cache_dir:&Path)->Option<Self>{
        let data=std::fs::read(cache_dir.join("workspace_index.bin")).ok()?;
        if data.len()<8||&data[0..4]!=b"RWSI"{return None;}
        let version=u32::from_le_bytes(data[4..8].try_into().ok()?); if version!=5{return None;}
        let mut pos=8usize; let count=read_varint(&data,&mut pos)? as usize;
        let mut files=BTreeMap::new();
        for _ in 0..count{
            let path_str=read_str(&data,&mut pos)?;
            let hcount=read_varint(&data,&mut pos)? as usize; let mut headings=Vec::new();
            for _ in 0..hcount{ let text=read_str(&data,&mut pos)?; let anchor=read_str(&data,&mut pos)?; let _line=read_varint(&data,&mut pos)?; headings.push((text,anchor)); }
            // links: encode as count then each has 4 fields (we don't store links in load usage except hash - keep format self-consistent)
            let lcount=read_varint(&data,&mut pos)? as usize; for _ in 0..lcount{ let _a=read_str(&data,&mut pos)?; let _b=read_str(&data,&mut pos)?; let _c=read_varint(&data,&mut pos)?; let _d=read_varint(&data,&mut pos)?; }
            let hash=read_str(&data,&mut pos)?;
            files.insert(PathBuf::from(path_str),WsEntry{headings,hash});
        }
        Some(Self{files})
    }
    pub fn save(&self,cache_dir:&Path){
        let mut out:Vec<u8>=Vec::new(); out.extend_from_slice(b"RWSI"); out.extend_from_slice(&5u32.to_le_bytes());
        write_varint(&mut out,self.files.len() as u64);
        for (path,entry) in &self.files{
            write_str(&mut out,&path.to_string_lossy());
            write_varint(&mut out,entry.headings.len() as u64);
            for (text,anchor) in &entry.headings{ write_str(&mut out,text); write_str(&mut out,anchor); write_varint(&mut out,0); }
            write_varint(&mut out,0); // links count placeholder
            write_str(&mut out,&entry.hash);
            // anchors set mimic: count + anchors (not read in this simplified format after hash - but our loader expects after hash next entry, so do NOT write extra here)
        }
        // reverse index placeholder: write 0 count as trailing varint to resemble original trailing data
        write_varint(&mut out,0);
        let _=std::fs::write(cache_dir.join("workspace_index.bin"),out);
    }
}
