            for (text,anchor) in &entry.headings{ write_str(&mut out,text); write_str(&mut out,anchor); write_varint(&mut out,0); }
            write_varint(&mut out,0); // links count placeholder
            write_str(&mut out,&entry.hash);
            // anchors set mimic: count + anchors (not read in this simplified format after hash - but our loader expects after hash next entry, so do NOT write extra here)
        }
        // reverse index placeholder: write 0 count as trailing varint to resemble original trailing data
        write_varint(&mut out,0);
        let _=std::fs::write(cache_dir.join("workspace_index.bin"),out);
    }
}
