        file_data.push((entry.clone(),content));
    }
    // Workspace index update/save logs
    if args.verbose && !args.silent {
        let pruned=loaded_ws.as_ref().map(|ws| ws.files.keys().filter(|k| !new_ws.files.contains_key(*k)).count()).unwrap_or(0);
