# add project_root field to Config struct after warning_path
t=t.replace('    pub warning_path: Option<String>,','    pub warning_path: Option<String>,\n    pub project_root: Option<PathBuf>,')
start=t.index('pub fn load_resolved')
end=t.index('pub fn user_config_candidate')
new=r'''pub fn load_resolved(global:&crate::cli::GlobalOpts, start_dir:&Path, suppress_config_warnings:bool)->Result<Config,String>{
    let abs_start=std::fs::canonicalize(start_dir).unwrap_or_else(|_| if start_dir.is_absolute(){start_dir.to_path_buf()}else{std::env::current_dir().unwrap_or(PathBuf::from(".")).join(start_dir)});
    log::debug!("[rumdl-config] Current working directory: Ok({:?})", abs_start.to_string_lossy());
    let cwd_abs=std::fs::canonicalize(std::env::current_dir().unwrap_or(PathBuf::from("."))).unwrap_or(abs_start.clone());
    if global.no_config {
        log::debug!("[rumdl-config] Skipping config discovery due to --no-config/--isolated flag");
        let mut c=Config::default(); c.project_root=Some(cwd_abs.clone()); return Ok(c);
    }
    if let Some(cfg_path)=&global.config {
