use crate::check::CheckArgs;
use clap::ArgMatches;
use std::collections::HashMap;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::time::{Duration, SystemTime};

fn now_str()->String{ chrono::Local::now().format("%H:%M:%S").to_string() }
fn is_config_name(p:&Path)->bool{
    let name=p.file_name().and_then(|s| s.to_str()).unwrap_or("");
    name==".rumdl.toml"||name=="rumdl.toml"||name=="pyproject.toml"||crate::config::MARKDOWNLINT_CANDIDATES.contains(&name)
}
fn is_relevant(p:&Path, explicit_files:&Vec<PathBuf>)->bool{
    if explicit_files.contains(&p.to_path_buf()){return true;}
    if is_config_name(p){return true;}
    crate::check::is_markdown_file_pub(p)
}
fn snapshot(watch_paths:&[PathBuf], explicit_files:&Vec<PathBuf>)->HashMap<PathBuf,(u64,SystemTime)>{
    let mut map=HashMap::new();
    for wp in watch_paths{
        if wp.is_file(){
            if is_relevant(wp,explicit_files){ if let Ok(m)=std::fs::metadata(wp){ map.insert(wp.clone(),(m.len(),m.modified().unwrap_or(SystemTime::UNIX_EPOCH))); } }
        } else if wp.is_dir(){
            for entry in walkdir(wp){ if entry.is_file()&&is_relevant(&entry,explicit_files){ if let Ok(m)=std::fs::metadata(&entry){ map.insert(entry,(m.len(),m.modified().unwrap_or(SystemTime::UNIX_EPOCH))); } } }
        }
    }
    map
}
fn walkdir(dir:&Path)->Vec<PathBuf>{
    let mut out=Vec::new(); let mut stack=vec![dir.to_path_buf()];
    while let Some(d)=stack.pop(){ if let Ok(rd)=std::fs::read_dir(&d){ for e in rd.flatten(){ let p=e.path(); let name=p.file_name().and_then(|s| s.to_str()).unwrap_or(""); if name==".rumdl_cache"||name==".git"{continue;} if p.is_dir(){stack.push(p);}else{out.push(p);} } } }
    out
}
pub fn run_watch(matches:&ArgMatches, global:&crate::cli::GlobalOpts, is_fmt:bool)->i32{
    let args=CheckArgs::from_matches(matches);
    // validation already done in run_check before calling watch
    print!("\x1b[2J\x1b[1;1H[{}] Starting linter in watch mode...\nPress Ctrl-C to exit\n\n", now_str());
    let _=std::io::stdout().flush();
    // determine watch paths
    let raw_paths:Vec<String>=if args.paths.is_empty(){vec![".".to_string()]}else{args.paths.clone()};
    let cwd=std::env::current_dir().unwrap_or(PathBuf::from("."));
    let mut watch_paths:Vec<PathBuf>=Vec::new();
    let mut explicit_files:Vec<PathBuf>=Vec::new();
    for raw in &raw_paths{
        let p=Path::new(raw);
        if !p.exists(){
            eprintln!("Warning: Failed to watch {raw}: No path was found.");
            continue;
        }
        let abs=std::fs::canonicalize(p).unwrap_or_else(|_| cwd.join(p));
        if abs.is_file(){explicit_files.push(abs.clone());}
        watch_paths.push(abs);
    }
    let diff_effective=args.diff_flag||(is_fmt&&args.check_flag);
    let mut snap=snapshot(&watch_paths,&explicit_files);
    let _code=crate::check::run_check_once(matches,global,is_fmt,&args,diff_effective);
    loop {
        println!("\nWatching for file changes...");
        let _=std::io::stdout().flush();
        // poll for change
        let changed_kind: String;
        loop {
            std::thread::sleep(Duration::from_millis(100));
            let new_snap=snapshot(&watch_paths,&explicit_files);
            if new_snap!=snap{
                let mut is_config=false;
                for k in new_snap.keys(){ if !snap.contains_key(k)&&is_config_name(k){is_config=true;} }
                for k in snap.keys(){ if !new_snap.contains_key(k)&&is_config_name(k){is_config=true;} }
                for (k,v) in &new_snap{ if snap.get(k)!=Some(v)&&is_config_name(k){is_config=true;} }
                snap=new_snap;
                changed_kind=if is_config{"Configuration change detected...".to_string()}else{"File change detected...".to_string()};
                // Debounce: wait a short period and refresh snapshot to coalesce rapid writes, but keep snapshot as from detection time so self-fixes trigger next cycle as original
                std::thread::sleep(Duration::from_millis(100));
                break;
            }
        }
        print!("\x1b[2J\x1b[1;1H[{}] {}\n\n", now_str(), changed_kind);
        let _=std::io::stdout().flush();
        let _code=crate::check::run_check_once(matches,global,is_fmt,&args,diff_effective);
    }
}
