use crate::cli::GlobalOpts;
use crate::config::*;
use crate::info::*;
use crate::lint::*;
use serde_json::{json, Value};
use std::collections::{HashMap, HashSet};
use std::io::{BufRead, BufReader, Read, Write};
use std::path::{Path, PathBuf};

pub fn run_server(matches:&clap::ArgMatches, global:&GlobalOpts)->i32{
    // explicit server config: server matches config arg already merged into global.config by resolve_global (server level wins)
    // But if global.no_config and a server config was also given, resolve_global clears config - original server still checks the server -c file existence regardless.
    // We need raw server config from matches:
    let server_cfg_raw=matches.get_one::<String>("config").cloned();
    let explicit_path=server_cfg_raw.clone().or(global.config.clone());
    if let Some(p)=&explicit_path {
        if !Path::new(p).exists() { eprintln!("Error: Configuration file not found: {p}"); return 2; }
    }
    // TCP or stdio
    if let Some(port)=matches.get_one::<u16>("port").copied(){
        let listener=match std::net::TcpListener::bind(("127.0.0.1",port)){Ok(l)=>l,Err(e)=>{eprintln!("Error: Failed to bind to port {port}: {e}"); return 2;}};
        for stream in listener.incoming(){
            match stream{ Ok(s)=>{ let reader=s.try_clone().unwrap(); let writer=s; serve_stream(reader,writer,global,explicit_path.clone()); }, Err(_)=>continue }
        }
        return 0;
    }
    let stdin=std::io::stdin();
    let stdout=std::io::stdout();
    serve_stream(stdin,stdout,global,explicit_path)
}

struct Doc{ text:String, version:Option<i64>, language_id:String }
struct Server{
    docs:HashMap<String,Doc>,
    root_dirs:Vec<PathBuf>,
    base_cfg:Config,
    base_global:GlobalOpts,
    explicit_path:Option<String>,
    settings_cfg:Option<Config>,
    settings_warnings:Vec<String>,
    next_req_id:i64,
    shutdown:bool,
}
fn uri_to_path(uri:&str)->Option<PathBuf>{
    if let Some(rest)=uri.strip_prefix("file://"){
        // file:///path or file://host/path
        let path_str=if rest.starts_with('/') {rest.to_string()} else { match rest.find('/'){Some(i)=>rest[i..].to_string(),None=>rest.to_string()} };
        Some(PathBuf::from(percent_decode(&path_str)))
    } else { None }
}
fn percent_decode(s:&str)->String{ let mut out:Vec<u8>=Vec::new(); let b=s.as_bytes(); let mut i=0; while i<b.len(){ if b[i]==b'%'&&i+2<b.len(){ if let Ok(v)=u8::from_str_radix(std::str::from_utf8(&b[i+1..i+3]).unwrap_or(""),16){out.push(v);i+=3;continue;} } out.push(b[i]);i+=1; } String::from_utf8_lossy(&out).to_string() }

fn read_message<R:Read>(reader:&mut BufReader<R>)->Option<Value>{
    let mut content_len:Option<usize>=None;
    loop {
        let mut line=String::new();
        let n=reader.read_line(&mut line).ok()?;
        if n==0{return None;}
        if line=="\r\n"||line=="\n"{break;}
        if let Some((k,v))=line.split_once(':'){ if k.trim().eq_ignore_ascii_case("Content-Length"){ content_len=v.trim().parse::<usize>().ok(); } }
    }
    let len=content_len?;
    let mut buf=vec![0u8;len]; reader.read_exact(&mut buf).ok()?;
    serde_json::from_slice(&buf).ok()
}
fn write_message<W:Write>(writer:&mut W, msg:&Value){
    let s=serde_json::to_string(msg).unwrap();
    let _=write!(writer,"Content-Length: {}\r\n\r\n{}",s.len(),s); let _=writer.flush();
}

fn serve_stream<R:Read,W:Write>(input:R, mut output:W, global:&GlobalOpts, explicit_path:Option<String>)->i32{
    let mut reader=BufReader::new(input);
    let mut server=Server{docs:HashMap::new(),root_dirs:vec![],base_cfg:Config::default(),base_global:global.clone(),explicit_path:explicit_path.clone(),settings_cfg:None,settings_warnings:vec![],next_req_id:0,shutdown:false};
    // Load base config eagerly if explicit (fallback default on error)
    if let Some(p)=&explicit_path{
        if let Ok(cfg)=crate::config::load_config_file(Path::new(p),p,p){ server.base_cfg=cfg; }
    } else if global.no_config {
        server.base_cfg=Config::default();
    } else {
        // Defer discovery per root/doc; base is cwd config as a fallback
        if let Ok(cfg)=crate::config::load_resolved(global,Path::new("."),true){ server.base_cfg=cfg; }
    }
    loop {
        let Some(msg)=read_message(&mut reader) else { break; };
        handle_message(&mut server,&msg,&mut output);
    }
    0
}

fn send(server:&mut Server, out:&mut impl Write, msg:Value){ write_message(out,&msg); }

fn handle_message(server:&mut Server, msg:&Value, out:&mut impl Write){
    let method=msg.get("method").and_then(|v| v.as_str());
    let id=msg.get("id").cloned();
    // Responses to our requests: ignore
    if method.is_none(){ return; }
    let method=method.unwrap();
    let params=msg.get("params").cloned();
    match method {
        "initialize"=>{
