            let mut roots:Vec<PathBuf>=Vec::new();
            if let Some(p)=&params{
                if let Some(folders)=p.get("workspaceFolders").and_then(|v| v.as_array()){
                    for f in folders{ if let Some(uri)=f.get("uri").and_then(|v| v.as_str()){ if let Some(path)=uri_to_path(uri){roots.push(path);} } }
                }
                if roots.is_empty(){
                    if let Some(uri)=p.get("rootUri").and_then(|v| v.as_str()){ if let Some(path)=uri_to_path(uri){roots.push(path);} }
                    else if let Some(rp)=p.get("rootPath").and_then(|v| v.as_str()){ if !rp.is_empty(){roots.push(PathBuf::from(rp));} }
                }
            }
            server.root_dirs=roots;
            let result=json!({
                "capabilities":{
                    "textDocumentSync":{"openClose":true,"change":1,"willSave":false,"willSaveWaitUntil":true,"save":{"includeText":false}},
                    "completionProvider":{"resolveProvider":false,"triggerCharacters":["`"]},
                    "codeActionProvider":{"codeActionKinds":["quickfix","source.fixAll","source.fixAll.rumdl"]},
                    "documentFormattingProvider":true,
                    "documentRangeFormattingProvider":true,
                    "workspace":{"workspaceFolders":{"supported":true,"changeNotifications":true}},
                    "diagnosticProvider":{"identifier":"rumdl","interFileDependencies":true,"workspaceDiagnostics":false}
                },
                "serverInfo":{"name":"rumdl","version":"0.1.13"}
            });
            if let Some(id)=id{ send(server,out,json!({"jsonrpc":"2.0","result":result,"id":id})); }
        },
        "initialized"=>{
            send(server,out,json!({"jsonrpc":"2.0","method":"window/logMessage","params":{"type":3,"message":"rumdl v0.1.13 Language Server started"}}));
            let req_id=server.next_req_id; server.next_req_id+=1;
            send(server,out,json!({"jsonrpc":"2.0","method":"client/registerCapability","params":{"registrations":[{"id":"markdown-watcher","method":"workspace/didChangeWatchedFiles","registerOptions":{"watchers":[{"globPattern":"**/*.md","kind":7},{"globPattern":"**/*.markdown","kind":7},{"globPattern":"**/*.mdx","kind":7},{"globPattern":"**/*.mkd","kind":7},{"globPattern":"**/*.mkdn","kind":7},{"globPattern":"**/*.mdown","kind":7},{"globPattern":"**/*.mdwn","kind":7},{"globPattern":"**/*.qmd","kind":7},{"globPattern":"**/*.rmd","kind":7}]}}]},"id":req_id}));
            // Workspace indexing progress only if workspaceFolders were provided (root_dirs from folders; our root_dirs includes rootUri fallback - original only indexes when workspaceFolders present. We can't distinguish here; use a heuristic: if params had workspaceFolders in initialize, we stored roots but rootUri-only session in badcfg test had only 2 messages (no progress). To replicate, track a flag.)
            if server.root_dirs_from_folders {
                let files=scan_markdown_files(&server.root_dirs);
                let n=files.len();
                let token="rumdl-index";
                let req_id2=server.next_req_id; server.next_req_id+=1;
                send(server,out,json!({"jsonrpc":"2.0","method":"window/workDoneProgress/create","params":{"token":token},"id":req_id2}));
                send(server,out,json!({"jsonrpc":"2.0","method":"$/progress","params":{"token":token,"value":{"kind":"begin","title":"Indexing workspace","cancellable":false,"message":format!("Scanning {n} markdown files..."),"percentage":0}}}));
                send(server,out,json!({"jsonrpc":"2.0","method":"$/progress","params":{"token":token,"value":{"kind":"report","cancellable":false,"message":format!("Indexed {n}/{n} files"),"percentage":100}}}));
                send(server,out,json!({"jsonrpc":"2.0","method":"$/progress","params":{"token":token,"value":{"kind":"end","message":"Indexing complete"}}}));
            }
        },
        "shutdown"=>{
            if msg.get("params").is_some(){
                let p=msg.get("params").unwrap();
                if let Some(id)=id{ send(server,out,json!({"jsonrpc":"2.0","error":{"code":-32602,"message":format!("Unexpected params: {p}")},"id":id})); }
            } else {
                server.shutdown=true;
                if let Some(id)=id{ send(server,out,json!({"jsonrpc":"2.0","result":null,"id":id})); }
            }
        },
        "exit"=>{ /* original doesn't exit until stdin closes; do nothing */ },
        "textDocument/didOpen"=>{
            if let Some(td)=params.as_ref().and_then(|p| p.get("textDocument")){
                let uri=td.get("uri").and_then(|v| v.as_str()).unwrap_or("").to_string();
                let text=td.get("text").and_then(|v| v.as_str()).unwrap_or("").to_string();
                let version=td.get("version").and_then(|v| v.as_i64());
                let lang=td.get("languageId").and_then(|v| v.as_str()).unwrap_or("").to_string();
                server.docs.insert(uri.clone(),Doc{text,version,language_id:lang});
                publish_diagnostics(server,out,&uri);
            }
        },
        "textDocument/didChange"=>{
            if let Some(p)=&params{
                let uri=p.get("textDocument").and_then(|t| t.get("uri")).and_then(|v| v.as_str()).unwrap_or("").to_string();
                let version=p.get("textDocument").and_then(|t| t.get("version")).and_then(|v| v.as_i64());
                if let Some(changes)=p.get("contentChanges").and_then(|v| v.as_array()){
                    if let Some(doc)=server.docs.get_mut(&uri){
                        for ch in changes{
                            if let Some(text)=ch.get("text").and_then(|v| v.as_str()){
                                if let Some(range)=ch.get("range"){
                                    doc.text=apply_range_edit(&doc.text,range,text);
                                } else { doc.text=text.to_string(); }
                            }
                        }
                        doc.version=version;
                    } else if let Some(last)=changes.last(){
                        if let Some(text)=last.get("text").and_then(|v| v.as_str()){ server.docs.insert(uri.clone(),Doc{text:text.to_string(),version,language_id:"markdown".into()}); }
                    }
                }
                if server.docs.contains_key(&uri){ publish_diagnostics(server,out,&uri); }
            }
        },
