            for uri in uris{ publish_diagnostics(server,out,&uri); }
        },
        "workspace/didChangeWatchedFiles"=>{
            // Reload base config if not explicit/no-config and republish all
            let uris:Vec<String>=server.docs.keys().cloned().collect();
            for uri in uris{ publish_diagnostics(server,out,&uri); }
        },
        "workspace/didChangeWorkspaceFolders"=>{
            if let Some(p)=&params{
                if let Some(added)=p.get("event").and_then(|e| e.get("added")).and_then(|v| v.as_array()){ for f in added{ if let Some(uri)=f.get("uri").and_then(|v| v.as_str()){ if let Some(path)=uri_to_path(uri){ if !server.root_dirs.contains(&path){server.root_dirs.push(path);} } } } }
                if let Some(removed)=p.get("event").and_then(|e| e.get("removed")).and_then(|v| v.as_array()){ for f in removed{ if let Some(uri)=f.get("uri").and_then(|v| v.as_str()){ if let Some(path)=uri_to_path(uri){ server.root_dirs.retain(|x| x!=&path); } } } }
            }
        },
        _=>{
            if let Some(id)=id{
                // Requests
                handle_request(server,method,params,id,out);
            } else {
                // Unknown notifications ignored ($/cancelRequest etc)
            }
        }
    }
}

fn handle_request(server:&mut Server, method:&str, params:Option<Value>, id:Value, out:&mut impl Write){
    match method {
        "textDocument/willSaveWaitUntil"=>{
            send(server,out,json!({"jsonrpc":"2.0","result":null,"id":id}));
        },
        "textDocument/formatting"|"textDocument/rangeFormatting"=>{
            let uri=params.as_ref().and_then(|p| p.get("textDocument")).and_then(|t| t.get("uri")).and_then(|v| v.as_str()).unwrap_or("");
            let edits=if let Some(doc)=server.docs.get(uri){
                let formatted=format_document(server,uri,&doc.text);
                if formatted!=doc.text{ vec![json!({"range":{"start":{"line":0,"character":0},"end":end_position(&doc.text)},"newText":formatted})] } else { vec![] }
            } else { vec![] };
            send(server,out,json!({"jsonrpc":"2.0","result":edits,"id":id}));
        },
        "textDocument/diagnostic"=>{
            let uri=params.as_ref().and_then(|p| p.get("textDocument")).and_then(|t| t.get("uri")).and_then(|v| v.as_str()).unwrap_or("");
            let items=diagnostics_for(server,uri);
            send(server,out,json!({"jsonrpc":"2.0","result":{"kind":"full","items":items},"id":id}));
        },
        "textDocument/codeAction"=>{
            let actions=code_actions(server,&params);
            send(server,out,json!({"jsonrpc":"2.0","result":actions,"id":id}));
        },
        "textDocument/completion"=>{
            let items=completion_items(server,&params);
            let result=if items.is_empty(){Value::Null}else{Value::Array(items)};
            send(server,out,json!({"jsonrpc":"2.0","result":result,"id":id}));
        },
        _=>{
            if is_known_request_method(method){
                send(server,out,json!({"jsonrpc":"2.0","error":{"code":-32601,"message":"Method not found"},"id":id}));
            } else if is_known_notification_method(method) {
                send(server,out,json!({"jsonrpc":"2.0","error":{"code":-32600,"message":"Invalid request"},"id":id}));
            } else {
                send(server,out,json!({"jsonrpc":"2.0","error":{"code":-32601,"message":"Method not found","data":method},"id":id}));
            }
        }
    }
}
fn is_known_notification_method(m:&str)->bool{
    matches!(m,"initialized"|"exit"|"$/cancelRequest"|"textDocument/didOpen"|"textDocument/didChange"|"textDocument/didSave"|"textDocument/didClose"|"textDocument/willSave"|"workspace/didChangeConfiguration"|"workspace/didChangeWatchedFiles"|"workspace/didChangeWorkspaceFolders"|"workspace/didCreateFiles"|"workspace/didRenameFiles"|"workspace/didDeleteFiles"|"notebookDocument/didOpen"|"notebookDocument/didChange"|"notebookDocument/didSave"|"notebookDocument/didClose")
}
fn is_known_request_method(m:&str)->bool{
    const KNOWN:&[&str]=&[
        "initialize","shutdown","textDocument/completion","completionItem/resolve","textDocument/hover","textDocument/signatureHelp","textDocument/declaration","textDocument/definition","textDocument/typeDefinition","textDocument/implementation","textDocument/references","textDocument/documentHighlight","textDocument/documentSymbol","textDocument/codeAction","codeAction/resolve","textDocument/codeLens","codeLens/resolve","textDocument/documentLink","documentLink/resolve","textDocument/documentColor","textDocument/colorPresentation","textDocument/formatting","textDocument/rangeFormatting","textDocument/onTypeFormatting","textDocument/rename","textDocument/prepareRename","textDocument/foldingRange","textDocument/selectionRange","textDocument/prepareCallHierarchy","callHierarchy/incomingCalls","callHierarchy/outgoingCalls","textDocument/semanticTokens/full","textDocument/semanticTokens/full/delta","textDocument/semanticTokens/range","textDocument/linkedEditingRange","workspace/symbol","workspaceSymbol/resolve","workspace/executeCommand","workspace/applyEdit","textDocument/moniker","textDocument/prepareTypeHierarchy","typeHierarchy/supertypes","typeHierarchy/subtypes","textDocument/inlineValue","workspace/inlineValue/refresh","textDocument/inlayHint","inlayHint/resolve","workspace/inlayHint/refresh","textDocument/diagnostic","workspace/diagnostic","workspace/diagnostic/refresh","textDocument/documentDiagnostic","notebookDocument/diagnostic","textDocument/willSaveWaitUntil","workspace/workspaceFolders","workspace/configuration","workspace/semanticTokens/refresh","workspace/codeLens/refresh","workspace/applyEdit","workspace/willCreateFiles","workspace/willRenameFiles","workspace/willDeleteFiles","workspace/textDocumentContent","workspace/textDocumentContent/refresh","callHierarchy/prepare","textDocument/prepareCallHierarchy"
    ];
    KNOWN.contains(&m)
}
fn scan_markdown_files(roots:&[PathBuf])->Vec<PathBuf>{
    let mut out=Vec::new();
    for r in roots{
        if r.is_file(){ if crate::check::is_markdown_file_pub(r){out.push(r.clone());} continue; }
        // use ignore walker like CLI
        let mut builder=ignore::WalkBuilder::new(r); builder.hidden(false).follow_links(false).git_ignore(true).git_global(true).git_exclude(true).ignore(true).parents(true).require_git(false);
        for e in builder.build().flatten(){ if e.file_type().map(|t| t.is_file()).unwrap_or(false){ let p=e.path().to_path_buf(); if crate::check::is_markdown_file_pub(&p){out.push(p);} } }
    }
    out.sort(); out.dedup(); out
}
fn effective_config_for_doc(server:&Server, uri:&str)->(Config, Vec<&RuleInfo>, Flavor, Option<PathBuf>){
    let path=uri_to_path(uri);
    let mut cfg:Config;
    if server.explicit_path.is_some(){
        cfg=server.base_cfg.clone();
    } else if server.base_global.no_config {
        cfg=Config::default();
    } else if let Some(p)=&path {
        let start=p.parent().unwrap_or(Path::new("."));
        cfg=crate::config::load_resolved(&server.base_global,start,true).unwrap_or_default();
    } else {
        cfg=server.base_cfg.clone();
    }
    if let Some(sc)=&server.settings_cfg{
        // settings_cfg is already base+settings applied at change time based on server.base_cfg - but per-file config should be base for settings: re-apply stored settings raw is not kept; we stored a cfg derived from base_cfg in apply at didChange time (see handling) - for per-file, use settings_cfg directly as original likely has one global config from settings overriding file configs? Test indicated per-file configs work without settings; with settings, settings likely merge over per-file. Our stored settings_cfg was applied to base_cfg (cwd) not per-file. To approximate, if settings were ever set, use that cfg (it will be refreshed on next didChangeConfiguration).
        cfg=sc.clone();
    }
    // flavor & enabled
    let flavor={
        let mut fl=cfg.global.flavor;
        if !cfg.global_explicit.contains("flavor"){
            if let Some(p)=&path{ if let Some(f)=Flavor::from_filename(&p.to_string_lossy()){fl=f;} }
        }
        // per-file flavor patterns using path relative to project root (use display-like)
        if let Some(p)=&path{
            let disp=path.to_string();
            let mut best:Option<String>=None;
            // Use cfg per-file flavor in order first match vs path string / file name
            for (pat,flv) in &cfg.per_file_flavor{ if crate::globmatch::cross_matches(pat,&disp){fl=*flv;break;} }
            let _=best;
        }
        fl
    };
    let enabled_all:Vec<&RuleInfo>=RULES.iter().collect();
    // Reuse check compute_enabled with a default CheckArgs (no CLI filters)
    let enabled={
        // Build a minimal CheckArgs via parsing? Use compute_enabled logic by constructing through a helper: we replicate by using check module's function with a default args struct constructed via a fake matches is hard.
        // Instead, implement inline: if cfg.global.enable non-empty select those, else all except disable.
        let mut set:std::collections::HashSet<String>=std::collections::HashSet::new();
        if !cfg.global.enable.is_empty(){ for s in &cfg.global.enable{ if let Some(info)=resolve_rule(s){set.insert(info.code.into());} } }
        else { for r in &enabled_all{set.insert(r.code.into());} for s in &cfg.global.disable{ if let Some(info)=resolve_rule(s){set.remove(info.code);} } }
