}
fn range_pos(range:&Value)->(usize,usize,usize,usize){
    let g=|k:&str,kk:&str| range.get(k).and_then(|v| v.get(kk)).and_then(|v| v.as_u64()).unwrap_or(0) as usize;
    (g("start","line"),g("start","character"),g("end","line"),g("end","character"))
}
pub fn byte_range_to_lsp_range(text:&str,start:usize,end:usize)->(Value,Value){
    (byte_to_pos(text,start),byte_to_pos(text,end))
}
fn byte_to_pos(text:&str,byte:usize)->Value{
    let mut line=0; let mut ch=0; let mut cur=0;
    for c in text.chars(){ if cur>=byte{break;} if c=='\n'{line+=1;ch=0;}else{ch+=1;} cur+=c.len_utf8(); }
    json!({"line":line,"character":ch})
}
fn apply_range_edit(text:&str,range:&Value,new_text:&str)->String{
    let (sl,sc,el,ec)=range_pos(range);
    let start=pos_to_byte(text,sl,sc); let end=pos_to_byte(text,el,ec);
    let mut out=text.to_string(); if start<=end&&end<=out.len()&&out.is_char_boundary(start)&&out.is_char_boundary(end){out.replace_range(start..end,new_text);} out
}
fn pos_to_byte(text:&str,line:usize,ch:usize)->usize{
    let mut cur_line=0; let mut cur_ch=0; let mut idx=0;
    for c in text.chars(){ if cur_line==line&&cur_ch==ch{return idx;} if c=='\n'{cur_line+=1;cur_ch=0;}else{cur_ch+=1;} idx+=c.len_utf8(); if cur_line>line{break;} }
    idx
}
fn completion_items(server:&Server,params:&Option<Value>)->Vec<Value>{
    let Some(p)=params else{return vec![];};
    let uri=p.get("textDocument").and_then(|t| t.get("uri")).and_then(|v| v.as_str()).unwrap_or("");
    let Some(doc)=server.docs.get(uri) else{return vec![];};
    let pos=p.get("position").cloned().unwrap_or(json!({}));
    let line_no=pos.get("line").and_then(|v| v.as_u64()).unwrap_or(0) as usize;
    let character=pos.get("character").and_then(|v| v.as_u64()).unwrap_or(0) as usize;
    let lines:Vec<&str>=doc.text.lines().collect();
    let Some(line)=lines.get(line_no) else{return vec![];};
    // Must be on a fence opening line, cursor after fence run
    let stripped=crate::lint::strip_blockquote_prefix(line);
    let Some((_indent,_fc,fence_len,_info))=crate::lint::parse_fence_line(stripped) else{return vec![];};
    // Check this line is an opening fence in context (not closing) - use LintContext code_blocks starts
    let ctx=LintContext::new(&doc.text,Flavor::Standard,None);
    if !ctx.code_blocks.iter().any(|cb| cb.start_line==line_no){return vec![];}
    // Prefix is text after fence run up to cursor (chars)
    let line_chars:Vec<char>=line.chars().collect();
    // Find fence start char index in original line
    let fence_start=line.find(|c| c=='`'||c=='~').map(|b| line[..b].chars().count()).unwrap_or(0);
    if character < fence_start+fence_len{return vec![];}
    let prefix:String=line_chars.iter().skip(fence_start+fence_len).take(character.saturating_sub(fence_start+fence_len)).collect();
    // If prefix contains whitespace, only complete first token
    if prefix.contains(|c:char| c.is_whitespace()){return vec![];}
    // Range replaced is from after fence to end of existing label token
    let mut label_end=character; while label_end<line_chars.len()&&!line_chars[label_end].is_whitespace(){label_end+=1;}
    let (cfg,_,_,_)=effective_config_for_doc(server,uri);
    let allowed=cfg.rules.get("MD040").and_then(|m| m.get("allowed-languages")).and_then(|v| if let toml::Value::Array(a)=v{Some(a.iter().filter_map(|x| if let toml::Value::String(s)=x{Some(s.clone())}else{None}).collect::<Vec<_>>())}else{None}).unwrap_or_default();
    let disallowed=cfg.rules.get("MD040").and_then(|m| m.get("disallowed-languages")).and_then(|v| if let toml::Value::Array(a)=v{Some(a.iter().filter_map(|x| if let toml::Value::String(s)=x{Some(s.clone())}else{None}).collect::<Vec<_>>())}else{None}).unwrap_or_default();
    let preferred=cfg.rule_tables.get("MD040").and_then(|m| m.get("preferred-aliases"));
    let mut pref_map:std::collections::HashMap<String,String>=std::collections::HashMap::new();
    if let Some(toml::Value::Table(t))=preferred{ for (k,v) in t{ if let toml::Value::String(s)=v{pref_map.insert(k.to_ascii_lowercase(),s.clone());} } }
    let mut items:Vec<Value>=Vec::new();
    let prefix_lower=prefix.to_ascii_lowercase();
    for (canon,aliases) in crate::lang::LANGUAGES{
        if !allowed.is_empty() && !allowed.iter().any(|a| { let ac=crate::lang::canonical_language(a).unwrap_or(a.clone()); ac.eq_ignore_ascii_case(canon) }){continue;}
        if !disallowed.is_empty() && disallowed.iter().any(|a| { let ac=crate::lang::canonical_language(a).unwrap_or(a.clone()); ac.eq_ignore_ascii_case(canon) }){continue;}
        let mut labels:Vec<(String,bool)>=Vec::new();
        labels.push((canon.to_string(),true));
        // Preferred alias first? Original gives each alias as separate item; preferred aliases may change ordering/sort - ignore ordering for now, include preferred value if not in aliases
        for a in *aliases{ if !labels.iter().any(|(l,_)| l==a){labels.push((a.to_string(),false));} }
        if let Some(pref)=pref_map.get(&canon.to_ascii_lowercase()){ if !labels.iter().any(|(l,_)| l==pref){labels.push((pref.clone(),false));} }
        for (label,is_canon) in labels{
            if !prefix_lower.is_empty() && !label.to_ascii_lowercase().starts_with(&prefix_lower){continue;}
            let sort_prefix=if is_canon{"0"}else{"1"};
            items.push(json!({"label":label,"kind":12,"detail":format!("{canon} (GitHub Linguist)"),"sortText":format!("{sort_prefix}{label}"),"filterText":label,"insertText":label,"textEdit":{"range":{"start":{"line":line_no,"character":fence_start+fence_len},"end":{"line":line_no,"character":label_end}},"newText":label}}));
            if items.len()>=100 && !prefix_lower.is_empty(){ /* original limits to 100 only for empty prefix? It took 100 from map iteration - if prefix filtering it also limits maybe */}
        }
        if prefix_lower.is_empty()&&items.len()>=100{break;}
    }
    if prefix_lower.is_empty(){items.truncate(100);}
    items
}
fn apply_settings(base:&Config, settings:&Value)->(Config,Vec<String>){
    let mut cfg=base.clone(); let mut warns=Vec::new();
    let obj=match settings{ Value::Object(m)=>{ if let Some(r)=m.get("rumdl"){ if let Value::Object(rm)=r{rm.clone()}else{return (cfg,warns);} } else {m.clone()} }, _=>return (cfg,warns) };
    for (k,v) in obj{
        if k=="enable"||k=="disable"{
            if let Value::Array(a)=&v{
                if a.iter().all(|x| x.is_string()){
                    let list:Vec<String>=a.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect();
                    // validate unknown rules? Settings warning probes for unknown list entries unknown yet
                    if k=="enable"{cfg.global.enable=list; cfg.global_explicit.insert("enable".into());}else{cfg.global.disable=list; cfg.global_explicit.insert("disable".into());}
                } else { warns.push(format!("rumdl: Invalid '{k}' value: expected array of strings, got {v}")); }
            } else { warns.push(format!("rumdl: Invalid '{k}' value: expected array of strings, got {v}")); }
        } else if let Some(info)=resolve_rule(&k){
            if let Value::Object(entries)=v{
                cfg.rule_sections.insert(info.code.into());
                let m=cfg.rules.entry(info.code.into()).or_default();
                for (ek,ev) in entries{
                    let nk=norm_key(&ek);
                    if nk=="severity"{ if let Value::String(s)=&ev{ if let Some(sev)=Severity::parse(s){cfg.severities.insert(info.code.into(),sev);} } continue; }
                    if let Some(tv)=crate::import_convert::json_to_toml(&ev){ if let toml::Value::Table(_)=tv{cfg.rule_tables.entry(info.code.into()).or_default().insert(nk,tv);}else{m.insert(nk,tv);} }
                }
            } else {
                warns.push(format!("rumdl: Invalid '{k}' value: expected object, got {v}"));
            }
        } else {
            warns.push(format!("rumdl: Unknown rule in settings: {k}"));
        }
    }
    (cfg,warns)
}
