            send(server,out,json!({"jsonrpc":"2.0","method":"window/logMessage","params":{"type":3,"message":"rumdl v0.1.13 Language Server started"}}));
            let req_id=server.next_req_id; server.next_req_id+=1;
            send(server,out,json!({"jsonrpc":"2.0","method":"client/registerCapability","params":{"registrations":[{"id":"markdown-watcher","method":"workspace/didChangeWatchedFiles","registerOptions":{"watchers":[{"globPattern":"**/*.md","kind":7},{"globPattern":"**/*.markdown","kind":7},{"globPattern":"**/*.mdx","kind":7},{"globPattern":"**/*.mkd","kind":7},{"globPattern":"**/*.mkdn","kind":7},{"globPattern":"**/*.mdown","kind":7},{"globPattern":"**/*.mdwn","kind":7},{"globPattern":"**/*.qmd","kind":7},{"globPattern":"**/*.rmd","kind":7}]}}]},"id":req_id}));
            // Workspace indexing progress only if workspaceFolders were provided (root_dirs from folders; our root_dirs includes rootUri fallback - original only indexes when workspaceFolders present. We can't distinguish here; use a heuristic: if params had workspaceFolders in initialize, we stored roots but rootUri-only session in badcfg test had only 2 messages (no progress). To replicate, track a flag.)
            if server.root_dirs_from_folders {
                let files=scan_markdown_files(&server.root_dirs);
                let n=files.len();
                let token="rumdl-index";
                let req_id2=server.next_req_id; server.next_req_id+=1;
                send(server,out,json!({"jsonrpc":"2.0","method":"window/workDoneProgress/create","params":{"token":token},"id":req_id2}));
                send(server,out,json!({"jsonrpc":"2.0","method":"$/progress","params":{"token":token,"value":{"kind":"begin","title":"Indexing workspace","cancellable":false,"message":format!("Scanning {n} markdown files..."),"percentage":0}}}));
                send(server,out,json!({"jsonrpc":"2.0","method":"$/progress","params":{"token":token,"value":{"kind":"report","cancellable":false,"message":format!("Indexed {n}/{n} files"),"percentage":100}}}));
                send(server,out,json!({"jsonrpc":"2.0","method":"$/progress","params":{"token":token,"value":{"kind":"end","message":"Indexing complete"}}}));
            }
        },
        "shutdown"=>{
            if msg.get("params").is_some(){
                let p=msg.get("params").unwrap();
                if let Some(id)=id{ send(server,out,json!({"jsonrpc":"2.0","error":{"code":-32602,"message":format!("Unexpected params: {p}")},"id":id})); }
            } else {
                server.shutdown=true;
                if let Some(id)=id{ send(server,out,json!({"jsonrpc":"2.0","result":null,"id":id})); }
            }
        },
        "exit"=>{ /* original doesn't exit until stdin closes; do nothing */ },
        "textDocument/didOpen"=>{
            if let Some(td)=params.as_ref().and_then(|p| p.get("textDocument")){
                let uri=td.get("uri").and_then(|v| v.as_str()).unwrap_or("").to_string();
                let text=td.get("text").and_then(|v| v.as_str()).unwrap_or("").to_string();
                let version=td.get("version").and_then(|v| v.as_i64());
                let lang=td.get("languageId").and_then(|v| v.as_str()).unwrap_or("").to_string();
                server.docs.insert(uri.clone(),Doc{text,version,language_id:lang});
                publish_diagnostics(server,out,&uri);
            }
        },
        "textDocument/didChange"=>{
            if let Some(p)=&params{
                let uri=p.get("textDocument").and_then(|t| t.get("uri")).and_then(|v| v.as_str()).unwrap_or("").to_string();
                let version=p.get("textDocument").and_then(|t| t.get("version")).and_then(|v| v.as_i64());
                if let Some(changes)=p.get("contentChanges").and_then(|v| v.as_array()){
                    if let Some(doc)=server.docs.get_mut(&uri){
                        for ch in changes{
                            if let Some(text)=ch.get("text").and_then(|v| v.as_str()){
                                if let Some(range)=ch.get("range"){
                                    doc.text=apply_range_edit(&doc.text,range,text);
                                } else { doc.text=text.to_string(); }
                            }
                        }
                        doc.version=version;
                    } else if let Some(last)=changes.last(){
                        if let Some(text)=last.get("text").and_then(|v| v.as_str()){ server.docs.insert(uri.clone(),Doc{text:text.to_string(),version,language_id:"markdown".into()}); }
                    }
                }
                if server.docs.contains_key(&uri){ publish_diagnostics(server,out,&uri); }
            }
        },
        "textDocument/didSave"=>{
            if let Some(p)=&params{ let uri=p.get("textDocument").and_then(|t| t.get("uri")).and_then(|v| v.as_str()).unwrap_or("").to_string(); if server.docs.contains_key(&uri){ publish_diagnostics(server,out,&uri); } }
        },
        "textDocument/didClose"=>{
            if let Some(p)=&params{ let uri=p.get("textDocument").and_then(|t| t.get("uri")).and_then(|v| v.as_str()).unwrap_or("").to_string(); server.docs.remove(&uri); send(server,out,json!({"jsonrpc":"2.0","method":"textDocument/publishDiagnostics","params":{"uri":uri,"diagnostics":[]}})); }
        },
        "textDocument/willSave"=>{ /* notification */ },
        "workspace/didChangeConfiguration"=>{
            let settings=params.as_ref().and_then(|p| p.get("settings")).cloned().unwrap_or(Value::Null);
            let (cfg,warns)=apply_settings(&server.base_cfg,&settings);
            server.settings_cfg=Some(cfg); server.settings_warnings=warns.clone();
            for w in warns{ send(server,out,json!({"jsonrpc":"2.0","method":"window/logMessage","params":{"type":2,"message":w}})); }
            let uris:Vec<String>=server.docs.keys().cloned().collect();
            for uri in uris{ publish_diagnostics(server,out,&uri); }
        },
        "workspace/didChangeWatchedFiles"=>{
            // Reload base config if not explicit/no-config and republish all
            let uris:Vec<String>=server.docs.keys().cloned().collect();
            for uri in uris{ publish_diagnostics(server,out,&uri); }
        },
        "workspace/didChangeWorkspaceFolders"=>{
            if let Some(p)=&params{
                if let Some(added)=p.get("event").and_then(|e| e.get("added")).and_then(|v| v.as_array()){ for f in added{ if let Some(uri)=f.get("uri").and_then(|v| v.as_str()){ if let Some(path)=uri_to_path(uri){ if !server.root_dirs.contains(&path){server.root_dirs.push(path);} } } } }
                if let Some(removed)=p.get("event").and_then(|e| e.get("removed")).and_then(|v| v.as_array()){ for f in removed{ if let Some(uri)=f.get("uri").and_then(|v| v.as_str()){ if let Some(path)=uri_to_path(uri){ server.root_dirs.retain(|x| x!=&path); } } } }
            }
        },
        _=>{
            if let Some(id)=id{
                // Requests
                handle_request(server,method,params,id,out);
            } else {
                // Unknown notifications ignored ($/cancelRequest etc)
            }
        }
    }
}

fn handle_request(server:&mut Server, method:&str, params:Option<Value>, id:Value, out:&mut impl Write){
    match method {
        "textDocument/willSaveWaitUntil"=>{
            send(server,out,json!({"jsonrpc":"2.0","result":null,"id":id}));
        },
        "textDocument/formatting"|"textDocument/rangeFormatting"=>{
            let uri=params.as_ref().and_then(|p| p.get("textDocument")).and_then(|t| t.get("uri")).and_then(|v| v.as_str()).unwrap_or("");
            let edits=if let Some(doc)=server.docs.get(uri){
                let formatted=format_document(server,uri,&doc.text);
                if formatted!=doc.text{ vec![json!({"range":{"start":{"line":0,"character":0},"end":end_position(&doc.text)},"newText":formatted})] } else { vec![] }
            } else { vec![] };
            send(server,out,json!({"jsonrpc":"2.0","result":edits,"id":id}));
        },
        "textDocument/diagnostic"=>{
            let uri=params.as_ref().and_then(|p| p.get("textDocument")).and_then(|t| t.get("uri")).and_then(|v| v.as_str()).unwrap_or("");
            let items=diagnostics_for(server,uri);
            send(server,out,json!({"jsonrpc":"2.0","result":{"kind":"full","items":items},"id":id}));
        },
        "textDocument/codeAction"=>{
            let actions=code_actions(server,&params);
            send(server,out,json!({"jsonrpc":"2.0","result":actions,"id":id}));
        },
        "textDocument/completion"=>{
            let items=completion_items(server,&params);
            let result=if items.is_empty(){Value::Null}else{Value::Array(items)};
            send(server,out,json!({"jsonrpc":"2.0","result":result,"id":id}));
        },
        _=>{
            if is_known_request_method(method){
                send(server,out,json!({"jsonrpc":"2.0","error":{"code":-32601,"message":"Method not found"},"id":id}));
            } else if is_known_notification_method(method) {
                send(server,out,json!({"jsonrpc":"2.0","error":{"code":-32600,"message":"Invalid request"},"id":id}));
            } else {
                send(server,out,json!({"jsonrpc":"2.0","error":{"code":-32601,"message":"Method not found","data":method},"id":id}));
            }
        }
    }
}
fn is_known_notification_method(m:&str)->bool{
    matches!(m,"initialized"|"exit"|"$/cancelRequest"|"textDocument/didOpen"|"textDocument/didChange"|"textDocument/didSave"|"textDocument/didClose"|"textDocument/willSave"|"workspace/didChangeConfiguration"|"workspace/didChangeWatchedFiles"|"workspace/didChangeWorkspaceFolders"|"workspace/didCreateFiles"|"workspace/didRenameFiles"|"workspace/didDeleteFiles"|"notebookDocument/didOpen"|"notebookDocument/didChange"|"notebookDocument/didSave"|"notebookDocument/didClose")
}
fn is_known_request_method(m:&str)->bool{
    const KNOWN:&[&str]=&[
        "initialize","shutdown","textDocument/completion","completionItem/resolve","textDocument/hover","textDocument/signatureHelp","textDocument/declaration","textDocument/definition","textDocument/typeDefinition","textDocument/implementation","textDocument/references","textDocument/documentHighlight","textDocument/documentSymbol","textDocument/codeAction","codeAction/resolve","textDocument/codeLens","codeLens/resolve","textDocument/documentLink","documentLink/resolve","textDocument/documentColor","textDocument/colorPresentation","textDocument/formatting","textDocument/rangeFormatting","textDocument/onTypeFormatting","textDocument/rename","textDocument/prepareRename","textDocument/foldingRange","textDocument/selectionRange","textDocument/prepareCallHierarchy","callHierarchy/incomingCalls","callHierarchy/outgoingCalls","textDocument/semanticTokens/full","textDocument/semanticTokens/full/delta","textDocument/semanticTokens/range","textDocument/linkedEditingRange","workspace/symbol","workspaceSymbol/resolve","workspace/executeCommand","workspace/applyEdit","textDocument/moniker","textDocument/prepareTypeHierarchy","typeHierarchy/supertypes","typeHierarchy/subtypes","textDocument/inlineValue","workspace/inlineValue/refresh","textDocument/inlayHint","inlayHint/resolve","workspace/inlayHint/refresh","textDocument/diagnostic","workspace/diagnostic","workspace/diagnostic/refresh","textDocument/documentDiagnostic","notebookDocument/diagnostic","textDocument/willSaveWaitUntil","workspace/workspaceFolders","workspace/configuration","workspace/semanticTokens/refresh","workspace/codeLens/refresh","workspace/applyEdit","workspace/willCreateFiles","workspace/willRenameFiles","workspace/willDeleteFiles","workspace/textDocumentContent","workspace/textDocumentContent/refresh","callHierarchy/prepare","textDocument/prepareCallHierarchy"
    ];
    KNOWN.contains(&m)
}
fn scan_markdown_files(roots:&[PathBuf])->Vec<PathBuf>{
    let mut out=Vec::new();
    for r in roots{
        if r.is_file(){ if crate::check::is_markdown_file_pub(r){out.push(r.clone());} continue; }
        // use ignore walker like CLI
        let mut builder=ignore::WalkBuilder::new(r); builder.hidden(false).follow_links(false).git_ignore(true).git_global(true).git_exclude(true).ignore(true).parents(true).require_git(false);
        for e in builder.build().flatten(){ if e.file_type().map(|t| t.is_file()).unwrap_or(false){ let p=e.path().to_path_buf(); if crate::check::is_markdown_file_pub(&p){out.push(p);} } }
    }
    out.sort(); out.dedup(); out
}
fn effective_config_for_doc(server:&Server, uri:&str)->(Config, Vec<&RuleInfo>, Flavor, Option<PathBuf>){
    let path=uri_to_path(uri);
    let mut cfg:Config;
    if server.explicit_path.is_some(){
        cfg=server.base_cfg.clone();
    } else if server.base_global.no_config {
        cfg=Config::default();
    } else if let Some(p)=&path {
        let start=p.parent().unwrap_or(Path::new("."));
        cfg=crate::config::load_resolved(&server.base_global,start,true).unwrap_or_default();
    } else {
        cfg=server.base_cfg.clone();
    }
    if let Some(sc)=&server.settings_cfg{
        // settings_cfg is already base+settings applied at change time based on server.base_cfg - but per-file config should be base for settings: re-apply stored settings raw is not kept; we stored a cfg derived from base_cfg in apply at didChange time (see handling) - for per-file, use settings_cfg directly as original likely has one global config from settings overriding file configs? Test indicated per-file configs work without settings; with settings, settings likely merge over per-file. Our stored settings_cfg was applied to base_cfg (cwd) not per-file. To approximate, if settings were ever set, use that cfg (it will be refreshed on next didChangeConfiguration).
        cfg=sc.clone();
    }
    // flavor & enabled
    let flavor={
        let mut fl=cfg.global.flavor;
        if !cfg.global_explicit.contains("flavor"){
            if let Some(p)=&path{ if let Some(f)=Flavor::from_filename(&p.to_string_lossy()){fl=f;} }
        }
        // per-file flavor patterns using path relative to project root (use display-like)
        if let Some(p)=&path{
            let disp=path.to_string();
            let mut best:Option<String>=None;
            // Use cfg per-file flavor in order first match vs path string / file name
            for (pat,flv) in &cfg.per_file_flavor{ if crate::globmatch::cross_matches(pat,&disp){fl=*flv;break;} }
            let _=best;
        }
        fl
    };
    let enabled_all:Vec<&RuleInfo>=RULES.iter().collect();
    // Reuse check compute_enabled with a default CheckArgs (no CLI filters)
    let enabled={
        // Build a minimal CheckArgs via parsing? Use compute_enabled logic by constructing through a helper: we replicate by using check module's function with a default args struct constructed via a fake matches is hard.
        // Instead, implement inline: if cfg.global.enable non-empty select those, else all except disable.
        let mut set:std::collections::HashSet<String>=std::collections::HashSet::new();
        if !cfg.global.enable.is_empty(){ for s in &cfg.global.enable{ if let Some(info)=resolve_rule(s){set.insert(info.code.into());} } }
        else { for r in &enabled_all{set.insert(r.code.into());} for s in &cfg.global.disable{ if let Some(info)=resolve_rule(s){set.remove(info.code);} } }
        enabled_all.into_iter().filter(|r| set.contains(r.code)).collect()
    };
    (cfg,enabled,flavor,path)
}
fn diagnostics_for(server:&Server, uri:&str)->Vec<Value>{
    let Some(doc)=server.docs.get(uri) else{return vec![];};
    let warnings=lint_doc(server,uri,&doc.text);
    warnings.iter().map(|w| warning_to_diag(w)).collect()
}
fn lint_doc(server:&Server, uri:&str, text:&str)->Vec<LintWarning>{
    let (cfg,enabled,flavor,path)=effective_config_for_doc(server,uri);
    // Unsorted version for LSP diagnostics order (rule order) - use lint_content_unsorted if available
    crate::rules::lint_content_unsorted(text,&cfg,&enabled,flavor,path)
}
fn warning_to_diag(w:&LintWarning)->Value{
    json!({
        "range":{"start":{"line":w.line-1,"character":w.column-1},"end":{"line":w.end_line-1,"character":w.end_column-1}},
        "severity":match w.severity{Severity::Error=>1,Severity::Warning=>2,Severity::Info=>3},
        "code":w.rule_name,
        "codeDescription":{"href":format!("https://rumdl.dev/{}/",w.rule_name.to_ascii_lowercase())},
        "source":"rumdl",
        "message":w.message
    })
}
fn publish_diagnostics(server:&mut Server,out:&mut impl Write,uri:&str){
    let version=server.docs.get(uri).and_then(|d| d.version);
    let diags=diagnostics_for(server,uri);
    let mut params=json!({"uri":uri,"diagnostics":diags});
    if let Some(v)=version{params["version"]=json!(v);}
    send(server,out,json!({"jsonrpc":"2.0","method":"textDocument/publishDiagnostics","params":params}));
}
fn end_position(text:&str)->Value{
    let mut line=0usize; let mut ch=0usize;
    for c in text.chars(){ if c=='\n'{line+=1;ch=0;}else{ch+=1;} }
    json!({"line":line,"character":ch})
}
fn format_document(server:&Server, uri:&str, text:&str)->String{
    let (cfg,enabled,flavor,path)=effective_config_for_doc(server,uri);
    let (fixed,_)=crate::fix::apply_fixes(text,&cfg,&enabled,flavor,path);
    fixed
}
fn code_actions(server:&Server, params:&Option<Value>)->Vec<Value>{
    let Some(p)=params else{return vec![];};
    let uri=p.get("textDocument").and_then(|t| t.get("uri")).and_then(|v| v.as_str()).unwrap_or("");
    let Some(doc)=server.docs.get(uri) else{return vec![];};
    let range=p.get("range").cloned().unwrap_or(json!({}));
    let only:Vec<String>=p.get("context").and_then(|c| c.get("only")).and_then(|v| v.as_array()).map(|a| a.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect()).unwrap_or_default();
    let warnings=lint_doc(server,uri,&doc.text.clone());
    let mut actions:Vec<Value>=Vec::new();
    let in_range=|w:&LintWarning|->bool{
        let (sl,sc,el,ec)=range_pos(&range);
        let (ws,we)=((w.line-1,w.column-1),(w.end_line-1,w.end_column-1));
        // intersect or containment: start <= warning end and end >= warning start (lexicographic)
        (sl,sc) <= we && (el,ec) >= ws
    };
    let relevant:Vec<&LintWarning>=warnings.iter().filter(|w| in_range(w)).collect();
    let want_fixall=only.is_empty()||only.iter().any(|k| k=="source.fixAll"||k=="source.fixAll.rumdl"||k=="source");
    let want_quickfix=only.is_empty()||only.iter().any(|k| k=="quickfix");
    // Original: FixAll offered when range covers at least 2 fixable diagnostics? In probe with range covering whole doc and 2 diags it offered. With a point range and 1 relevant diag, no FixAll.
    let fixable_relevant=relevant.iter().filter(|w| w.fix.is_some()).count();
    if want_fixall && relevant.len()>=2 {
        let total_fixable=warnings.iter().filter(|w| w.fix.is_some()).count();
        // But is total based on relevant or all? In probe all docs relevant = all. Use relevant count as in title if context range filtered - original title says (2 fixable) matching relevant.
        let formatted=format_document(server,uri,&doc.text);
        if formatted!=doc.text{
            actions.push(json!({"title":format!("Fix all rumdl issues ({} fixable)",fixable_relevant),"kind":"source.fixAll.rumdl","diagnostics":[],"edit":{"changes":{uri:[{"range":{"start":{"line":0,"character":0},"end":end_position(&doc.text)},"newText":formatted}]}},"isPreferred":true}));
            let _=total_fixable;
        }
    }
    if want_quickfix{
        for w in relevant{
            let diag=warning_to_diag(w);
            if let Some(fix)=&w.fix{
                let (s,e)=byte_range_to_lsp_range(&doc.text,fix.range.start,fix.range.end);
                actions.push(json!({"title":format!("Fix: {}",w.message),"kind":"quickfix","diagnostics":[diag.clone()],"edit":{"changes":{uri:[{"range":{"start":s,"end":e},"newText":fix.replacement}]}},"isPreferred":true}));
            }
            // Ignore action: insert at end of warning line
            let lines:Vec<&str>=doc.text.lines().collect();
            let line_len=lines.get(w.line-1).map(|l| l.chars().count()).unwrap_or(0);
            actions.push(json!({"title":format!("Ignore {} for this line",w.rule_name),"kind":"quickfix","diagnostics":[diag],"edit":{"changes":{uri:[{"range":{"start":{"line":w.line-1,"character":line_len},"end":{"line":w.line-1,"character":line_len}},"newText":format!(" <!-- rumdl-disable-line {} -->",w.rule_name)}]}},"isPreferred":false}));
        }
    }
    actions
}
fn range_pos(range:&Value)->(usize,usize,usize,usize){
    let g=|k:&str,kk:&str| range.get(k).and_then(|v| v.get(kk)).and_then(|v| v.as_u64()).unwrap_or(0) as usize;
    (g("start","line"),g("start","character"),g("end","line"),g("end","character"))
}
pub fn byte_range_to_lsp_range(text:&str,start:usize,end:usize)->(Value,Value){
    (byte_to_pos(text,start),byte_to_pos(text,end))
}
fn byte_to_pos(text:&str,byte:usize)->Value{
    let mut line=0; let mut ch=0; let mut cur=0;
    for c in text.chars(){ if cur>=byte{break;} if c=='\n'{line+=1;ch=0;}else{ch+=1;} cur+=c.len_utf8(); }
    json!({"line":line,"character":ch})
}
fn apply_range_edit(text:&str,range:&Value,new_text:&str)->String{
    let (sl,sc,el,ec)=range_pos(range);
    let start=pos_to_byte(text,sl,sc); let end=pos_to_byte(text,el,ec);
    let mut out=text.to_string(); if start<=end&&end<=out.len()&&out.is_char_boundary(start)&&out.is_char_boundary(end){out.replace_range(start..end,new_text);} out
}
fn pos_to_byte(text:&str,line:usize,ch:usize)->usize{
    let mut cur_line=0; let mut cur_ch=0; let mut idx=0;
    for c in text.chars(){ if cur_line==line&&cur_ch==ch{return idx;} if c=='\n'{cur_line+=1;cur_ch=0;}else{cur_ch+=1;} idx+=c.len_utf8(); if cur_line>line{break;} }
    idx
}
fn completion_items(server:&Server,params:&Option<Value>)->Vec<Value>{
    let Some(p)=params else{return vec![];};
    let uri=p.get("textDocument").and_then(|t| t.get("uri")).and_then(|v| v.as_str()).unwrap_or("");
    let Some(doc)=server.docs.get(uri) else{return vec![];};
    let pos=p.get("position").cloned().unwrap_or(json!({}));
    let line_no=pos.get("line").and_then(|v| v.as_u64()).unwrap_or(0) as usize;
    let character=pos.get("character").and_then(|v| v.as_u64()).unwrap_or(0) as usize;
    let lines:Vec<&str>=doc.text.lines().collect();
    let Some(line)=lines.get(line_no) else{return vec![];};
    // Must be on a fence opening line, cursor after fence run
    let stripped=crate::lint::strip_blockquote_prefix(line);
    let Some((_indent,_fc,fence_len,_info))=crate::lint::parse_fence_line(stripped) else{return vec![];};
    // Check this line is an opening fence in context (not closing) - use LintContext code_blocks starts
    let ctx=LintContext::new(&doc.text,Flavor::Standard,None);
    if !ctx.code_blocks.iter().any(|cb| cb.start_line==line_no){return vec![];}
    // Prefix is text after fence run up to cursor (chars)
    let line_chars:Vec<char>=line.chars().collect();
    // Find fence start char index in original line
    let fence_start=line.find(|c| c=='`'||c=='~').map(|b| line[..b].chars().count()).unwrap_or(0);
    if character < fence_start+fence_len{return vec![];}
    let prefix:String=line_chars.iter().skip(fence_start+fence_len).take(character.saturating_sub(fence_start+fence_len)).collect();
    // If prefix contains whitespace, only complete first token
    if prefix.contains(|c:char| c.is_whitespace()){return vec![];}
    // Range replaced is from after fence to end of existing label token
    let mut label_end=character; while label_end<line_chars.len()&&!line_chars[label_end].is_whitespace(){label_end+=1;}
    let (cfg,_,_,_)=effective_config_for_doc(server,uri);
    let allowed=cfg.rules.get("MD040").and_then(|m| m.get("allowed-languages")).and_then(|v| if let toml::Value::Array(a)=v{Some(a.iter().filter_map(|x| if let toml::Value::String(s)=x{Some(s.clone())}else{None}).collect::<Vec<_>>())}else{None}).unwrap_or_default();
    let disallowed=cfg.rules.get("MD040").and_then(|m| m.get("disallowed-languages")).and_then(|v| if let toml::Value::Array(a)=v{Some(a.iter().filter_map(|x| if let toml::Value::String(s)=x{Some(s.clone())}else{None}).collect::<Vec<_>>())}else{None}).unwrap_or_default();
    let preferred=cfg.rule_tables.get("MD040").and_then(|m| m.get("preferred-aliases"));
    let mut pref_map:std::collections::HashMap<String,String>=std::collections::HashMap::new();
