pub fn split_sentences(text:&str, custom_abbr:&[String])->Vec<String>{
    let mut abbr:HashSet<String>=["mr","mrs","ms","dr","prof","sr","jr","st","vs","etc","i.e","e.g","inc","ltd","corp","jan","feb","mar","apr","jun","jul","aug","sep","sept","oct","nov","dec","u.s","u.k","u.s.a","ph.d","m.d","b.a","m.a"].iter().map(|s| s.to_string()).collect();
