            while end<chars.len()&&"\")]}'\"".contains(chars[end]){end+=1;}
            // next non-space char
            let mut nxt=end; while nxt<chars.len()&&chars[nxt].is_whitespace(){nxt+=1;}
            if nxt>=chars.len(){
                let s:String=chars[start..end].iter().collect(); if !s.trim().is_empty(){sentences.push(s.trim().to_string());} start=end; break;
            }
            // must be whitespace after terminator (end< nxt) to be boundary
            if end==nxt{ i=end; continue; }
            let next_c=chars[nxt];
