            }
            let s:String=chars[start..end].iter().collect(); if !s.trim().is_empty(){sentences.push(s.trim().to_string());}
            start=nxt; i=nxt; continue;
        }
        i+=1;
    }
    if start<chars.len(){ let s:String=chars[start..].iter().collect(); if !s.trim().is_empty(){sentences.push(s.trim().to_string());} }
    sentences
}
